INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C1','sci',5,2,'u4',1,'풍력 발전기와 풍력 발전 모형 — 풍력 발전기는 바람으로 회전 날개를 돌려 에너지를 만듦 · 산 위나 바닷가에서 볼 수 있고 길쭉한 날개가 세 개 · 모형도 회전 날개가 달려 있어 바람이 불면 돌아가고, 바람이 셀수록 빨리 돎',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C2','sci',5,2,'u4',1,'회전 날개를 돌려 전구에 불 켜기 — 입으로 가운데를 세게 불기·빨대로 비스듬히 불기·머리 말리개 바람으로 날개를 돌림 · 날개가 빠르게 돌 때만 전구에 불이 켜짐(날개가 돌아갈 때 불을 켤 에너지가 만들어짐) · 날개에 입술·손을 가까이 대지 않고 머리 말리개에 데지 않게 조심 · 페달 밟기처럼 내 몸으로 에너지를 만드는 방법도 떠올려 봄',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C3','sci',5,2,'u4',2,'자원의 뜻 — 우리가 생활하거나 물건을 생산할 때 이용하는 물·나무·철 같은 원료 · 목마를 때 마시는 물, 책을 만드는 나무, 자동차를 만드는 철',ARRAY['[6과08-01] 우리가 생활에서 이용하는 다양한 자원을 조사하고, 자원의 유한함을 설명할 수 있다.']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C4','sci',5,2,'u4',2,'물·산림·광물 자원의 이용 — 물 자원(마시기·씻기·농사·물건 생산), 산림 자원(목재로 집·가구·종이, 버섯·잣, 생물의 보금자리), 광물 자원(석재·철근으로 건물, 철·구리로 스마트 기기, 석탄으로 에너지, 금·은 장신구) · 이용 카드를 같은 자원끼리 분류함',ARRAY['[6과08-01] 우리가 생활에서 이용하는 다양한 자원을 조사하고, 자원의 유한함을 설명할 수 있다.']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C5','sci',5,2,'u4',2,'자원의 유한성 — 물: 지구의 물 총량은 줄지 않지만 오염된 물이 다시 쓸 수 있게 되기까지 오래 걸려 쓸 수 있는 깨끗한 물은 점점 부족해짐 · 산림: 마구 베거나 숲을 농경지로 바꾸면 다시 자라는 데 오래 걸려 줄어듦 · 광물: 묻혀 있는 양이 한정되고 다시 만들어지기 어려움 · 재활용으로 되쓰는 자원이 있어도 자원이 끝없이 있는 것은 아님',ARRAY['[6과08-01] 우리가 생활에서 이용하는 다양한 자원을 조사하고, 자원의 유한함을 설명할 수 있다.']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C6','sci',5,2,'u4',2,'자원을 아껴 써야 하는 까닭 — 인구가 늘고 편리한 생활을 하려고 자원 사용량이 늘어남 · 한정된 자원을 무분별하게 쓰면 부족해지고, 지나친 사용은 환경오염·기후변화도 부름 · 자원을 조사할 때는 믿을 수 있는 출처인지 확인함',ARRAY['[6과08-01] 우리가 생활에서 이용하는 다양한 자원을 조사하고, 자원의 유한함을 설명할 수 있다.']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C7','sci',5,2,'u4',3,'에너지와 재생 에너지 — 에너지는 생물이 살아가거나 기계를 움직이는 데 필요하며 석탄·석유·태양 빛·바람·물 등 여러 자원에서 얻음 · 태양 빛·바람·물처럼 자연에서 얻고 계속 이용할 수 있는 에너지가 재생 에너지 · 석탄·석유는 쓸수록 줄어 재생 에너지가 아님',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C8','sci',5,2,'u4',3,'재생 에너지의 종류 — 태양 에너지(태양 빛을 많이 쓰고 태양열도 씀 — 태양 전지로 가로등·시계·인공위성), 풍력(바람으로 발전기), 수력(높은 곳에서 낮은 곳으로 떨어지는 물의 흐름), 해양 에너지(밀물과 썰물·파도·바닷물 흐름·온도 차이), 지열 에너지(땅속 깊은 곳의 열 — 사계절 온도가 거의 같아 냉난방에), 바이오 에너지(나무·풀·가축의 분뇨·음식물 쓰레기)',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C9','sci',5,2,'u4',3,'지역에 알맞은 재생 에너지 — 재생 에너지는 날씨와 지형의 영향을 많이 받음 · 바람이 센 섬·바닷가·산 위는 풍력, 햇빛이 강한 곳은 태양 에너지, 가축을 많이 기르는 곳은 바이오 에너지, 물이 세차게 흐르는 골짜기는 수력, 밀물과 썰물이 큰 바다는 해양 에너지 · 지역의 특징을 보고 고름',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C10','sci',5,2,'u4',3,'재생 에너지가 주목받는 까닭과 한계 — 석탄·석유는 양이 한정되고 대기오염·기후변화에 영향을 줌 → 재생 에너지는 자연에서 계속 얻고 환경오염에 영향을 적게 줘 주목받음 · 그러나 늘 일정한 양을 얻기 어렵고 설치 비용이 많이 들며 시설을 지을 때 생태계에 영향을 주기도 함 → 기술 발전이 필요함',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C11','sci',5,2,'u4',4,'지속가능한 에너지 이용 — 지금 세대의 필요를 채우면서 미래 세대가 쓸 에너지도 지키는 것 · 재생 에너지는 계속 쓸 수 있지만 지금은 생산량이 충분하지 않음 · 미래 세대도 깨끗한 에너지를 쓰고 기후변화에 대응하려면 지속가능하게 써야 함',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C12','sci',5,2,'u4',4,'지속가능한 예와 그렇지 않은 예 — 지속가능한 예: 냉난방 적정 온도 유지, 태양 에너지·수력·풍력 이용, 가까운 곳은 걷거나 자전거, 친환경 제품, 절약 캠페인, 여러 나라의 협력 · 그렇지 않은 예: 창문을 연 채 난방, 빈방 조명, 보지 않는 텔레비전, 가까운 거리도 늘 자동차, 석유로 얻어 이산화 탄소 발생, 에너지를 많이 쓰는 기계 · 놀이판의 사다리와 미끄럼틀로 분류함',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C13','sci',5,2,'u4',4,'에너지를 지속가능하게 이용하는 방법 — 세 갈래: 재생 가능한 자원에서 재생 에너지 얻기, 환경을 덜 오염시키고 사용량을 줄이는 친환경 기술(전기차·수소차) 개발, 일상에서 불필요한 에너지 사용 줄이기 · 학교 실천: 이동 수업 때 전등 끄기, 겨울에 교실 문 닫기, 쓰지 않는 전기 기구 플러그 뽑기',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C14','sci',5,2,'u4',5,'효율과 에너지 소비 효율 등급 — 효율이 좋다는 것은 같은 일을 하면서 에너지를 적게 쓰는 것(같은 밝기를 내며 전기를 적게 쓰는 전등) · 에너지 소비 효율 등급은 1~5등급이고 1등급에 가까울수록 효율이 높음 · 전원을 꺼도 플러그를 꽂아 두면 전기가 조금씩 쓰임(대기 전력) — 플러그 뽑기·절전 멀티탭',ARRAY['[6과08-03] 자원과 에너지의 효율적인 이용 방법에 대해 탐색하고, 생활 속에서 실천할 수 있는 다양한 사례를 공유할 수 있다.']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C15','sci',5,2,'u4',5,'자원을 효율적으로 이용하는 방법 — 물: 물 받아 쓰기, 절수 장치, 움직임 센서 수도꼭지, 빗물 저금통 · 산림: 이면지, 손수건·다회용 컵, 전자 영수증, 나무 심고 가꾸기, 목재 제품 고쳐 쓰기 · 광물: 분리배출로 재활용(혼합물의 분리), 대체 자원 개발 · 과대 포장 물건 사지 않기 · 물·산림·광물을 함께 따짐',ARRAY['[6과08-03] 자원과 에너지의 효율적인 이용 방법에 대해 탐색하고, 생활 속에서 실천할 수 있는 다양한 사례를 공유할 수 있다.']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C16','sci',5,2,'u4',5,'에너지를 효율적으로 이용하는 방법 — 1등급에 가까운 제품·LED 조명 쓰기, 절전 기능·플러그 뽑기·알맞은 냉난방 온도 같은 절약 습관, 태양 에너지·지열 에너지 같은 재생 에너지 쓰기, 외벽·지붕·창틀 단열로 열 손실 줄이기 · 효율적으로 쓰면 돈도 아끼고 환경도 지킴',ARRAY['[6과08-03] 자원과 에너지의 효율적인 이용 방법에 대해 탐색하고, 생활 속에서 실천할 수 있는 다양한 사례를 공유할 수 있다.']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C17','sci',5,2,'u4',6,'집 모형 실험 설계 — 크기·모양이 같은 집 모형 두 개 · 둘 다 창문 안쪽에 뽁뽁이 한 장, 한 개에만 한 장 더 붙이고 우드록·색점토로 단열하고 틈을 막음 · 두 집 지붕에 탐침 온도계를 꽂고 미리 데운 같은 손난로를 넣어 5분 데운 뒤, 손난로를 빼고 1분 간격으로 5번 잼 · 탐침 끝은 바닥에 닿지 않게 공기 온도를 재고 뾰족한 끝은 사람을 향하지 않게 · 단열 말고 다른 조건은 같게',ARRAY['[6과08-03] 자원과 에너지의 효율적인 이용 방법에 대해 탐색하고, 생활 속에서 실천할 수 있는 다양한 사례를 공유할 수 있다.']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C18','sci',5,2,'u4',6,'집 모형 결과 해석 — 온도 변화량은 처음 온도에서 5분 뒤 온도를 뺀 값 · 단열한 집이 온도 변화가 더 작음 → 집 안 온도를 잘 지켜 에너지 효율이 더 높음 · 처음 온도가 다르면 마지막 온도가 아니라 변화량으로 견줌',ARRAY['[6과08-03] 자원과 에너지의 효율적인 이용 방법에 대해 탐색하고, 생활 속에서 실천할 수 있는 다양한 사례를 공유할 수 있다.']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C19','sci',5,2,'u4',6,'집에서 에너지를 효율적으로 이용하는 방법 — 열이 빠져나가지 않게 막기: 단열재, 이중창·삼중창, 햇빛 방향에 따라 움직이는 차양, 실내 온도를 지키는 열 교환기, 옥상 정원 · 에너지를 직접 만들기: 태양 빛으로 전기, 땅속 열로 냉난방 · 불 끄는 날(어스아워)처럼 절약을 함께 실천함',ARRAY['[6과08-03] 자원과 에너지의 효율적인 이용 방법에 대해 탐색하고, 생활 속에서 실천할 수 있는 다양한 사례를 공유할 수 있다.']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C20','sci',5,2,'u4',7,'실천 영상 만들고 나누기 — 생활에서 실제로 할 수 있는 방법(양치 컵, 음식 남기지 않기, 분리배출, 쓰지 않는 전원 끄기, 대중교통·자전거)을 주제로 정함 · 감독·대본·촬영·소품 역할을 나누고 장면을 스토리 보드에 글과 그림으로 · 남을 비하하거나 불쾌한 내용·개인 정보는 넣지 않고 안전한 곳에서 찍으며 소품은 재활용품으로 · 공유하고 바르고 고운 말로 댓글, 나부터 꾸준히 실천',ARRAY['[6과08-03] 자원과 에너지의 효율적인 이용 방법에 대해 탐색하고, 생활 속에서 실천할 수 있는 다양한 사례를 공유할 수 있다.']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C21','sci',5,2,'u4',8,'미래 에너지 전문가 — 재생 에너지 전문가: 재생 에너지원을 연구해 더 좋은 태양 전지·풍력 발전기를 만들고, 알맞은 설치 장소를 찾고, 중요성을 알림 · 에너지 하베스팅(수확) 전문가: 새어 나오는 조명 빛, 자동차의 떨림, 뜨거운 물의 열, 걸을 때 누르는 힘, 체온처럼 버려지는 에너지를 모아 쓰는 방법을 연구 · 놀이터 바닥·그네 같은 아이디어',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u4-C22','sci',5,2,'u4',8,'자원과 에너지 정리 — 물·산림·광물 자원은 한정되어 아껴 써야 함 · 재생 에너지·친환경 기술·절약으로 에너지를 지속가능하게 씀 · 1등급 제품·단열·재활용·빗물 재사용으로 자원과 에너지를 효율적으로 쓰고 생활에서 실천함',ARRAY['[6과08-03] 자원과 에너지의 효율적인 이용 방법에 대해 탐색하고, 생활 속에서 실천할 수 있는 다양한 사례를 공유할 수 있다.']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X01','sci',5,'u4',ARRAY['SC5-2-u4-C2']::text[],'회전 날개가 천천히 돌거나 멈춰 있어도 전구에 불이 켜진다고 여긴다','빠르게 돌 때만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X02','sci',5,'u4',ARRAY['SC5-2-u4-C2']::text[],'바람을 약하게, 날개 끝에 불수록 날개가 잘 돌아 불이 잘 켜진다고 여긴다','가운데를 세게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X03','sci',5,'u4',ARRAY['SC5-2-u4-C1']::text[],'풍력 발전기가 바람 없이도 돈다고 여기거나 모형과의 공통점을 겉모습에서만 찾는다','바람으로 날개가 돌아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X04','sci',5,'u4',ARRAY['SC5-2-u4-C2']::text[],'날개에 입술·손을 바짝 대거나 머리 말리개를 몸 가까이 대는 등 안전을 놓친다','입술·손은 멀리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X05','sci',5,'u4',ARRAY['SC5-2-u4-C3']::text[],'자원을 물건을 만드는 원료가 아닌 엉뚱한 것(쓰레기·날씨·기계)으로 여긴다','생활과 생산에 쓰는 원료') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X06','sci',5,'u4',ARRAY['SC5-2-u4-C4']::text[],'자원을 이용하는 모습과 자원의 종류를 바꾸어 분류한다(종이컵을 광물, 석탄을 산림으로)','물 · 나무 · 땅속 광물') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X07','sci',5,'u4',ARRAY['SC5-2-u4-C5']::text[],'물을 쓰면 지구의 물 총량이 줄어든다고 여긴다','총량은 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X08','sci',5,'u4',ARRAY['SC5-2-u4-C5']::text[],'물은 돌고 도니 사람이 쓸 수 있는 깨끗한 물도 줄지 않는다고 여긴다','깨끗해지기까지 오래 걸려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X09','sci',5,'u4',ARRAY['SC5-2-u4-C5']::text[],'나무는 다시 자라니 마구 베어도 산림 자원이 줄지 않는다고 여긴다','다시 자라는 데 오래') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X10','sci',5,'u4',ARRAY['SC5-2-u4-C5']::text[],'광물 자원은 캐내어 써도 곧 다시 만들어진다고 여긴다','묻힌 양이 한정') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X11','sci',5,'u4',ARRAY['SC5-2-u4-C5','SC5-2-u4-C6']::text[],'재활용·순환되는 사례를 보고 자원이 끝없이 있다고 여긴다','재활용해도 한정') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X12','sci',5,'u4',ARRAY['SC5-2-u4-C6']::text[],'찾은 자료를 출처를 확인하지 않고 그대로 믿고 쓴다','믿을 수 있는 출처') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X13','sci',5,'u4',ARRAY['SC5-2-u4-C7']::text[],'석탄·석유를 재생 에너지로 여기거나 태양 빛·바람도 쓰면 줄어든다고 여긴다','자연에서 계속') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X14','sci',5,'u4',ARRAY['SC5-2-u4-C8']::text[],'재생 에너지 이름과 얻는 방법을 바꾸어 짝짓는다(수력을 밀물과 썰물로, 해양 에너지를 계곡 물로)','떨어지는 물 수력 · 바다 해양') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X15','sci',5,'u4',ARRAY['SC5-2-u4-C8']::text[],'태양 에너지는 태양의 뜨거운 열만 이용한다고 여긴다','빛을 많이 써요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X16','sci',5,'u4',ARRAY['SC5-2-u4-C8']::text[],'지열 에너지를 땅 위 햇볕의 열로 여기거나 땅속 온도가 계절마다 크게 변한다고 여긴다','땅속 깊은 곳 · 사계절 비슷') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X17','sci',5,'u4',ARRAY['SC5-2-u4-C8']::text[],'바이오 에너지의 재료를 놓친다(석탄·쇠붙이라고 여긴다)','식물 · 가축 분뇨 · 음식물 쓰레기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X18','sci',5,'u4',ARRAY['SC5-2-u4-C9']::text[],'지역의 특징과 맞지 않는 재생 에너지를 고른다','그 지역에 많은 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X19','sci',5,'u4',ARRAY['SC5-2-u4-C10']::text[],'재생 에너지는 날씨와 상관없이 늘 같은 양을 얻고 비용·문제가 전혀 없다고 여긴다','날씨 · 비용 · 기술') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X20','sci',5,'u4',ARRAY['SC5-2-u4-C10']::text[],'재생 에너지가 주목받는 까닭을 고갈·오염이 아닌 엉뚱한 것(모양·크기)에서 찾거나 오히려 오염을 많이 낸다고 여긴다','계속 · 깨끗하게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X21','sci',5,'u4',ARRAY['SC5-2-u4-C7','SC5-2-u4-C10']::text[],'석탄·석유를 자연에서 끝없이 얻을 수 있고 환경에도 문제가 없다고 여긴다','쓸수록 줄어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X22','sci',5,'u4',ARRAY['SC5-2-u4-C11']::text[],'지속가능을 지금 세대가 마음껏 쓰는 것으로 여기고 미래 세대를 놓친다','미래 세대도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X23','sci',5,'u4',ARRAY['SC5-2-u4-C12']::text[],'에너지를 낭비하는 예를 지속가능하게 이용하는 예로 분류한다','불필요하게 쓰나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X24','sci',5,'u4',ARRAY['SC5-2-u4-C13']::text[],'지속가능하게 이용하는 방법을 한 가지로만 좁힌다(절약만, 또는 재생 에너지만)','재생 · 기술 · 절약 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X25','sci',5,'u4',ARRAY['SC5-2-u4-C14']::text[],'전원을 끄면 플러그를 꽂아 두어도 전기가 전혀 쓰이지 않는다고 여긴다','꽂혀 있으면 조금씩') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X26','sci',5,'u4',ARRAY['SC5-2-u4-C14']::text[],'효율이 높다는 것을 에너지를 많이 쓰거나 세게 작동하는 것으로 여긴다','같은 일에 적게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X27','sci',5,'u4',ARRAY['SC5-2-u4-C14']::text[],'에너지 소비 효율 등급 숫자가 클수록 효율이 높다고 여긴다','1등급에 가까울수록') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X28','sci',5,'u4',ARRAY['SC5-2-u4-C15']::text[],'자원을 낭비하는 행동(과대 포장 구입·일회용품·짧은 거리 자동차·물 틀어 놓기)을 효율적인 방법으로 고른다','덜 쓰고 다시 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X29','sci',5,'u4',ARRAY['SC5-2-u4-C16']::text[],'에너지 생산을 줄이고 사용을 늘리면 효율적이라고 여긴다','같은 일에 덜 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X30','sci',5,'u4',ARRAY['SC5-2-u4-C15']::text[],'물·산림·광물 자원을 아끼는 방법을 서로 바꾸어 짝짓는다(빗물 저금통을 광물, 분리배출을 물)','어떤 자원을 아끼나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X31','sci',5,'u4',ARRAY['SC5-2-u4-C17']::text[],'집 모형 실험에서 같게 할 조건(크기·손난로·재는 시간)을 다르게 한다','단열만 다르게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X32','sci',5,'u4',ARRAY['SC5-2-u4-C17']::text[],'탐침 끝을 바닥에 닿게 하거나 손난로를 뺄 때 문을 활짝 여는 등 측정을 흐트러뜨린다','공기 온도 · 살짝 열기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X33','sci',5,'u4',ARRAY['SC5-2-u4-C18']::text[],'온도 변화가 더 큰 집이 에너지 효율이 더 높다고 여긴다','덜 변한 집') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X34','sci',5,'u4',ARRAY['SC5-2-u4-C18']::text[],'처음 온도가 다른데 마지막 온도만 견주거나 온도 변화량을 잘못 구한다','처음 − 나중') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X35','sci',5,'u4',ARRAY['SC5-2-u4-C19']::text[],'열을 막는 방법과 에너지를 만드는 방법을 바꾸어 분류한다(이중창이 전기를 만든다고)','막기 · 만들기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X36','sci',5,'u4',ARRAY['SC5-2-u4-C19']::text[],'단열재가 스스로 열을 내 집을 데운다고 여긴다','막아서 지킬 뿐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X37','sci',5,'u4',ARRAY['SC5-2-u4-C20']::text[],'생활에서 실천할 수 없거나 자원·에너지와 상관없는 내용을 실천 영상 주제로 고른다','내가 할 수 있는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X38','sci',5,'u4',ARRAY['SC5-2-u4-C20']::text[],'영상에 개인 정보·남을 비하하는 내용을 넣거나 위험한 곳에서 찍고 댓글을 함부로 쓴다','지키고 존중하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X39','sci',5,'u4',ARRAY['SC5-2-u4-C20']::text[],'영상을 한 번 만들어 올리면 실천은 끝났다고 여긴다','꾸준히') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X40','sci',5,'u4',ARRAY['SC5-2-u4-C21']::text[],'에너지 하베스팅을 버려지는 에너지 모으기가 아닌 새 발전소 짓기·석탄 더 캐기로 여긴다','버려지는 에너지 모으기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X41','sci',5,'u4',ARRAY['SC5-2-u4-C21']::text[],'재생 에너지 전문가가 하는 일을 엉뚱하게(석유를 더 쓰게 하는 일로) 여긴다','재생 에너지를 더 잘') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u4-X42','sci',5,'u4',ARRAY['SC5-2-u4-C22']::text[],'재생 에너지가 있으니 자원과 에너지를 아낄 필요가 없다고 여긴다','아끼기도 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_basic#1','sci',5,2,'u4','L01','g5_2_sci_u4_L01_basic','lesson_basic','SC5-2-u4-C1',1,'mc','auto','풍력 발전기는 무엇의 힘으로 회전 날개를 돌리나요?',ARRAY['SC5-2-u4-X03']::text[],false,'{"seq":1,"concept":"SC5-2-u4-C1","difficulty":1,"kind":"mc","stem":"풍력 발전기는 무엇의 힘으로 회전 날개를 돌리나요?","options":[{"t":"바람","correct":true},{"t":"햇빛","mis":"SC5-2-u4-X03"},{"t":"땅속의 열","mis":"SC5-2-u4-X03"},{"t":"밀물과 썰물","mis":"SC5-2-u4-X03"}],"explanation":["풍력 발전기예요.","날개가 돌아요.","바람의 힘이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_basic#2','sci',5,2,'u4','L01','g5_2_sci_u4_L01_basic','lesson_basic','SC5-2-u4-C2',1,'ox','auto','풍력 발전 모형의 회전 날개가 빠르게 돌아갈 때 전구에 불이 켜져요.',ARRAY['SC5-2-u4-X01']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C2","difficulty":1,"kind":"ox","stem":"풍력 발전 모형의 회전 날개가 빠르게 돌아갈 때 전구에 불이 켜져요.","answer":"O","reason_options":[{"t":"날개가 돌아갈 때 불을 켤 에너지가 만들어지기 때문에","correct":true},{"t":"날개가 멈춰 있을 때 에너지가 가장 많기 때문에","mis":"SC5-2-u4-X01"}],"mis":"SC5-2-u4-X01","explanation":["날개가 돌아요.","에너지가 만들어져요.","불이 켜져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_basic#3','sci',5,2,'u4','L01','g5_2_sci_u4_L01_basic','lesson_basic','SC5-2-u4-C2',1,'mc','auto','풍력 발전 모형의 회전 날개를 돌리는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X01','SC5-2-u4-X03']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C2","difficulty":1,"kind":"mc","stem":"풍력 발전 모형의 회전 날개를 돌리는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"머리 말리개 바람을 날개에 보낸다","correct":true},{"t":"날개를 손가락으로 붙잡고 있는다","mis":"SC5-2-u4-X01"},{"t":"모형을 바람이 없는 상자 안에 둔다","mis":"SC5-2-u4-X03"},{"t":"전구를 손으로 감싼다","mis":"SC5-2-u4-X01"}],"explanation":["바람이 필요해요.","머리 말리개도 바람을 내요.","날개가 돌아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_basic#4','sci',5,2,'u4','L01','g5_2_sci_u4_L01_basic','lesson_basic','SC5-2-u4-C1',1,'sa','auto','바람으로 회전 날개를 돌려 에너지를 만드는 장치를 무엇이라고 하나요? 다섯 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-2-u4-C1","difficulty":1,"kind":"sa","stem":"바람으로 회전 날개를 돌려 에너지를 만드는 장치를 무엇이라고 하나요? 다섯 글자로 쓰세요.","answer":["풍력발전기","풍력 발전기"],"explanation":["바람의 힘을 써요.","다섯 글자예요.","풍력 발전기예요."],"mis":"SC5-2-u4-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_basic#5','sci',5,2,'u4','L01','g5_2_sci_u4_L01_basic','lesson_basic','SC5-2-u4-C1',2,'mc','auto','풍력 발전기와 풍력 발전 모형의 같은 점으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X03']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C1","difficulty":2,"kind":"mc","stem":"풍력 발전기와 풍력 발전 모형의 같은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"회전 날개가 달려 있어 바람이 불면 돌아간다","correct":true},{"t":"둘 다 산 위에만 세운다","mis":"SC5-2-u4-X03"},{"t":"둘 다 크기가 아주 크다","mis":"SC5-2-u4-X03"},{"t":"둘 다 바람 없이 스스로 돈다","mis":"SC5-2-u4-X03"}],"explanation":["둘 다 날개가 있어요.","바람이 불면 돌아요.","그게 같은 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_basic#6','sci',5,2,'u4','L01','g5_2_sci_u4_L01_basic','lesson_basic','SC5-2-u4-C2',2,'mc','auto','입으로 바람을 불어 전구에 불을 켤 때 알맞은 방법은 어느 것인가요?',ARRAY['SC5-2-u4-X02','SC5-2-u4-X04']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C2","difficulty":2,"kind":"mc","stem":"입으로 바람을 불어 전구에 불을 켤 때 알맞은 방법은 어느 것인가요?","options":[{"t":"날개 가운데 부분을 세게 분다","correct":true},{"t":"날개 끝을 살살 분다","mis":"SC5-2-u4-X02"},{"t":"날개에 입술을 대고 분다","mis":"SC5-2-u4-X04"},{"t":"전구에 대고 분다","mis":"SC5-2-u4-X02"}],"explanation":["가운데를 불어요.","세게 불어요.","날개가 빨리 돌아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_basic#7','sci',5,2,'u4','L01','g5_2_sci_u4_L01_basic','lesson_basic','SC5-2-u4-C2',2,'ox','auto','머리 말리개로 날개를 돌릴 때는 뜨거운 바람에 데지 않게 조심해야 해요.',ARRAY['SC5-2-u4-X04']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C2","difficulty":2,"kind":"ox","stem":"머리 말리개로 날개를 돌릴 때는 뜨거운 바람에 데지 않게 조심해야 해요.","answer":"O","reason_options":[{"t":"머리 말리개의 바람과 몸체가 뜨거울 수 있기 때문에","correct":true},{"t":"머리 말리개는 아무리 가까이 대도 안전하기 때문에","mis":"SC5-2-u4-X04"}],"mis":"SC5-2-u4-X04","explanation":["바람이 뜨거워요.","데일 수 있어요.","조심해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_basic#8','sci',5,2,'u4','L01','g5_2_sci_u4_L01_basic','lesson_basic','SC5-2-u4-C2',2,'mc','auto','풍력 발전 모형 놀이 기록 ㉠에서 전구에 불이 켜지지 않은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X02','SC5-2-u4-X01']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C2","difficulty":2,"kind":"mc","stem":"풍력 발전 모형 놀이 기록 ㉠에서 전구에 불이 켜지지 않은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"날개가 천천히 돌아 불을 켤 만큼 에너지가 만들어지지 않아서","correct":true},{"t":"입으로 불면 언제나 불이 켜지지 않아서","mis":"SC5-2-u4-X02"},{"t":"날개가 돌면 전구가 꺼지기 때문이라서","mis":"SC5-2-u4-X01"},{"t":"바람이 너무 세서","mis":"SC5-2-u4-X02"}],"explanation":["살살 불었어요.","날개가 천천히 돌아요.","에너지가 모자라요."],"asset":{"type":"passage","lines":["㉠ 입으로 살살 불기 — 날개가 천천히 돎 · 전구 꺼짐","㉡ 입으로 가운데를 세게 불기 — 날개가 빠르게 돎 · 전구 켜짐","㉢ 빨대로 날개 면을 비스듬히 불기 — 날개가 빠르게 돎 · 전구 켜짐","㉣ 머리 말리개 바람 보내기 — 날개가 아주 빠르게 돎 · 전구 밝게 켜짐"],"title":"풍력 발전 모형 놀이 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_basic#9','sci',5,2,'u4','L01','g5_2_sci_u4_L01_basic','lesson_basic','SC5-2-u4-C2',2,'mc','auto','빨대로 바람을 불 때 날개가 잘 돌게 하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X02','SC5-2-u4-X04']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C2","difficulty":2,"kind":"mc","stem":"빨대로 바람을 불 때 날개가 잘 돌게 하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"빨대 끝을 날개 면 쪽으로 향하게 해 비스듬히 분다","correct":true},{"t":"빨대를 날개 반대쪽으로 향하게 해 분다","mis":"SC5-2-u4-X02"},{"t":"빨대로 날개를 콕콕 찌른다","mis":"SC5-2-u4-X04"},{"t":"빨대를 모형 아래 바닥에 대고 분다","mis":"SC5-2-u4-X02"}],"explanation":["날개 면을 향해요.","비스듬히 불어요.","잘 돌아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_basic#10','sci',5,2,'u4','L01','g5_2_sci_u4_L01_basic','lesson_basic','SC5-2-u4-C2',3,'error','auto','풍력 발전 모형 놀이를 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X02','SC5-2-u4-X01']::text[],false,'{"seq":10,"concept":"SC5-2-u4-C2","difficulty":3,"kind":"error","stem":"풍력 발전 모형 놀이를 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「바람을 약하게 불수록 전구가 더 밝게 켜져.」","correct":true,"mis_target":"SC5-2-u4-X02"},{"t":"하준 — 「머리 말리개를 쓰니 날개가 더 빨리 돌았어.」","mis":"SC5-2-u4-X02"},{"t":"채린 — 「날개가 멈추니 불이 꺼졌어.」","mis":"SC5-2-u4-X01"}],"explanation":["세게 불어야 해요.","날개가 빨리 돌아야 해요.","서윤의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_challenge#1','sci',5,2,'u4','L01','g5_2_sci_u4_L01_challenge','lesson_challenge','SC5-2-u4-C2',2,'match','auto','바람을 보내는 방법과 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u4-C2","difficulty":2,"kind":"match","stem":"바람을 보내는 방법과 결과를 알맞게 이으세요.","pairs":[{"l":"입으로 살살 불기","r":"날개가 천천히 돌아 불이 안 켜짐"},{"l":"입으로 세게 불기","r":"날개가 빠르게 돌아 불이 켜짐"},{"l":"머리 말리개 바람","r":"날개가 아주 빠르게 돌아 밝게 켜짐"}],"mis":"SC5-2-u4-X02","explanation":["바람 세기를 봐요.","날개 빠르기가 달라요.","불도 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_challenge#2','sci',5,2,'u4','L01','g5_2_sci_u4_L01_challenge','lesson_challenge','SC5-2-u4-C1',2,'mc','auto','산 위에 있는 풍력 발전기 회전 날개의 특징으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X03']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C1","difficulty":2,"kind":"mc","stem":"산 위에 있는 풍력 발전기 회전 날개의 특징으로 알맞은 것은 어느 것인가요?","options":[{"t":"길쭉한 날개가 세 개 달려 있다","correct":true},{"t":"날개가 하나도 없다","mis":"SC5-2-u4-X03"},{"t":"날개가 손바닥만큼 짧다","mis":"SC5-2-u4-X03"},{"t":"날개가 땅속에 묻혀 있다","mis":"SC5-2-u4-X03"}],"explanation":["날개가 길어요.","세 개예요.","바람을 잘 받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_challenge#3','sci',5,2,'u4','L01','g5_2_sci_u4_L01_challenge','lesson_challenge','SC5-2-u4-C2',3,'mc','auto','풍력 발전 모형 놀이 기록 ㉡~㉣을 보고 알 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X01','SC5-2-u4-X02','SC5-2-u4-X03']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C2","difficulty":3,"kind":"mc","stem":"풍력 발전 모형 놀이 기록 ㉡~㉣을 보고 알 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"날개가 빠르게 돌수록 전구에 불이 잘 켜진다","correct":true},{"t":"날개가 돌지 않을 때 불이 가장 밝다","mis":"SC5-2-u4-X01"},{"t":"어떤 방법이든 날개 빠르기는 같다","mis":"SC5-2-u4-X02"},{"t":"전구는 바람의 색에 따라 켜진다","mis":"SC5-2-u4-X03"}],"explanation":["빠르게 돌았어요.","불이 켜졌어요.","빠를수록 잘 켜져요."],"asset":{"type":"passage","lines":["㉠ 입으로 살살 불기 — 날개가 천천히 돎 · 전구 꺼짐","㉡ 입으로 가운데를 세게 불기 — 날개가 빠르게 돎 · 전구 켜짐","㉢ 빨대로 날개 면을 비스듬히 불기 — 날개가 빠르게 돎 · 전구 켜짐","㉣ 머리 말리개 바람 보내기 — 날개가 아주 빠르게 돎 · 전구 밝게 켜짐"],"title":"풍력 발전 모형 놀이 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_challenge#4','sci',5,2,'u4','L01','g5_2_sci_u4_L01_challenge','lesson_challenge','SC5-2-u4-C2',3,'mc','auto','전구에 불을 켜려고 날개를 빨리 돌리는 데 힘이 많이 들었어요. 이것으로 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-2-u4-X01','SC5-2-u4-X03','SC5-2-u4-X02']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C2","difficulty":3,"kind":"mc","stem":"전구에 불을 켜려고 날개를 빨리 돌리는 데 힘이 많이 들었어요. 이것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"전구에 불을 켜는 데 큰 에너지가 필요하다","correct":true},{"t":"전구는 에너지 없이도 켜진다","mis":"SC5-2-u4-X01"},{"t":"바람은 에너지를 만들 수 없다","mis":"SC5-2-u4-X03"},{"t":"약한 바람이 에너지를 가장 많이 만든다","mis":"SC5-2-u4-X02"}],"explanation":["힘이 많이 들었어요.","에너지가 많이 필요해요.","불 켜기는 쉽지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_challenge#5','sci',5,2,'u4','L01','g5_2_sci_u4_L01_challenge','lesson_challenge','SC5-2-u4-C1',3,'ox','auto','바람이 전혀 불지 않는 날에도 풍력 발전기는 에너지를 많이 만들어요.',ARRAY['SC5-2-u4-X03']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C1","difficulty":3,"kind":"ox","stem":"바람이 전혀 불지 않는 날에도 풍력 발전기는 에너지를 많이 만들어요.","answer":"X","reason_options":[{"t":"바람이 불어 날개가 돌아야 에너지가 만들어지기 때문에","correct":true},{"t":"풍력 발전기는 바람 없이 스스로 날개를 돌리기 때문에","mis":"SC5-2-u4-X03"}],"mis":"SC5-2-u4-X03","explanation":["바람이 없어요.","날개가 안 돌아요.","에너지를 못 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_challenge#6','sci',5,2,'u4','L01','g5_2_sci_u4_L01_challenge','lesson_challenge','SC5-2-u4-C2',3,'error','auto','안전하게 놀이를 하는지 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X04','SC5-2-u4-X02']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C2","difficulty":3,"kind":"error","stem":"안전하게 놀이를 하는지 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「날개에 입술을 바짝 대고 불어야 잘 돌아.」","correct":true,"mis_target":"SC5-2-u4-X04"},{"t":"지아 — 「머리 말리개는 몸에서 떨어뜨려 써.」","mis":"SC5-2-u4-X04"},{"t":"은호 — 「가운데를 세게 부니 불이 켜졌어.」","mis":"SC5-2-u4-X02"}],"explanation":["입술은 멀리해요.","날개가 돌면 다쳐요.","도윤의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_challenge#7','sci',5,2,'u4','L01','g5_2_sci_u4_L01_challenge','lesson_challenge','SC5-2-u4-C2',3,'mc','auto','풍력 발전 모형의 전구가 날개가 돌 때만 켜지는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X01','SC5-2-u4-X02','SC5-2-u4-X03']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C2","difficulty":3,"kind":"mc","stem":"풍력 발전 모형의 전구가 날개가 돌 때만 켜지는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"날개가 돌아가는 동안 불을 켤 에너지가 만들어지기 때문이다","correct":true},{"t":"전구 속에 에너지가 미리 가득 들어 있기 때문이다","mis":"SC5-2-u4-X01"},{"t":"날개가 멈추면 바람이 더 세지기 때문이다","mis":"SC5-2-u4-X02"},{"t":"모형이 햇빛을 받아야 켜지기 때문이다","mis":"SC5-2-u4-X03"}],"explanation":["날개가 돌아요.","에너지가 생겨요.","그때만 켜져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_challenge#8','sci',5,2,'u4','L01','g5_2_sci_u4_L01_challenge','lesson_challenge','SC5-2-u4-C2',4,'mc','auto','내 몸을 움직여 에너지를 만들 수 있을 것 같은 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X01','SC5-2-u4-X03']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C2","difficulty":4,"kind":"mc","stem":"내 몸을 움직여 에너지를 만들 수 있을 것 같은 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자전거 페달을 힘차게 밟아 바퀴에 단 장치를 돌린다","correct":true},{"t":"가만히 앉아 눈을 감고 있는다","mis":"SC5-2-u4-X01"},{"t":"전구를 냉장고에 넣어 둔다","mis":"SC5-2-u4-X03"},{"t":"모형의 날개를 손으로 꽉 잡는다","mis":"SC5-2-u4-X01"}],"explanation":["몸을 움직여요.","바퀴가 돌아요.","에너지를 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_challenge#9','sci',5,2,'u4','L01','g5_2_sci_u4_L01_challenge','lesson_challenge','SC5-2-u4-C1',4,'mc','auto','풍력 발전기를 세우기에 가장 알맞은 곳은 어느 것인가요?',ARRAY['SC5-2-u4-X03']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C1","difficulty":4,"kind":"mc","stem":"풍력 발전기를 세우기에 가장 알맞은 곳은 어느 것인가요?","options":[{"t":"바람이 세고 자주 부는 바닷가 언덕","correct":true},{"t":"바람이 거의 없는 좁은 골목","mis":"SC5-2-u4-X03"},{"t":"사방이 막힌 지하 주차장","mis":"SC5-2-u4-X03"},{"t":"높은 건물로 둘러싸인 작은 마당","mis":"SC5-2-u4-X03"}],"explanation":["바람이 필요해요.","세고 자주 불어야 해요.","바닷가 언덕이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L01_challenge#10','sci',5,2,'u4','L01','g5_2_sci_u4_L01_challenge','lesson_challenge','SC5-2-u4-C2',4,'essay','teacher','풍력 발전 모형의 전구를 더 밝게 켜는 방법을 하나 생각해 쓰고, 그렇게 생각한 까닭을 날개가 도는 빠르기와 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u4-C2","difficulty":4,"kind":"essay","stem":"풍력 발전 모형의 전구를 더 밝게 켜는 방법을 하나 생각해 쓰고, 그렇게 생각한 까닭을 날개가 도는 빠르기와 함께 쓰세요.","answer_guide":{"answer":"예: 머리 말리개 바람을 날개 가운데에 똑바로 보낸다. 바람이 세면 날개가 더 빠르게 돌아 전구를 켤 에너지가 더 많이 만들어지기 때문이다.","scoring_points":["방법을 하나 썼는가","날개가 더 빠르게 돈다고 썼는가","에너지가 더 많이 만들어진다는 까닭을 썼는가"]},"explanation":["바람을 세게 해요.","날개가 빨라져요.","불이 밝아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_basic#1','sci',5,2,'u4','L02','g5_2_sci_u4_L02_basic','lesson_basic','SC5-2-u4-C3',1,'mc','auto','책을 만들 때 쓰는 나무처럼 생활하거나 물건을 만들 때 이용하는 원료를 무엇이라고 하나요?',ARRAY['SC5-2-u4-X05']::text[],false,'{"seq":1,"concept":"SC5-2-u4-C3","difficulty":1,"kind":"mc","stem":"책을 만들 때 쓰는 나무처럼 생활하거나 물건을 만들 때 이용하는 원료를 무엇이라고 하나요?","options":[{"t":"자원","correct":true},{"t":"쓰레기","mis":"SC5-2-u4-X05"},{"t":"날씨","mis":"SC5-2-u4-X05"},{"t":"기계","mis":"SC5-2-u4-X05"}],"explanation":["나무는 원료예요.","물건을 만들어요.","자원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_basic#2','sci',5,2,'u4','L02','g5_2_sci_u4_L02_basic','lesson_basic','SC5-2-u4-C3',1,'sa','auto','우리가 생활하거나 물건을 생산할 때 이용하는 원료를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-2-u4-C3","difficulty":1,"kind":"sa","stem":"우리가 생활하거나 물건을 생산할 때 이용하는 원료를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["자원"],"explanation":["물·나무·철이에요.","두 글자예요.","자원이에요."],"mis":"SC5-2-u4-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_basic#3','sci',5,2,'u4','L02','g5_2_sci_u4_L02_basic','lesson_basic','SC5-2-u4-C4',1,'mc','auto','종이컵이나 휴지를 만들 때 쓰는 나무는 어떤 자원인가요?',ARRAY['SC5-2-u4-X06']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C4","difficulty":1,"kind":"mc","stem":"종이컵이나 휴지를 만들 때 쓰는 나무는 어떤 자원인가요?","options":[{"t":"산림 자원","correct":true},{"t":"물 자원","mis":"SC5-2-u4-X06"},{"t":"광물 자원","mis":"SC5-2-u4-X06"},{"t":"바람 자원","mis":"SC5-2-u4-X06"}],"explanation":["나무는 숲에서 와요.","숲은 산림이에요.","산림 자원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_basic#4','sci',5,2,'u4','L02','g5_2_sci_u4_L02_basic','lesson_basic','SC5-2-u4-C5',1,'ox','auto','땅속 광물 자원은 묻혀 있는 양이 한정되어 있어요.',ARRAY['SC5-2-u4-X10']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C5","difficulty":1,"kind":"ox","stem":"땅속 광물 자원은 묻혀 있는 양이 한정되어 있어요.","answer":"O","reason_options":[{"t":"한번 쓰면 다시 만들어지기 어렵기 때문에","correct":true},{"t":"캐낸 만큼 금방 다시 생겨나기 때문에","mis":"SC5-2-u4-X10"}],"mis":"SC5-2-u4-X10","explanation":["묻힌 양이 정해져 있어요.","다시 생기기 어려워요.","한정되어 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_basic#5','sci',5,2,'u4','L02','g5_2_sci_u4_L02_basic','lesson_basic','SC5-2-u4-C4',2,'mc','auto','자원의 이용 카드에서 광물 자원을 이용하는 카드끼리 모은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X06']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C4","difficulty":2,"kind":"mc","stem":"자원의 이용 카드에서 광물 자원을 이용하는 카드끼리 모은 것은 어느 것인가요?","options":[{"t":"㉢, ㉥","correct":true},{"t":"㉠, ㉣","mis":"SC5-2-u4-X06"},{"t":"㉡, ㉤","mis":"SC5-2-u4-X06"},{"t":"㉢, ㉤","mis":"SC5-2-u4-X06"}],"explanation":["철·구리는 광물이에요.","석탄도 광물이에요.","㉢과 ㉥이에요."],"asset":{"type":"passage","lines":["㉠ 목이 말라 물을 마신다.","㉡ 숲에서 버섯을 딴다.","㉢ 철과 구리로 스마트 기기를 만든다.","㉣ 논에 물을 대어 벼를 기른다.","㉤ 나무로 책상을 만든다.","㉥ 석탄으로 에너지를 얻는다."],"title":"자원의 이용 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_basic#6','sci',5,2,'u4','L02','g5_2_sci_u4_L02_basic','lesson_basic','SC5-2-u4-C5',2,'mc','auto','물 자원에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-2-u4-X07','SC5-2-u4-X08','SC5-2-u4-X05']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C5","difficulty":2,"kind":"mc","stem":"물 자원에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"지구의 물 총량은 그대로지만 쓸 수 있는 깨끗한 물은 점점 부족해진다","correct":true},{"t":"물을 쓸 때마다 지구의 물이 사라진다","mis":"SC5-2-u4-X07"},{"t":"물은 돌고 도니 깨끗한 물도 줄지 않는다","mis":"SC5-2-u4-X08"},{"t":"물은 자원이 아니라 걱정할 필요가 없다","mis":"SC5-2-u4-X05"}],"explanation":["총량은 그대로예요.","깨끗해지려면 오래 걸려요.","깨끗한 물은 줄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_basic#7','sci',5,2,'u4','L02','g5_2_sci_u4_L02_basic','lesson_basic','SC5-2-u4-C5',2,'mc','auto','산림 자원이 줄어드는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X09']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C5","difficulty":2,"kind":"mc","stem":"산림 자원이 줄어드는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나무를 많이 베거나 숲을 농경지로 바꾸면 다시 자라는 데 오래 걸려서","correct":true},{"t":"나무는 베면 바로 다시 자라서","mis":"SC5-2-u4-X09"},{"t":"비가 많이 오면 나무가 사라져서","mis":"SC5-2-u4-X09"},{"t":"나무를 심을수록 숲이 줄어들어서","mis":"SC5-2-u4-X09"}],"explanation":["나무를 많이 베요.","다시 자라려면 오래 걸려요.","숲이 줄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_basic#8','sci',5,2,'u4','L02','g5_2_sci_u4_L02_basic','lesson_basic','SC5-2-u4-C6',2,'ox','auto','자원을 조사할 때는 찾은 자료가 믿을 수 있는 출처에서 나왔는지 확인해야 해요.',ARRAY['SC5-2-u4-X12']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C6","difficulty":2,"kind":"ox","stem":"자원을 조사할 때는 찾은 자료가 믿을 수 있는 출처에서 나왔는지 확인해야 해요.","answer":"O","reason_options":[{"t":"틀린 정보를 그대로 믿으면 잘못 알 수 있기 때문에","correct":true},{"t":"누리망에 있는 자료는 모두 정확하기 때문에","mis":"SC5-2-u4-X12"}],"mis":"SC5-2-u4-X12","explanation":["자료를 찾아요.","출처를 확인해요.","믿을 수 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_basic#9','sci',5,2,'u4','L02','g5_2_sci_u4_L02_basic','lesson_basic','SC5-2-u4-C6',2,'mc','auto','자원을 아껴 써야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X10','SC5-2-u4-X11','SC5-2-u4-X05']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C6","difficulty":2,"kind":"mc","stem":"자원을 아껴 써야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"자원의 양이 한정되어 있어 마구 쓰면 부족해지기 때문이다","correct":true},{"t":"자원은 쓸수록 더 늘어나기 때문이다","mis":"SC5-2-u4-X10"},{"t":"재활용하면 끝없이 생기기 때문이다","mis":"SC5-2-u4-X11"},{"t":"자원은 미래에는 필요 없기 때문이다","mis":"SC5-2-u4-X05"}],"explanation":["양이 한정되어 있어요.","마구 쓰면 부족해요.","아껴 써야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_basic#10','sci',5,2,'u4','L02','g5_2_sci_u4_L02_basic','lesson_basic','SC5-2-u4-C5',3,'error','auto','세 모둠의 토의 메모를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X11','SC5-2-u4-X08','SC5-2-u4-X09']::text[],false,'{"seq":10,"concept":"SC5-2-u4-C5","difficulty":3,"kind":"error","stem":"세 모둠의 토의 메모를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"나래 — 「캔을 재활용하니까 광물 자원은 끝없이 쓸 수 있어.」","correct":true,"mis_target":"SC5-2-u4-X11"},{"t":"시우 — 「더러워진 물이 깨끗해지려면 오래 걸려.」","mis":"SC5-2-u4-X08"},{"t":"다온 — 「나무가 다시 자라려면 오래 걸려.」","mis":"SC5-2-u4-X09"}],"explanation":["재활용해도 한정돼요.","끝없지 않아요.","나래의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["물 모둠 — 물은 돌고 돌지만 더러워진 물이 깨끗해지려면 오래 걸린다.","숲 모둠 — 나무를 베면 다시 자라기까지 오래 걸린다.","광물 모둠 — 땅속 광물은 묻혀 있는 양이 정해져 있다."],"title":"세 모둠의 토의 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_challenge#1','sci',5,2,'u4','L02','g5_2_sci_u4_L02_challenge','lesson_challenge','SC5-2-u4-C4',2,'match','auto','자원을 이용하는 모습과 자원의 종류를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u4-C4","difficulty":2,"kind":"match","stem":"자원을 이용하는 모습과 자원의 종류를 알맞게 이으세요.","pairs":[{"l":"논에 물을 대어 벼를 기른다","r":"물 자원"},{"l":"나무로 책상을 만든다","r":"산림 자원"},{"l":"철근으로 건물을 짓는다","r":"광물 자원"}],"mis":"SC5-2-u4-X06","explanation":["물을 써요.","나무를 써요.","철을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_challenge#2','sci',5,2,'u4','L02','g5_2_sci_u4_L02_challenge','lesson_challenge','SC5-2-u4-C3',2,'mc','auto','다음 가운데 자원이라고 할 수 있는 것은 어느 것인가요?',ARRAY['SC5-2-u4-X05']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C3","difficulty":2,"kind":"mc","stem":"다음 가운데 자원이라고 할 수 있는 것은 어느 것인가요?","options":[{"t":"자동차를 만드는 데 쓰는 철","correct":true},{"t":"하늘에 뜬 무지개","mis":"SC5-2-u4-X05"},{"t":"어젯밤에 꾼 꿈","mis":"SC5-2-u4-X05"},{"t":"친구의 웃음소리","mis":"SC5-2-u4-X05"}],"explanation":["원료를 찾아요.","철은 자동차의 원료예요.","철이 자원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_challenge#3','sci',5,2,'u4','L02','g5_2_sci_u4_L02_challenge','lesson_challenge','SC5-2-u4-C5',3,'mc','auto','세 모둠의 토의 메모를 모아 낼 수 있는 결론으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X11','SC5-2-u4-X09','SC5-2-u4-X10']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C5","difficulty":3,"kind":"mc","stem":"세 모둠의 토의 메모를 모아 낼 수 있는 결론으로 알맞은 것은 어느 것인가요?","options":[{"t":"물·산림·광물 자원은 다시 만들어지는 데 오래 걸리거나 양이 한정되어 계속 쓰기 어렵다","correct":true},{"t":"세 자원은 끝없이 있어 마음껏 써도 된다","mis":"SC5-2-u4-X11"},{"t":"물 자원만 한정되어 있다","mis":"SC5-2-u4-X09"},{"t":"광물 자원은 곧 다시 만들어진다","mis":"SC5-2-u4-X10"}],"explanation":["세 모둠 모두 오래 걸려요.","양도 정해져 있어요.","계속 쓰기 어려워요."],"asset":{"type":"passage","lines":["물 모둠 — 물은 돌고 돌지만 더러워진 물이 깨끗해지려면 오래 걸린다.","숲 모둠 — 나무를 베면 다시 자라기까지 오래 걸린다.","광물 모둠 — 땅속 광물은 묻혀 있는 양이 정해져 있다."],"title":"세 모둠의 토의 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_challenge#4','sci',5,2,'u4','L02','g5_2_sci_u4_L02_challenge','lesson_challenge','SC5-2-u4-C5',3,'mc','auto','「물은 지구를 돌고 돌아 줄지 않으니 마음껏 써도 된다.」를 바르게 고친 것은 어느 것인가요?',ARRAY['SC5-2-u4-X07','SC5-2-u4-X08']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C5","difficulty":3,"kind":"mc","stem":"「물은 지구를 돌고 돌아 줄지 않으니 마음껏 써도 된다.」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"물의 총량은 그대로지만 오염이나 기후변화로 사람이 쓸 깨끗한 물은 줄어든다","correct":true},{"t":"물은 돌지 않고 한 번 쓰면 없어진다","mis":"SC5-2-u4-X07"},{"t":"고칠 것이 없는 맞는 말이다","mis":"SC5-2-u4-X08"},{"t":"물은 바다에만 있어 사람이 쓸 수 없다","mis":"SC5-2-u4-X08"}],"explanation":["물은 돌아요.","총량은 그대로예요.","깨끗한 물이 줄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_challenge#5','sci',5,2,'u4','L02','g5_2_sci_u4_L02_challenge','lesson_challenge','SC5-2-u4-C5',3,'ox','auto','종이를 재활용하는 예가 있으니 산림 자원은 걱정 없이 마구 써도 돼요.',ARRAY['SC5-2-u4-X11']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C5","difficulty":3,"kind":"ox","stem":"종이를 재활용하는 예가 있으니 산림 자원은 걱정 없이 마구 써도 돼요.","answer":"X","reason_options":[{"t":"재활용을 해도 자원이 끝없이 있는 것은 아니기 때문에","correct":true},{"t":"재활용되는 자원은 무한하기 때문에","mis":"SC5-2-u4-X11"}],"mis":"SC5-2-u4-X11","explanation":["재활용은 좋아요.","그래도 한정돼요.","아껴 써야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_challenge#6','sci',5,2,'u4','L02','g5_2_sci_u4_L02_challenge','lesson_challenge','SC5-2-u4-C6',3,'mc','auto','오늘날 자원 사용량이 점점 늘어나는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X10','SC5-2-u4-X05','SC5-2-u4-X11']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C6","difficulty":3,"kind":"mc","stem":"오늘날 자원 사용량이 점점 늘어나는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"인구가 늘고 더 편리하게 생활하려고 자원을 많이 쓰기 때문이다","correct":true},{"t":"자원이 저절로 늘어나기 때문이다","mis":"SC5-2-u4-X10"},{"t":"사람들이 자원을 전혀 쓰지 않기 때문이다","mis":"SC5-2-u4-X05"},{"t":"자원은 쓸수록 다시 생기기 때문이다","mis":"SC5-2-u4-X11"}],"explanation":["사람이 늘어요.","편리한 생활을 해요.","많이 쓰게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_challenge#7','sci',5,2,'u4','L02','g5_2_sci_u4_L02_challenge','lesson_challenge','SC5-2-u4-C4',3,'error','auto','자원의 이용 카드를 나누며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X06']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C4","difficulty":3,"kind":"error","stem":"자원의 이용 카드를 나누며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"보미 — 「㉥ 석탄으로 에너지를 얻는 카드는 산림 자원이야.」","correct":true,"mis_target":"SC5-2-u4-X06"},{"t":"지훈 — 「㉡ 숲에서 버섯을 따는 건 산림 자원이야.」","mis":"SC5-2-u4-X06"},{"t":"예린 — 「㉣ 논에 물을 대는 건 물 자원이야.」","mis":"SC5-2-u4-X06"}],"explanation":["석탄은 땅속에서 캐요.","광물 자원이에요.","보미의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["㉠ 목이 말라 물을 마신다.","㉡ 숲에서 버섯을 딴다.","㉢ 철과 구리로 스마트 기기를 만든다.","㉣ 논에 물을 대어 벼를 기른다.","㉤ 나무로 책상을 만든다.","㉥ 석탄으로 에너지를 얻는다."],"title":"자원의 이용 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_challenge#8','sci',5,2,'u4','L02','g5_2_sci_u4_L02_challenge','lesson_challenge','SC5-2-u4-C6',4,'mc','auto','스마트 기기로 자원을 조사할 때 가장 알맞은 태도는 어느 것인가요?',ARRAY['SC5-2-u4-X12']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C6","difficulty":4,"kind":"mc","stem":"스마트 기기로 자원을 조사할 때 가장 알맞은 태도는 어느 것인가요?","options":[{"t":"믿을 수 있는 누리집 자료인지 확인하고 출처를 함께 적는다","correct":true},{"t":"가장 먼저 나온 글을 그대로 베낀다","mis":"SC5-2-u4-X12"},{"t":"출처는 지우고 내 생각처럼 쓴다","mis":"SC5-2-u4-X12"},{"t":"조사와 상관없는 놀이 누리집을 본다","mis":"SC5-2-u4-X12"}],"explanation":["자료를 살펴요.","출처를 확인해요.","함께 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_challenge#9','sci',5,2,'u4','L02','g5_2_sci_u4_L02_challenge','lesson_challenge','SC5-2-u4-C5',4,'mc','auto','지금처럼 자원을 마구 쓰면 생길 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X11','SC5-2-u4-X10','SC5-2-u4-X05']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C5","difficulty":4,"kind":"mc","stem":"지금처럼 자원을 마구 쓰면 생길 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"쓸 수 있는 자원이 부족해지고 환경오염과 기후변화도 심해질 수 있다","correct":true},{"t":"자원이 오히려 넘쳐나게 된다","mis":"SC5-2-u4-X11"},{"t":"광물 자원이 새로 빨리 만들어진다","mis":"SC5-2-u4-X10"},{"t":"아무 일도 생기지 않는다","mis":"SC5-2-u4-X05"}],"explanation":["자원은 한정돼요.","부족해져요.","환경도 나빠져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L02_challenge#10','sci',5,2,'u4','L02','g5_2_sci_u4_L02_challenge','lesson_challenge','SC5-2-u4-C6',4,'essay','teacher','물·산림·광물 자원 가운데 하나를 골라, 그 자원을 계속 마구 쓰면 어떻게 될지와 아껴 써야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u4-C6","difficulty":4,"kind":"essay","stem":"물·산림·광물 자원 가운데 하나를 골라, 그 자원을 계속 마구 쓰면 어떻게 될지와 아껴 써야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 광물 자원은 땅속에 묻힌 양이 한정되어 있고 다시 만들어지기 어렵다. 계속 마구 쓰면 언젠가 바닥나 쓸 수 없게 되므로 아끼고 분리배출해 다시 써야 한다.","scoring_points":["자원 하나를 골랐는가","한정되어 있다는 점을 썼는가","계속 쓰면 부족해진다는 결과와 아껴 쓸 까닭을 썼는가"]},"explanation":["자원을 골라요.","한정을 써요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_basic#1','sci',5,2,'u4','L03','g5_2_sci_u4_L03_basic','lesson_basic','SC5-2-u4-C7',1,'mc','auto','태양 빛·바람·물처럼 자연에서 얻고 계속 이용할 수 있는 에너지는 어느 것인가요?',ARRAY['SC5-2-u4-X13']::text[],false,'{"seq":1,"concept":"SC5-2-u4-C7","difficulty":1,"kind":"mc","stem":"태양 빛·바람·물처럼 자연에서 얻고 계속 이용할 수 있는 에너지는 어느 것인가요?","options":[{"t":"재생 에너지","correct":true},{"t":"석탄에서 얻는 에너지","mis":"SC5-2-u4-X13"},{"t":"석유에서 얻는 에너지","mis":"SC5-2-u4-X13"},{"t":"쓸수록 줄어드는 에너지","mis":"SC5-2-u4-X13"}],"explanation":["자연에서 얻어요.","계속 쓸 수 있어요.","재생 에너지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_basic#2','sci',5,2,'u4','L03','g5_2_sci_u4_L03_basic','lesson_basic','SC5-2-u4-C7',1,'sa','auto','바람처럼 자연에서 얻어 계속 쓸 수 있는 에너지를 무엇이라고 하나요? 다섯 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-2-u4-C7","difficulty":1,"kind":"sa","stem":"바람처럼 자연에서 얻어 계속 쓸 수 있는 에너지를 무엇이라고 하나요? 다섯 글자로 쓰세요.","answer":["재생에너지","재생 에너지"],"explanation":["계속 쓸 수 있어요.","다섯 글자예요.","재생 에너지예요."],"mis":"SC5-2-u4-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_basic#3','sci',5,2,'u4','L03','g5_2_sci_u4_L03_basic','lesson_basic','SC5-2-u4-C8',1,'mc','auto','높은 곳에서 낮은 곳으로 떨어지는 물의 흐름을 이용하는 재생 에너지는 어느 것인가요?',ARRAY['SC5-2-u4-X14','SC5-2-u4-X17']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C8","difficulty":1,"kind":"mc","stem":"높은 곳에서 낮은 곳으로 떨어지는 물의 흐름을 이용하는 재생 에너지는 어느 것인가요?","options":[{"t":"수력","correct":true},{"t":"해양 에너지","mis":"SC5-2-u4-X14"},{"t":"지열 에너지","mis":"SC5-2-u4-X14"},{"t":"바이오 에너지","mis":"SC5-2-u4-X17"}],"explanation":["떨어지는 물이에요.","물의 흐름을 써요.","수력이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_basic#4','sci',5,2,'u4','L03','g5_2_sci_u4_L03_basic','lesson_basic','SC5-2-u4-C8',1,'ox','auto','바람으로 발전기를 돌려 에너지를 얻는 것을 풍력이라고 해요.',ARRAY['SC5-2-u4-X14']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C8","difficulty":1,"kind":"ox","stem":"바람으로 발전기를 돌려 에너지를 얻는 것을 풍력이라고 해요.","answer":"O","reason_options":[{"t":"바람의 힘으로 발전기를 돌리기 때문에","correct":true},{"t":"땅속의 열로 발전기를 돌리기 때문에","mis":"SC5-2-u4-X14"}],"mis":"SC5-2-u4-X14","explanation":["바람을 써요.","발전기가 돌아요.","풍력이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_basic#5','sci',5,2,'u4','L03','g5_2_sci_u4_L03_basic','lesson_basic','SC5-2-u4-C8',2,'mc','auto','재생 에너지 수수께끼 카드 (가)가 가리키는 재생 에너지는 어느 것인가요?',ARRAY['SC5-2-u4-X16','SC5-2-u4-X14']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C8","difficulty":2,"kind":"mc","stem":"재생 에너지 수수께끼 카드 (가)가 가리키는 재생 에너지는 어느 것인가요?","options":[{"t":"지열 에너지","correct":true},{"t":"태양 에너지","mis":"SC5-2-u4-X16"},{"t":"해양 에너지","mis":"SC5-2-u4-X14"},{"t":"풍력","mis":"SC5-2-u4-X14"}],"explanation":["땅속 깊은 곳이에요.","온도가 거의 같아요.","지열 에너지예요."],"asset":{"type":"passage","lines":["(가) 땅속 깊은 곳에 있어. 사계절 온도가 거의 같아 냉난방을 도와.","(나) 바닷가에 살아. 밀물과 썰물이 드나드는 힘을 써.","(다) 골짜기에 살아. 높은 곳에서 떨어지는 물로 발전기를 돌려.","(라) 목장에 살아. 가축의 분뇨와 음식물 쓰레기에서 얻어."],"title":"재생 에너지 수수께끼 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
