INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_basic#7','sci',5,2,'u4','L03','g5_2_sci_u4_L03_basic','lesson_basic','SC5-2-u4-C8',2,'mc','auto','태양 에너지에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-2-u4-X15','SC5-2-u4-X16']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C8","difficulty":2,"kind":"mc","stem":"태양 에너지에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"태양 빛을 많이 이용하고 태양열을 이용하기도 한다","correct":true},{"t":"태양의 뜨거운 열만 이용한다","mis":"SC5-2-u4-X15"},{"t":"밤에만 얻을 수 있다","mis":"SC5-2-u4-X15"},{"t":"땅속에서 캐내어 얻는다","mis":"SC5-2-u4-X16"}],"explanation":["빛을 많이 써요.","열도 써요.","둘 다 이용해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_basic#8','sci',5,2,'u4','L03','g5_2_sci_u4_L03_basic','lesson_basic','SC5-2-u4-C9',2,'mc','auto','네 지역의 특징에서 ㉡ 해든 들판에 가장 알맞은 재생 에너지는 어느 것인가요?',ARRAY['SC5-2-u4-X18']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C9","difficulty":2,"kind":"mc","stem":"네 지역의 특징에서 ㉡ 해든 들판에 가장 알맞은 재생 에너지는 어느 것인가요?","options":[{"t":"태양 에너지","correct":true},{"t":"바이오 에너지","mis":"SC5-2-u4-X18"},{"t":"해양 에너지","mis":"SC5-2-u4-X18"},{"t":"수력","mis":"SC5-2-u4-X18"}],"explanation":["햇빛이 강해요.","빛을 모아요.","태양 에너지예요."],"asset":{"type":"passage","lines":["㉠ 바람솔섬 — 바다로 둘러싸여 일 년 내내 바람이 세다.","㉡ 해든 들판 — 비가 적고 햇빛이 강하게 내리쬔다.","㉢ 소울 목장 마을 — 가축이 많아 분뇨 처리가 걱정이다.","㉣ 물안개 골짜기 — 산이 깊고 물이 세차게 흘러내린다."],"title":"네 지역의 특징"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_basic#9','sci',5,2,'u4','L03','g5_2_sci_u4_L03_basic','lesson_basic','SC5-2-u4-C10',2,'ox','auto','재생 에너지는 환경오염에 영향을 적게 줘요.',ARRAY['SC5-2-u4-X20']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C10","difficulty":2,"kind":"ox","stem":"재생 에너지는 환경오염에 영향을 적게 줘요.","answer":"O","reason_options":[{"t":"자연에서 얻어 대기오염과 기후변화에 영향을 적게 주기 때문에","correct":true},{"t":"재생 에너지는 쓸수록 공기를 더럽히기 때문에","mis":"SC5-2-u4-X20"}],"mis":"SC5-2-u4-X20","explanation":["자연에서 얻어요.","오염을 적게 내요.","환경을 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_basic#10','sci',5,2,'u4','L03','g5_2_sci_u4_L03_basic','lesson_basic','SC5-2-u4-C10',3,'error','auto','재생 에너지를 조사하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X19','SC5-2-u4-X21']::text[],false,'{"seq":10,"concept":"SC5-2-u4-C10","difficulty":3,"kind":"error","stem":"재생 에너지를 조사하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하율 — 「재생 에너지는 날씨와 상관없이 늘 같은 양을 얻을 수 있어.」","correct":true,"mis_target":"SC5-2-u4-X19"},{"t":"준서 — 「석탄과 석유는 쓸수록 줄어.」","mis":"SC5-2-u4-X21"},{"t":"민아 — 「재생 에너지는 설치 비용이 많이 들기도 해.」","mis":"SC5-2-u4-X19"}],"explanation":["날씨 영향을 받아요.","양이 달라져요.","하율의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_challenge#1','sci',5,2,'u4','L03','g5_2_sci_u4_L03_challenge','lesson_challenge','SC5-2-u4-C8',2,'match','auto','에너지를 얻는 곳과 재생 에너지를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u4-C8","difficulty":2,"kind":"match","stem":"에너지를 얻는 곳과 재생 에너지를 알맞게 이으세요.","pairs":[{"l":"밀물과 썰물, 파도","r":"해양 에너지"},{"l":"땅속 깊은 곳의 열","r":"지열 에너지"},{"l":"나무, 풀, 가축의 분뇨","r":"바이오 에너지"}],"mis":"SC5-2-u4-X14","explanation":["바다는 해양이에요.","땅속은 지열이에요.","생물은 바이오예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_challenge#2','sci',5,2,'u4','L03','g5_2_sci_u4_L03_challenge','lesson_challenge','SC5-2-u4-C9',2,'mc','auto','네 지역의 특징에서 ㉣ 물안개 골짜기에 가장 알맞은 재생 에너지는 어느 것인가요?',ARRAY['SC5-2-u4-X18','SC5-2-u4-X13']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C9","difficulty":2,"kind":"mc","stem":"네 지역의 특징에서 ㉣ 물안개 골짜기에 가장 알맞은 재생 에너지는 어느 것인가요?","options":[{"t":"수력","correct":true},{"t":"바이오 에너지","mis":"SC5-2-u4-X18"},{"t":"지열 에너지","mis":"SC5-2-u4-X18"},{"t":"석유","mis":"SC5-2-u4-X13"}],"explanation":["물이 세차게 흘러요.","떨어지는 물을 써요.","수력이에요."],"asset":{"type":"passage","lines":["㉠ 바람솔섬 — 바다로 둘러싸여 일 년 내내 바람이 세다.","㉡ 해든 들판 — 비가 적고 햇빛이 강하게 내리쬔다.","㉢ 소울 목장 마을 — 가축이 많아 분뇨 처리가 걱정이다.","㉣ 물안개 골짜기 — 산이 깊고 물이 세차게 흘러내린다."],"title":"네 지역의 특징"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_challenge#3','sci',5,2,'u4','L03','g5_2_sci_u4_L03_challenge','lesson_challenge','SC5-2-u4-C9',3,'mc','auto','네 지역의 특징에서 ㉠과 ㉢에 알맞은 재생 에너지를 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X18']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C9","difficulty":3,"kind":"mc","stem":"네 지역의 특징에서 ㉠과 ㉢에 알맞은 재생 에너지를 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"㉠ 풍력, ㉢ 바이오 에너지","correct":true},{"t":"㉠ 바이오 에너지, ㉢ 풍력","mis":"SC5-2-u4-X18"},{"t":"㉠ 수력, ㉢ 태양 에너지","mis":"SC5-2-u4-X18"},{"t":"㉠ 지열 에너지, ㉢ 해양 에너지","mis":"SC5-2-u4-X18"}],"explanation":["섬은 바람이 세요.","목장은 분뇨가 많아요.","풍력과 바이오예요."],"asset":{"type":"passage","lines":["㉠ 바람솔섬 — 바다로 둘러싸여 일 년 내내 바람이 세다.","㉡ 해든 들판 — 비가 적고 햇빛이 강하게 내리쬔다.","㉢ 소울 목장 마을 — 가축이 많아 분뇨 처리가 걱정이다.","㉣ 물안개 골짜기 — 산이 깊고 물이 세차게 흘러내린다."],"title":"네 지역의 특징"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_challenge#4','sci',5,2,'u4','L03','g5_2_sci_u4_L03_challenge','lesson_challenge','SC5-2-u4-C10',3,'mc','auto','재생 에너지가 주목받는 까닭 두 가지를 바르게 모은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X21','SC5-2-u4-X19','SC5-2-u4-X20']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C10","difficulty":3,"kind":"mc","stem":"재생 에너지가 주목받는 까닭 두 가지를 바르게 모은 것은 어느 것인가요?","options":[{"t":"자연에서 계속 얻을 수 있고, 대기오염과 기후변화에 영향을 적게 준다","correct":true},{"t":"땅속에 묻힌 양이 정해져 있고, 태울수록 연기가 많이 난다","mis":"SC5-2-u4-X21"},{"t":"설치 비용이 들지 않고, 어디서나 같은 양을 얻는다","mis":"SC5-2-u4-X19"},{"t":"모양이 멋지고, 크기가 커서 눈에 잘 띈다","mis":"SC5-2-u4-X20"}],"explanation":["계속 얻어요.","환경에 좋아요.","그래서 주목받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_challenge#5','sci',5,2,'u4','L03','g5_2_sci_u4_L03_challenge','lesson_challenge','SC5-2-u4-C8',3,'mc','auto','태양 전지로 햇빛을 받아 전기를 만들어 쓰는 예로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X16','SC5-2-u4-X14','SC5-2-u4-X17']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C8","difficulty":3,"kind":"mc","stem":"태양 전지로 햇빛을 받아 전기를 만들어 쓰는 예로 알맞은 것은 어느 것인가요?","options":[{"t":"태양 전지를 단 가로등과 인공위성","correct":true},{"t":"땅속의 열로 데우는 온천","mis":"SC5-2-u4-X16"},{"t":"바람으로 돌아가는 바람개비","mis":"SC5-2-u4-X14"},{"t":"가축 분뇨로 만든 가스","mis":"SC5-2-u4-X17"}],"explanation":["햇빛을 받아요.","전기를 만들어요.","가로등과 인공위성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_challenge#6','sci',5,2,'u4','L03','g5_2_sci_u4_L03_challenge','lesson_challenge','SC5-2-u4-C8',3,'ox','auto','땅속 깊은 곳은 사계절 내내 온도가 거의 변하지 않아 냉난방에 이용할 수 있어요.',ARRAY['SC5-2-u4-X16']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C8","difficulty":3,"kind":"ox","stem":"땅속 깊은 곳은 사계절 내내 온도가 거의 변하지 않아 냉난방에 이용할 수 있어요.","answer":"O","reason_options":[{"t":"겨울에는 땅 위보다 따뜻하고 여름에는 땅 위보다 시원하기 때문에","correct":true},{"t":"땅속 온도는 여름에 가장 뜨겁고 겨울에 가장 차갑기 때문에","mis":"SC5-2-u4-X16"}],"mis":"SC5-2-u4-X16","explanation":["땅속은 온도가 비슷해요.","겨울엔 따뜻해요.","여름엔 시원해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_challenge#7','sci',5,2,'u4','L03','g5_2_sci_u4_L03_challenge','lesson_challenge','SC5-2-u4-C7',3,'error','auto','재생 에너지를 가려내며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X13']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C7","difficulty":3,"kind":"error","stem":"재생 에너지를 가려내며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「석유도 자연에서 캐내니까 재생 에너지야.」","correct":true,"mis_target":"SC5-2-u4-X13"},{"t":"가은 — 「바람은 써도 줄어들지 않아.」","mis":"SC5-2-u4-X13"},{"t":"로하 — 「에너지가 있어야 기계가 움직여.」","mis":"SC5-2-u4-X13"}],"explanation":["석유는 쓸수록 줄어요.","계속 쓸 수 없어요.","태오의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_challenge#8','sci',5,2,'u4','L03','g5_2_sci_u4_L03_challenge','lesson_challenge','SC5-2-u4-C10',4,'mc','auto','재생 에너지의 단점을 줄이는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X21','SC5-2-u4-X19','SC5-2-u4-X18']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C10","difficulty":4,"kind":"mc","stem":"재생 에너지의 단점을 줄이는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"날씨에 따라 달라지는 에너지를 모아 두는 기술과 비용을 줄이는 기술을 발전시킨다","correct":true},{"t":"재생 에너지를 모두 없애고 석탄만 쓴다","mis":"SC5-2-u4-X21"},{"t":"단점이 없으니 아무것도 하지 않는다","mis":"SC5-2-u4-X19"},{"t":"바람이 없는 곳에 풍력 발전기를 더 세운다","mis":"SC5-2-u4-X18"}],"explanation":["양이 달라져요.","비용도 들어요.","기술을 발전시켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_challenge#9','sci',5,2,'u4','L03','g5_2_sci_u4_L03_challenge','lesson_challenge','SC5-2-u4-C9',4,'mc','auto','네 지역의 특징의 바람솔섬에서 바람이 약한 날에도 에너지를 얻으려면 어떻게 하는 것이 가장 알맞은가요?',ARRAY['SC5-2-u4-X18','SC5-2-u4-X19']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C9","difficulty":4,"kind":"mc","stem":"네 지역의 특징의 바람솔섬에서 바람이 약한 날에도 에너지를 얻으려면 어떻게 하는 것이 가장 알맞은가요?","options":[{"t":"풍력과 함께 섬 둘레 바다의 밀물과 썰물을 쓰는 해양 에너지도 쓴다","correct":true},{"t":"풍력 발전기를 모두 없앤다","mis":"SC5-2-u4-X18"},{"t":"바람이 약한 날에 풍력이 더 많은 에너지를 만든다고 믿는다","mis":"SC5-2-u4-X19"},{"t":"섬에 없는 골짜기의 물을 쓴다","mis":"SC5-2-u4-X18"}],"explanation":["섬은 바다로 둘러싸여요.","바다도 에너지를 줘요.","함께 쓰면 좋아요."],"asset":{"type":"passage","lines":["㉠ 바람솔섬 — 바다로 둘러싸여 일 년 내내 바람이 세다.","㉡ 해든 들판 — 비가 적고 햇빛이 강하게 내리쬔다.","㉢ 소울 목장 마을 — 가축이 많아 분뇨 처리가 걱정이다.","㉣ 물안개 골짜기 — 산이 깊고 물이 세차게 흘러내린다."],"title":"네 지역의 특징"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L03_challenge#10','sci',5,2,'u4','L03','g5_2_sci_u4_L03_challenge','lesson_challenge','SC5-2-u4-C8',4,'essay','teacher','재생 에너지 한 가지를 골라 소개 카드를 쓰세요. 에너지를 얻는 방법, 이용하는 예, 좋은 점을 넣으세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u4-C8","difficulty":4,"kind":"essay","stem":"재생 에너지 한 가지를 골라 소개 카드를 쓰세요. 에너지를 얻는 방법, 이용하는 예, 좋은 점을 넣으세요.","answer_guide":{"answer":"예: 태양 에너지 — 태양 빛이나 태양열을 이용해 에너지를 얻는다. 태양 전지를 단 가로등이나 지붕의 태양 전지판에 쓴다. 자연에서 계속 얻을 수 있고 환경을 덜 오염시킨다.","scoring_points":["재생 에너지를 골라 얻는 방법을 썼는가","이용하는 예를 썼는가","좋은 점(계속 이용·환경)을 썼는가"]},"explanation":["하나를 골라요.","얻는 방법을 써요.","좋은 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_basic#1','sci',5,2,'u4','L04','g5_2_sci_u4_L04_basic','lesson_basic','SC5-2-u4-C11',1,'mc','auto','지속가능한 에너지의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X22']::text[],false,'{"seq":1,"concept":"SC5-2-u4-C11","difficulty":1,"kind":"mc","stem":"지속가능한 에너지의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"지금 필요를 채우면서 미래 세대도 계속 쓸 수 있게 하는 에너지","correct":true},{"t":"지금 세대만 마음껏 쓰는 에너지","mis":"SC5-2-u4-X22"},{"t":"한 번 쓰면 사라지는 에너지","mis":"SC5-2-u4-X22"},{"t":"미래에는 필요 없는 에너지","mis":"SC5-2-u4-X22"}],"explanation":["지금도 써요.","미래 세대도 써요.","계속 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_basic#2','sci',5,2,'u4','L04','g5_2_sci_u4_L04_basic','lesson_basic','SC5-2-u4-C12',1,'ox','auto','사람이 없는 교실의 전등과 전기 기구를 끄는 것은 에너지를 지속가능하게 이용하는 방법이에요.',ARRAY['SC5-2-u4-X23']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C12","difficulty":1,"kind":"ox","stem":"사람이 없는 교실의 전등과 전기 기구를 끄는 것은 에너지를 지속가능하게 이용하는 방법이에요.","answer":"O","reason_options":[{"t":"불필요한 에너지 사용을 줄이기 때문에","correct":true},{"t":"사람이 없어도 켜 두어야 에너지가 늘어나기 때문에","mis":"SC5-2-u4-X23"}],"mis":"SC5-2-u4-X23","explanation":["사람이 없어요.","켜 둘 필요가 없어요.","꺼서 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_basic#3','sci',5,2,'u4','L04','g5_2_sci_u4_L04_basic','lesson_basic','SC5-2-u4-C12',1,'mc','auto','에너지 이용 놀이판의 ⑤ 칸에 도착하면 말을 어떻게 옮기나요?',ARRAY['SC5-2-u4-X23']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C12","difficulty":1,"kind":"mc","stem":"에너지 이용 놀이판의 ⑤ 칸에 도착하면 말을 어떻게 옮기나요?","options":[{"t":"사다리를 타고 위로 올라간다","correct":true},{"t":"미끄럼틀을 타고 아래로 내려간다","mis":"SC5-2-u4-X23"},{"t":"출발점으로 돌아간다","mis":"SC5-2-u4-X23"},{"t":"그 자리에서 놀이가 끝난다","mis":"SC5-2-u4-X23"}],"explanation":["⑤는 태양 전지판이에요.","지속가능한 예예요.","사다리로 올라가요."],"asset":{"type":"passage","lines":["① 냉난방할 때 알맞은 온도 지키기","② 창문을 연 채 난방 켜기","③ 가까운 곳은 걷거나 자전거 타기","④ 빈방에 조명 켜 두기","⑤ 지붕에 태양 전지판 달기","⑥ 보지 않는 텔레비전 켜 두기","⑦ 여러 나라가 함께 에너지 문제 풀기","⑧ 가까운 거리도 늘 자동차 타기"],"title":"에너지 이용 놀이판의 칸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_basic#4','sci',5,2,'u4','L04','g5_2_sci_u4_L04_basic','lesson_basic','SC5-2-u4-C13',1,'mc','auto','에너지를 지속가능하게 이용하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X21','SC5-2-u4-X23']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C13","difficulty":1,"kind":"mc","stem":"에너지를 지속가능하게 이용하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"태양 에너지, 풍력 같은 재생 에너지를 쓴다","correct":true},{"t":"석유를 더 많이 태운다","mis":"SC5-2-u4-X21"},{"t":"빈방 전등을 켜 둔다","mis":"SC5-2-u4-X23"},{"t":"가까운 거리도 늘 자동차를 탄다","mis":"SC5-2-u4-X23"}],"explanation":["재생 에너지예요.","계속 쓸 수 있어요.","지속가능해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_basic#5','sci',5,2,'u4','L04','g5_2_sci_u4_L04_basic','lesson_basic','SC5-2-u4-C12',2,'mc','auto','에너지 이용 놀이판에서 미끄럼틀을 타고 내려가는 칸끼리 모은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X23']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C12","difficulty":2,"kind":"mc","stem":"에너지 이용 놀이판에서 미끄럼틀을 타고 내려가는 칸끼리 모은 것은 어느 것인가요?","options":[{"t":"②, ④, ⑥, ⑧","correct":true},{"t":"①, ③, ⑤, ⑦","mis":"SC5-2-u4-X23"},{"t":"①, ②, ③, ④","mis":"SC5-2-u4-X23"},{"t":"⑤, ⑥, ⑦, ⑧","mis":"SC5-2-u4-X23"}],"explanation":["낭비하는 칸이에요.","짝수 칸이에요.","미끄럼틀이에요."],"asset":{"type":"passage","lines":["① 냉난방할 때 알맞은 온도 지키기","② 창문을 연 채 난방 켜기","③ 가까운 곳은 걷거나 자전거 타기","④ 빈방에 조명 켜 두기","⑤ 지붕에 태양 전지판 달기","⑥ 보지 않는 텔레비전 켜 두기","⑦ 여러 나라가 함께 에너지 문제 풀기","⑧ 가까운 거리도 늘 자동차 타기"],"title":"에너지 이용 놀이판의 칸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_basic#6','sci',5,2,'u4','L04','g5_2_sci_u4_L04_basic','lesson_basic','SC5-2-u4-C11',2,'mc','auto','에너지를 지속가능하게 이용해야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X22','SC5-2-u4-X21','SC5-2-u4-X19']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C11","difficulty":2,"kind":"mc","stem":"에너지를 지속가능하게 이용해야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"미래 세대도 깨끗한 에너지를 쓰고 기후변화에 대응하기 위해서","correct":true},{"t":"지금 세대가 에너지를 더 많이 쓰기 위해서","mis":"SC5-2-u4-X22"},{"t":"석탄과 석유를 빨리 다 쓰기 위해서","mis":"SC5-2-u4-X21"},{"t":"재생 에너지가 이미 넘칠 만큼 많아서","mis":"SC5-2-u4-X19"}],"explanation":["미래 세대가 있어요.","기후변화도 있어요.","그래서 지속가능하게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_basic#7','sci',5,2,'u4','L04','g5_2_sci_u4_L04_basic','lesson_basic','SC5-2-u4-C13',2,'ox','auto','전기차나 수소차처럼 환경오염에 영향을 적게 주는 친환경 기술을 개발하는 것도 지속가능한 방법이에요.',ARRAY['SC5-2-u4-X24']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C13","difficulty":2,"kind":"ox","stem":"전기차나 수소차처럼 환경오염에 영향을 적게 주는 친환경 기술을 개발하는 것도 지속가능한 방법이에요.","answer":"O","reason_options":[{"t":"환경을 덜 오염시키고 에너지 문제를 푸는 데 도움이 되기 때문에","correct":true},{"t":"지속가능한 방법은 에너지를 아끼는 것 한 가지뿐이기 때문에","mis":"SC5-2-u4-X24"}],"mis":"SC5-2-u4-X24","explanation":["친환경 기술이에요.","오염을 줄여요.","지속가능해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_basic#8','sci',5,2,'u4','L04','g5_2_sci_u4_L04_basic','lesson_basic','SC5-2-u4-C13',2,'mc','auto','학교에서 에너지를 지속가능하게 이용하려고 실천할 수 있는 일은 어느 것인가요?',ARRAY['SC5-2-u4-X23','SC5-2-u4-X25']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C13","difficulty":2,"kind":"mc","stem":"학교에서 에너지를 지속가능하게 이용하려고 실천할 수 있는 일은 어느 것인가요?","options":[{"t":"이동 수업을 갈 때 교실 전등을 끈다","correct":true},{"t":"겨울에 난방을 켜고 교실 문을 활짝 열어 둔다","mis":"SC5-2-u4-X23"},{"t":"쓰지 않는 전기 기구 플러그를 꽂아 둔다","mis":"SC5-2-u4-X25"},{"t":"에어컨을 켠 채 창문을 연다","mis":"SC5-2-u4-X23"}],"explanation":["교실이 비어요.","전등을 꺼요.","에너지를 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_basic#9','sci',5,2,'u4','L04','g5_2_sci_u4_L04_basic','lesson_basic','SC5-2-u4-C11',2,'mc','auto','석탄과 석유로 에너지를 얻을 때 생기는 문제로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X21','SC5-2-u4-X22']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C11","difficulty":2,"kind":"mc","stem":"석탄과 석유로 에너지를 얻을 때 생기는 문제로 알맞은 것은 어느 것인가요?","options":[{"t":"양이 한정되어 있고 대기오염과 기후변화를 일으킬 수 있다","correct":true},{"t":"양이 끝없이 많다","mis":"SC5-2-u4-X21"},{"t":"공기를 깨끗하게 만든다","mis":"SC5-2-u4-X21"},{"t":"미래 세대에게만 도움이 된다","mis":"SC5-2-u4-X22"}],"explanation":["양이 정해져 있어요.","공기를 더럽혀요.","문제가 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_basic#10','sci',5,2,'u4','L04','g5_2_sci_u4_L04_basic','lesson_basic','SC5-2-u4-C12',3,'error','auto','놀이를 마치고 칸을 나누며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X23','SC5-2-u4-X24']::text[],false,'{"seq":10,"concept":"SC5-2-u4-C12","difficulty":3,"kind":"error","stem":"놀이를 마치고 칸을 나누며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"이든 — 「창문을 연 채 난방을 하면 시원하니까 지속가능한 방법이야.」","correct":true,"mis_target":"SC5-2-u4-X23"},{"t":"소윤 — 「친환경 제품을 쓰면 에너지를 아낄 수 있어.」","mis":"SC5-2-u4-X23"},{"t":"라희 — 「여러 나라가 협력하는 것도 도움이 돼.」","mis":"SC5-2-u4-X24"}],"explanation":["열이 빠져나가요.","에너지를 낭비해요.","이든의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_challenge#1','sci',5,2,'u4','L04','g5_2_sci_u4_L04_challenge','lesson_challenge','SC5-2-u4-C13',2,'match','auto','에너지를 지속가능하게 이용하는 일과 그 갈래를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u4-C13","difficulty":2,"kind":"match","stem":"에너지를 지속가능하게 이용하는 일과 그 갈래를 알맞게 이으세요.","pairs":[{"l":"바람으로 전기를 만드는 발전기를 세운다","r":"재생 에너지 얻기"},{"l":"전기차와 수소차를 연구한다","r":"친환경 기술 개발"},{"l":"쓰지 않는 전등을 끈다","r":"불필요한 사용 줄이기"}],"mis":"SC5-2-u4-X24","explanation":["발전기는 재생 에너지예요.","연구는 기술이에요.","끄는 건 절약이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_challenge#2','sci',5,2,'u4','L04','g5_2_sci_u4_L04_challenge','lesson_challenge','SC5-2-u4-C12',2,'mc','auto','에너지를 지속가능하게 이용하지 않은 예는 어느 것인가요?',ARRAY['SC5-2-u4-X23']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C12","difficulty":2,"kind":"mc","stem":"에너지를 지속가능하게 이용하지 않은 예는 어느 것인가요?","options":[{"t":"석유로 에너지를 얻어 이산화 탄소가 많이 생긴다","correct":true},{"t":"에너지 절약 캠페인에 참여한다","mis":"SC5-2-u4-X23"},{"t":"수력과 풍력을 이용한다","mis":"SC5-2-u4-X23"},{"t":"친환경 제품을 쓴다","mis":"SC5-2-u4-X23"}],"explanation":["석유를 태워요.","이산화 탄소가 생겨요.","지속가능하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_challenge#3','sci',5,2,'u4','L04','g5_2_sci_u4_L04_challenge','lesson_challenge','SC5-2-u4-C11',3,'mc','auto','재생 에너지는 계속 쓸 수 있는데도 에너지를 아껴 써야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X13','SC5-2-u4-X20','SC5-2-u4-X42']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C11","difficulty":3,"kind":"mc","stem":"재생 에너지는 계속 쓸 수 있는데도 에너지를 아껴 써야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"지금은 재생 에너지 생산량이 충분하지 않기 때문이다","correct":true},{"t":"재생 에너지는 쓰면 금방 사라지기 때문이다","mis":"SC5-2-u4-X13"},{"t":"재생 에너지가 환경을 가장 많이 오염시키기 때문이다","mis":"SC5-2-u4-X20"},{"t":"아낄 필요가 전혀 없다","mis":"SC5-2-u4-X42"}],"explanation":["계속 쓸 수 있어요.","하지만 아직 모자라요.","아껴야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_challenge#4','sci',5,2,'u4','L04','g5_2_sci_u4_L04_challenge','lesson_challenge','SC5-2-u4-C13',3,'mc','auto','「에너지를 지속가능하게 쓰려면 재생 에너지만 있으면 돼.」를 바르게 고친 것은 어느 것인가요?',ARRAY['SC5-2-u4-X24','SC5-2-u4-X21','SC5-2-u4-X22']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C13","difficulty":3,"kind":"mc","stem":"「에너지를 지속가능하게 쓰려면 재생 에너지만 있으면 돼.」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"재생 에너지와 함께 친환경 기술 개발과 절약도 같이 해야 한다","correct":true},{"t":"고칠 것이 없으니 절약은 필요 없다","mis":"SC5-2-u4-X24"},{"t":"재생 에너지는 쓰지 말고 석유만 쓴다","mis":"SC5-2-u4-X21"},{"t":"미래 세대는 에너지가 필요 없다","mis":"SC5-2-u4-X22"}],"explanation":["세 갈래가 있어요.","함께 해야 해요.","하나로는 부족해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_challenge#5','sci',5,2,'u4','L04','g5_2_sci_u4_L04_challenge','lesson_challenge','SC5-2-u4-C12',3,'ox','auto','에너지를 많이 소모하는 기계를 공장에서 계속 쓰는 것은 에너지를 지속가능하게 이용하는 예예요.',ARRAY['SC5-2-u4-X23']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C12","difficulty":3,"kind":"ox","stem":"에너지를 많이 소모하는 기계를 공장에서 계속 쓰는 것은 에너지를 지속가능하게 이용하는 예예요.","answer":"X","reason_options":[{"t":"필요 이상으로 에너지를 많이 써 낭비가 되기 때문에","correct":true},{"t":"에너지를 많이 쓸수록 미래 세대에 도움이 되기 때문에","mis":"SC5-2-u4-X23"}],"mis":"SC5-2-u4-X23","explanation":["에너지를 많이 써요.","낭비예요.","지속가능하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_challenge#6','sci',5,2,'u4','L04','g5_2_sci_u4_L04_challenge','lesson_challenge','SC5-2-u4-C11',3,'error','auto','지속가능한 에너지를 토의하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X22']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C11","difficulty":3,"kind":"error","stem":"지속가능한 에너지를 토의하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"규리 — 「미래 세대는 알아서 하겠지. 지금 우리가 마음껏 쓰면 돼.」","correct":true,"mis_target":"SC5-2-u4-X22"},{"t":"수아 — 「미래 세대도 에너지가 필요해.」","mis":"SC5-2-u4-X22"},{"t":"해온 — 「기후변화에도 대응해야 해.」","mis":"SC5-2-u4-X22"}],"explanation":["미래 세대도 써요.","마음껏 쓰면 안 돼요.","규리의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_challenge#7','sci',5,2,'u4','L04','g5_2_sci_u4_L04_challenge','lesson_challenge','SC5-2-u4-C13',3,'mc','auto','겨울철 교실에서 에너지를 지속가능하게 쓰는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X23']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C13","difficulty":3,"kind":"mc","stem":"겨울철 교실에서 에너지를 지속가능하게 쓰는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"난방 중에는 열이 빠져나가지 않게 문과 창문을 닫는다","correct":true},{"t":"난방을 가장 세게 켜고 창문을 연다","mis":"SC5-2-u4-X23"},{"t":"복도 전등까지 모두 켜 둔다","mis":"SC5-2-u4-X23"},{"t":"빈 교실 난방기를 켜 둔다","mis":"SC5-2-u4-X23"}],"explanation":["난방 중이에요.","열이 나가면 안 돼요.","문을 닫아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_challenge#8','sci',5,2,'u4','L04','g5_2_sci_u4_L04_challenge','lesson_challenge','SC5-2-u4-C12',4,'mc','auto','에너지 이용 놀이판의 미끄럼틀 칸을 사다리 칸으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['SC5-2-u4-X23']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C12","difficulty":4,"kind":"mc","stem":"에너지 이용 놀이판의 미끄럼틀 칸을 사다리 칸으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"④ 빈방에 조명 켜 두기 → 방을 나설 때 조명 끄기","correct":true},{"t":"② 창문을 연 채 난방 켜기 → 난방을 더 세게 켜기","mis":"SC5-2-u4-X23"},{"t":"⑧ 가까운 거리도 늘 자동차 타기 → 더 큰 자동차 타기","mis":"SC5-2-u4-X23"},{"t":"⑥ 보지 않는 텔레비전 켜 두기 → 소리만 줄이기","mis":"SC5-2-u4-X23"}],"explanation":["낭비를 찾아요.","불필요한 사용을 끊어요.","④를 바르게 바꿨어요."],"asset":{"type":"passage","lines":["① 냉난방할 때 알맞은 온도 지키기","② 창문을 연 채 난방 켜기","③ 가까운 곳은 걷거나 자전거 타기","④ 빈방에 조명 켜 두기","⑤ 지붕에 태양 전지판 달기","⑥ 보지 않는 텔레비전 켜 두기","⑦ 여러 나라가 함께 에너지 문제 풀기","⑧ 가까운 거리도 늘 자동차 타기"],"title":"에너지 이용 놀이판의 칸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_challenge#9','sci',5,2,'u4','L04','g5_2_sci_u4_L04_challenge','lesson_challenge','SC5-2-u4-C11',4,'mc','auto','에너지를 지속가능하게 이용하는 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X22','SC5-2-u4-X42','SC5-2-u4-X21']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C11","difficulty":4,"kind":"mc","stem":"에너지를 지속가능하게 이용하는 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"에너지 문제를 내 일로 여기고 생활 속 작은 실천부터 꾸준히 한다","correct":true},{"t":"어른들이 할 일이라 나와는 상관없다","mis":"SC5-2-u4-X22"},{"t":"재생 에너지가 있으니 낭비해도 된다","mis":"SC5-2-u4-X42"},{"t":"석유를 아끼려고 석탄을 더 쓴다","mis":"SC5-2-u4-X21"}],"explanation":["내 일이에요.","작은 실천부터요.","꾸준히 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L04_challenge#10','sci',5,2,'u4','L04','g5_2_sci_u4_L04_challenge','lesson_challenge','SC5-2-u4-C11',4,'essay','teacher','에너지를 지속가능하게 이용해야 하는 까닭을 두 가지 쓰고, 내가 학교에서 실천할 수 있는 방법을 하나 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u4-C11","difficulty":4,"kind":"essay","stem":"에너지를 지속가능하게 이용해야 하는 까닭을 두 가지 쓰고, 내가 학교에서 실천할 수 있는 방법을 하나 쓰세요.","answer_guide":{"answer":"예: 석탄과 석유는 양이 한정되어 있어 계속 쓸 수 없다. 또 대기오염과 기후변화를 일으키므로 미래 세대도 깨끗한 에너지를 쓸 수 있게 해야 한다. 나는 이동 수업 때 교실 전등을 끄겠다.","scoring_points":["까닭 하나(한정·고갈)를 썼는가","까닭 하나(환경·미래 세대)를 썼는가","학교에서 실천할 방법을 썼는가"]},"explanation":["까닭 두 가지예요.","미래 세대를 생각해요.","실천을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_basic#1','sci',5,2,'u4','L05','g5_2_sci_u4_L05_basic','lesson_basic','SC5-2-u4-C14',1,'mc','auto','효율이 좋은 전등은 어느 것인가요?',ARRAY['SC5-2-u4-X26']::text[],false,'{"seq":1,"concept":"SC5-2-u4-C14","difficulty":1,"kind":"mc","stem":"효율이 좋은 전등은 어느 것인가요?","options":[{"t":"같은 밝기를 내면서 전기를 적게 쓰는 전등","correct":true},{"t":"같은 밝기를 내면서 전기를 많이 쓰는 전등","mis":"SC5-2-u4-X26"},{"t":"전기를 많이 써 가장 뜨거운 전등","mis":"SC5-2-u4-X26"},{"t":"불을 켜도 어두운 전등","mis":"SC5-2-u4-X26"}],"explanation":["밝기가 같아요.","전기를 적게 써요.","효율이 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_basic#2','sci',5,2,'u4','L05','g5_2_sci_u4_L05_basic','lesson_basic','SC5-2-u4-C14',1,'mc','auto','에너지 소비 효율 등급에서 효율이 가장 높은 등급은 어느 것인가요?',ARRAY['SC5-2-u4-X27']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C14","difficulty":1,"kind":"mc","stem":"에너지 소비 효율 등급에서 효율이 가장 높은 등급은 어느 것인가요?","options":[{"t":"1등급","correct":true},{"t":"5등급","mis":"SC5-2-u4-X27"},{"t":"3등급","mis":"SC5-2-u4-X27"},{"t":"등급과 효율은 상관없다","mis":"SC5-2-u4-X27"}],"explanation":["1~5등급이 있어요.","1등급에 가까울수록요.","1등급이 가장 높아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_basic#3','sci',5,2,'u4','L05','g5_2_sci_u4_L05_basic','lesson_basic','SC5-2-u4-C15',1,'ox','auto','빗물 저금통에 빗물을 모아 다시 쓰면 물 자원을 효율적으로 이용할 수 있어요.',ARRAY['SC5-2-u4-X07']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C15","difficulty":1,"kind":"ox","stem":"빗물 저금통에 빗물을 모아 다시 쓰면 물 자원을 효율적으로 이용할 수 있어요.","answer":"O","reason_options":[{"t":"그냥 흘러가 버릴 빗물을 모아 다시 쓰기 때문에","correct":true},{"t":"빗물을 모으면 지구의 물이 새로 늘어나기 때문에","mis":"SC5-2-u4-X07"}],"mis":"SC5-2-u4-X07","explanation":["빗물을 모아요.","다시 써요.","물을 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_basic#4','sci',5,2,'u4','L05','g5_2_sci_u4_L05_basic','lesson_basic','SC5-2-u4-C15',1,'mc','auto','산림 자원을 효율적으로 이용하는 방법은 어느 것인가요?',ARRAY['SC5-2-u4-X28']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C15","difficulty":1,"kind":"mc","stem":"산림 자원을 효율적으로 이용하는 방법은 어느 것인가요?","options":[{"t":"종이 영수증 대신 전자 영수증을 받는다","correct":true},{"t":"종이컵을 한 번 쓰고 버린다","mis":"SC5-2-u4-X28"},{"t":"과대 포장된 물건을 산다","mis":"SC5-2-u4-X28"},{"t":"이면지를 모두 버린다","mis":"SC5-2-u4-X28"}],"explanation":["영수증은 종이예요.","전자로 받아요.","나무를 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_basic#5','sci',5,2,'u4','L05','g5_2_sci_u4_L05_basic','lesson_basic','SC5-2-u4-C14',2,'mc','auto','우리 교실 살펴보기 ①에서 에너지가 낭비되는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X25','SC5-2-u4-X29']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C14","difficulty":2,"kind":"mc","stem":"우리 교실 살펴보기 ①에서 에너지가 낭비되는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"꺼 둔 기계도 플러그가 꽂혀 있으면 전기가 조금씩 쓰이기 때문이다","correct":true},{"t":"꺼 둔 기계는 플러그가 꽂혀 있어도 전기가 전혀 쓰이지 않기 때문이다","mis":"SC5-2-u4-X25"},{"t":"플러그를 꽂아 두면 전기가 새로 만들어지기 때문이다","mis":"SC5-2-u4-X29"},{"t":"공기 청정기는 원래 전기를 쓰지 않기 때문이다","mis":"SC5-2-u4-X25"}],"explanation":["전원은 꺼져 있어요.","플러그는 꽂혀 있어요.","전기가 조금씩 새요."],"asset":{"type":"passage","lines":["① 꺼 둔 공기 청정기의 플러그가 꽂혀 있다.","② 종이컵을 하루에 열 개씩 쓰고 버린다.","③ 양치할 때 물을 계속 틀어 놓는다.","④ 이면지 상자가 늘 비어 있다.","⑤ 교실 전등을 LED 조명으로 바꾸었다."],"title":"우리 교실 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_basic#6','sci',5,2,'u4','L05','g5_2_sci_u4_L05_basic','lesson_basic','SC5-2-u4-C15',2,'mc','auto','우리 교실 살펴보기 ③을 고치는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X28','SC5-2-u4-X30']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C15","difficulty":2,"kind":"mc","stem":"우리 교실 살펴보기 ③을 고치는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"양치 컵에 물을 받아 양치한다","correct":true},{"t":"물을 더 세게 틀어 놓는다","mis":"SC5-2-u4-X28"},{"t":"물 대신 종이를 아낀다","mis":"SC5-2-u4-X30"},{"t":"수도꼭지를 분리배출한다","mis":"SC5-2-u4-X30"}],"explanation":["물을 틀어 놓았어요.","컵에 받아요.","물을 아껴요."],"asset":{"type":"passage","lines":["① 꺼 둔 공기 청정기의 플러그가 꽂혀 있다.","② 종이컵을 하루에 열 개씩 쓰고 버린다.","③ 양치할 때 물을 계속 틀어 놓는다.","④ 이면지 상자가 늘 비어 있다.","⑤ 교실 전등을 LED 조명으로 바꾸었다."],"title":"우리 교실 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_basic#7','sci',5,2,'u4','L05','g5_2_sci_u4_L05_basic','lesson_basic','SC5-2-u4-C16',2,'mc','auto','에너지를 효율적으로 이용하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X27','SC5-2-u4-X29','SC5-2-u4-X25']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C16","difficulty":2,"kind":"mc","stem":"에너지를 효율적으로 이용하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"1등급에 가까운 제품과 LED 조명을 쓴다","correct":true},{"t":"5등급 제품을 골라 쓴다","mis":"SC5-2-u4-X27"},{"t":"에너지 생산을 줄이고 사용을 늘린다","mis":"SC5-2-u4-X29"},{"t":"쓰지 않는 전기 기구를 켜 둔다","mis":"SC5-2-u4-X25"}],"explanation":["등급을 봐요.","LED 조명이에요.","효율적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_basic#8','sci',5,2,'u4','L05','g5_2_sci_u4_L05_basic','lesson_basic','SC5-2-u4-C15',2,'ox','auto','분리배출을 잘하면 버려질 광물 자원을 재활용할 수 있어요.',ARRAY['SC5-2-u4-X30']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C15","difficulty":2,"kind":"ox","stem":"분리배출을 잘하면 버려질 광물 자원을 재활용할 수 있어요.","answer":"O","reason_options":[{"t":"섞인 쓰레기를 종류별로 나누면 다시 쓸 수 있기 때문에","correct":true},{"t":"분리배출은 물 자원만 아끼는 방법이기 때문에","mis":"SC5-2-u4-X30"}],"mis":"SC5-2-u4-X30","explanation":["종류별로 나눠요.","혼합물의 분리예요.","다시 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_basic#9','sci',5,2,'u4','L05','g5_2_sci_u4_L05_basic','lesson_basic','SC5-2-u4-C16',2,'mc','auto','절전 멀티탭을 쓰는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X26','SC5-2-u4-X25']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C16","difficulty":2,"kind":"mc","stem":"절전 멀티탭을 쓰는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"쓰지 않을 때 단추 하나로 전기를 끊어 새는 전기를 막으려고","correct":true},{"t":"전기를 더 많이 쓰려고","mis":"SC5-2-u4-X26"},{"t":"꺼 둔 기계는 원래 전기를 안 쓰니 필요 없다","mis":"SC5-2-u4-X25"},{"t":"전기 기구를 더 세게 작동시키려고","mis":"SC5-2-u4-X26"}],"explanation":["단추로 끊어요.","새는 전기를 막아요.","에너지를 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_basic#10','sci',5,2,'u4','L05','g5_2_sci_u4_L05_basic','lesson_basic','SC5-2-u4-C16',3,'error','auto','두 냉장고의 등급 표시를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X27','SC5-2-u4-X26']::text[],false,'{"seq":10,"concept":"SC5-2-u4-C16","difficulty":3,"kind":"error","stem":"두 냉장고의 등급 표시를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태린 — 「4등급인 ㉯가 숫자가 더 크니까 효율이 더 높아.」","correct":true,"mis_target":"SC5-2-u4-X27"},{"t":"윤재 — 「㉮가 같은 일을 하며 전기를 덜 써.」","mis":"SC5-2-u4-X26"},{"t":"하린 — 「1등급에 가까울수록 효율이 높아.」","mis":"SC5-2-u4-X27"}],"explanation":["1등급에 가까울수록요.","㉮가 효율이 높아요.","태린의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["냉장고 ㉮ — 에너지 소비 효율 1등급","냉장고 ㉯ — 에너지 소비 효율 4등급","두 냉장고는 크기와 기능이 같다."],"title":"두 냉장고의 등급 표시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_challenge#1','sci',5,2,'u4','L05','g5_2_sci_u4_L05_challenge','lesson_challenge','SC5-2-u4-C15',2,'match','auto','자원을 효율적으로 이용하는 방법과 주로 아끼는 자원을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u4-C15","difficulty":2,"kind":"match","stem":"자원을 효율적으로 이용하는 방법과 주로 아끼는 자원을 알맞게 이으세요.","pairs":[{"l":"빗물 저금통","r":"물 자원"},{"l":"이면지 쓰기","r":"산림 자원"},{"l":"캔 분리배출","r":"광물 자원"}],"mis":"SC5-2-u4-X30","explanation":["빗물은 물이에요.","종이는 나무예요.","캔은 광물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_challenge#2','sci',5,2,'u4','L05','g5_2_sci_u4_L05_challenge','lesson_challenge','SC5-2-u4-C14',2,'mc','auto','전기 기구를 껐는데도 플러그를 꽂아 두기만 해서 쓰이는 전기를 줄이는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X25','SC5-2-u4-X26']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C14","difficulty":2,"kind":"mc","stem":"전기 기구를 껐는데도 플러그를 꽂아 두기만 해서 쓰이는 전기를 줄이는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"쓰지 않을 때는 플러그를 뽑는다","correct":true},{"t":"플러그를 더 깊게 꽂는다","mis":"SC5-2-u4-X25"},{"t":"전원 단추만 여러 번 누른다","mis":"SC5-2-u4-X25"},{"t":"멀티탭을 두 개 이어 쓴다","mis":"SC5-2-u4-X26"}],"explanation":["꽂혀만 있어도 써요.","플러그를 뽑아요.","새는 전기를 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_challenge#3','sci',5,2,'u4','L05','g5_2_sci_u4_L05_challenge','lesson_challenge','SC5-2-u4-C16',3,'mc','auto','두 냉장고의 등급 표시에서 ㉮를 고르는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X27','SC5-2-u4-X26']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C16","difficulty":3,"kind":"mc","stem":"두 냉장고의 등급 표시에서 ㉮를 고르는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"크기와 기능이 같으면서 전기를 덜 써 에너지와 돈을 아낄 수 있어서","correct":true},{"t":"숫자가 작아 효율이 낮아서","mis":"SC5-2-u4-X27"},{"t":"전기를 더 많이 써서 더 시원해서","mis":"SC5-2-u4-X26"},{"t":"등급은 겉모양을 알려 주는 표시라서","mis":"SC5-2-u4-X27"}],"explanation":["크기·기능이 같아요.","1등급이에요.","전기를 덜 써요."],"asset":{"type":"passage","lines":["냉장고 ㉮ — 에너지 소비 효율 1등급","냉장고 ㉯ — 에너지 소비 효율 4등급","두 냉장고는 크기와 기능이 같다."],"title":"두 냉장고의 등급 표시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_challenge#4','sci',5,2,'u4','L05','g5_2_sci_u4_L05_challenge','lesson_challenge','SC5-2-u4-C15',3,'mc','auto','자원을 가장 효율적으로 이용한 친구는 누구인가요?',ARRAY['SC5-2-u4-X28']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C15","difficulty":3,"kind":"mc","stem":"자원을 가장 효율적으로 이용한 친구는 누구인가요?","options":[{"t":"장바구니를 들고 가 과대 포장 없는 물건을 산 은솔","correct":true},{"t":"가까운 편의점까지 자동차를 탄 지후","mis":"SC5-2-u4-X28"},{"t":"물을 틀어 놓고 비누칠을 한 서아","mis":"SC5-2-u4-X28"},{"t":"새 공책을 한 장만 쓰고 버린 하람","mis":"SC5-2-u4-X28"}],"explanation":["장바구니를 써요.","포장을 줄여요.","은솔이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_challenge#5','sci',5,2,'u4','L05','g5_2_sci_u4_L05_challenge','lesson_challenge','SC5-2-u4-C16',3,'ox','auto','외벽과 창틀에 단열을 하는 것도 에너지를 효율적으로 이용하는 방법이에요.',ARRAY['SC5-2-u4-X36']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C16","difficulty":3,"kind":"ox","stem":"외벽과 창틀에 단열을 하는 것도 에너지를 효율적으로 이용하는 방법이에요.","answer":"O","reason_options":[{"t":"집 안 열이 빠져나가는 것을 막아 냉난방 에너지를 덜 쓰기 때문에","correct":true},{"t":"단열재가 스스로 열을 만들어 집을 데우기 때문에","mis":"SC5-2-u4-X36"}],"mis":"SC5-2-u4-X36","explanation":["열이 빠져나가요.","단열로 막아요.","에너지를 덜 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_challenge#6','sci',5,2,'u4','L05','g5_2_sci_u4_L05_challenge','lesson_challenge','SC5-2-u4-C16',3,'error','auto','에너지를 효율적으로 쓰는 방법을 나누며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X29']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C16","difficulty":3,"kind":"error","stem":"에너지를 효율적으로 쓰는 방법을 나누며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민규 — 「에너지 생산을 줄이고 사용을 늘리면 효율적으로 쓰는 거야.」","correct":true,"mis_target":"SC5-2-u4-X29"},{"t":"세아 — 「태양 에너지를 쓰는 것도 방법이야.」","mis":"SC5-2-u4-X29"},{"t":"도하 — 「냉난방 온도를 알맞게 지켜.」","mis":"SC5-2-u4-X29"}],"explanation":["덜 써야 해요.","사용을 늘리면 낭비예요.","민규의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_challenge#7','sci',5,2,'u4','L05','g5_2_sci_u4_L05_challenge','lesson_challenge','SC5-2-u4-C15',3,'mc','auto','움직임을 알아차리는 센서가 달린 수도꼭지가 물 절약에 좋은 까닭은 어느 것인가요?',ARRAY['SC5-2-u4-X28','SC5-2-u4-X07','SC5-2-u4-X30']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C15","difficulty":3,"kind":"mc","stem":"움직임을 알아차리는 센서가 달린 수도꼭지가 물 절약에 좋은 까닭은 어느 것인가요?","options":[{"t":"손을 떼면 물이 저절로 멈춰 낭비되는 물을 줄인다","correct":true},{"t":"물을 끊임없이 흘려보낸다","mis":"SC5-2-u4-X28"},{"t":"지구의 물을 새로 만들어 낸다","mis":"SC5-2-u4-X07"},{"t":"물 대신 나무를 아낀다","mis":"SC5-2-u4-X30"}],"explanation":["손을 떼요.","물이 멈춰요.","물을 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_challenge#8','sci',5,2,'u4','L05','g5_2_sci_u4_L05_challenge','lesson_challenge','SC5-2-u4-C14',4,'mc','auto','밝기가 같은 전등 ㉠은 한 시간에 전기를 10만큼, 전등 ㉡은 60만큼 써요. 효율이 더 좋은 전등과 그 까닭은 어느 것인가요?',ARRAY['SC5-2-u4-X26','SC5-2-u4-X27']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C14","difficulty":4,"kind":"mc","stem":"밝기가 같은 전등 ㉠은 한 시간에 전기를 10만큼, 전등 ㉡은 60만큼 써요. 효율이 더 좋은 전등과 그 까닭은 어느 것인가요?","options":[{"t":"㉠, 같은 밝기를 내면서 전기를 적게 써서","correct":true},{"t":"㉡, 전기를 많이 써서","mis":"SC5-2-u4-X26"},{"t":"둘이 같다, 밝기가 같아서","mis":"SC5-2-u4-X26"},{"t":"㉡, 숫자가 더 커서","mis":"SC5-2-u4-X27"}],"explanation":["밝기가 같아요.","㉠이 적게 써요.","㉠이 효율적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_challenge#9','sci',5,2,'u4','L05','g5_2_sci_u4_L05_challenge','lesson_challenge','SC5-2-u4-C16',4,'mc','auto','우리 교실의 에너지 계획으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X25','SC5-2-u4-X26','SC5-2-u4-X27']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C16","difficulty":4,"kind":"mc","stem":"우리 교실의 에너지 계획으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"쓰지 않는 기기는 절전 멀티탭으로 끄고, 조명은 LED로, 냉난방 중엔 창문을 닫는다","correct":true},{"t":"모든 기기를 켜 두고 창문을 활짝 연다","mis":"SC5-2-u4-X25"},{"t":"밝게 하려고 조명을 두 배로 늘린다","mis":"SC5-2-u4-X26"},{"t":"모든 제품을 5등급으로 바꾼다","mis":"SC5-2-u4-X27"}],"explanation":["새는 전기를 막아요.","효율 높은 조명이에요.","열도 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L05_challenge#10','sci',5,2,'u4','L05','g5_2_sci_u4_L05_challenge','lesson_challenge','SC5-2-u4-C15',4,'essay','teacher','우리 교실 살펴보기에서 자원이나 에너지가 낭비되는 곳을 두 군데 찾고, 각각 어떻게 고치면 좋을지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u4-C15","difficulty":4,"kind":"essay","stem":"우리 교실 살펴보기에서 자원이나 에너지가 낭비되는 곳을 두 군데 찾고, 각각 어떻게 고치면 좋을지 쓰세요.","answer_guide":{"answer":"예: ① 꺼 둔 공기 청정기의 플러그가 꽂혀 있어 전기가 새므로 쓰지 않을 때 플러그를 뽑는다. ② 종이컵을 하루에 열 개씩 버리므로 다회용 컵을 쓴다.","scoring_points":["낭비되는 곳 하나를 바르게 찾아 고칠 방법을 썼는가","낭비되는 곳 하나를 더 찾아 고칠 방법을 썼는가","고친 방법이 무엇을 아끼는지 알맞은가"]},"explanation":["두 군데를 찾아요.","고칠 방법을 써요.","무엇을 아끼나 봐요."],"asset":{"type":"passage","lines":["① 꺼 둔 공기 청정기의 플러그가 꽂혀 있다.","② 종이컵을 하루에 열 개씩 쓰고 버린다.","③ 양치할 때 물을 계속 틀어 놓는다.","④ 이면지 상자가 늘 비어 있다.","⑤ 교실 전등을 LED 조명으로 바꾸었다."],"title":"우리 교실 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_basic#1','sci',5,2,'u4','L06','g5_2_sci_u4_L06_basic','lesson_basic','SC5-2-u4-C17',1,'mc','auto','단열 효과를 알아보는 실험에서 두 집 모형은 어떻게 만드나요?',ARRAY['SC5-2-u4-X31']::text[],false,'{"seq":1,"concept":"SC5-2-u4-C17","difficulty":1,"kind":"mc","stem":"단열 효과를 알아보는 실험에서 두 집 모형은 어떻게 만드나요?","options":[{"t":"크기와 모양이 같게 만든다","correct":true},{"t":"크기를 서로 다르게 만든다","mis":"SC5-2-u4-X31"},{"t":"한 집은 종이, 한 집은 쇠로 만든다","mis":"SC5-2-u4-X31"},{"t":"집 모형을 하나만 만든다","mis":"SC5-2-u4-X31"}],"explanation":["두 집을 견줘요.","크기와 모양이 같아요.","단열만 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_basic#2','sci',5,2,'u4','L06','g5_2_sci_u4_L06_basic','lesson_basic','SC5-2-u4-C17',1,'mc','auto','집 모형 실험 차례 ④에서 집 안 공기를 데우려고 넣은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X31']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C17","difficulty":1,"kind":"mc","stem":"집 모형 실험 차례 ④에서 집 안 공기를 데우려고 넣은 것은 어느 것인가요?","options":[{"t":"따뜻한 손난로","correct":true},{"t":"얼음 주머니","mis":"SC5-2-u4-X31"},{"t":"젖은 수건","mis":"SC5-2-u4-X31"},{"t":"작은 선풍기","mis":"SC5-2-u4-X31"}],"explanation":["공기를 데워요.","따뜻한 것을 넣어요.","손난로예요."],"asset":{"type":"passage","lines":["① 크기와 모양이 같은 집 모형 ㉮, ㉯를 만든다.","② 두 집 창문 안쪽에 뽁뽁이를 한 장씩 붙인다.","③ ㉯에만 뽁뽁이를 한 장 더, 벽에 우드록, 틈은 색점토로 막는다.","④ 지붕에 탐침 온도계를 꽂고 데운 손난로를 넣어 5분 둔다.","⑤ 손난로를 빼고 1분 간격으로 5번 온도를 잰다."],"title":"집 모형 실험 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_basic#3','sci',5,2,'u4','L06','g5_2_sci_u4_L06_basic','lesson_basic','SC5-2-u4-C18',1,'ox','auto','단열을 한 집 모형은 단열을 하지 않은 집 모형보다 온도 변화가 더 작아요.',ARRAY['SC5-2-u4-X33']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C18","difficulty":1,"kind":"ox","stem":"단열을 한 집 모형은 단열을 하지 않은 집 모형보다 온도 변화가 더 작아요.","answer":"O","reason_options":[{"t":"단열을 하면 집 안의 열이 덜 빠져나가기 때문에","correct":true},{"t":"단열재가 열을 더 빨리 밖으로 내보내기 때문에","mis":"SC5-2-u4-X33"}],"mis":"SC5-2-u4-X33","explanation":["열이 덜 나가요.","온도가 잘 지켜져요.","변화가 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_basic#4','sci',5,2,'u4','L06','g5_2_sci_u4_L06_basic','lesson_basic','SC5-2-u4-C18',1,'sa','auto','두 집 모형 안의 온도 그래프에서 단열한 집의 5분 뒤 온도는 몇 °C인가요? 숫자만 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-2-u4-C18","difficulty":1,"kind":"sa","stem":"두 집 모형 안의 온도 그래프에서 단열한 집의 5분 뒤 온도는 몇 °C인가요? 숫자만 쓰세요.","answer":["27.5","27.5 °C","27.5도"],"explanation":["단열한 집을 봐요.","5분 뒤예요.","27.5 °C예요."],"asset":{"type":"lgraph","xs":["처음","1","2","3","4","5"],"series":[{"name":"단열 안 한 집","vals":[30,28,27,26.5,26,25.5]},{"name":"단열한 집","vals":[30,29.5,29,28.5,28,27.5]}],"step":0.5,"y0":24,"wave":true,"ymax":31,"ylab":"(°C)","xlab":"(분 뒤)","title":"두 집 모형 안의 온도"},"mis":"SC5-2-u4-X34"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_basic#5','sci',5,2,'u4','L06','g5_2_sci_u4_L06_basic','lesson_basic','SC5-2-u4-C18',2,'mc','auto','두 집 모형 안의 온도 그래프에서 단열 안 한 집의 온도 변화량은 얼마인가요?',ARRAY['SC5-2-u4-X34','SC5-2-u4-X33']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C18","difficulty":2,"kind":"mc","stem":"두 집 모형 안의 온도 그래프에서 단열 안 한 집의 온도 변화량은 얼마인가요?","options":[{"t":"4.5 °C","correct":true},{"t":"25.5 °C","mis":"SC5-2-u4-X34"},{"t":"2.5 °C","mis":"SC5-2-u4-X33"},{"t":"30 °C","mis":"SC5-2-u4-X34"}],"explanation":["처음은 30 °C예요.","5분 뒤 25.5 °C예요.","4.5 °C 낮아졌어요."],"asset":{"type":"lgraph","xs":["처음","1","2","3","4","5"],"series":[{"name":"단열 안 한 집","vals":[30,28,27,26.5,26,25.5]},{"name":"단열한 집","vals":[30,29.5,29,28.5,28,27.5]}],"step":0.5,"y0":24,"wave":true,"ymax":31,"ylab":"(°C)","xlab":"(분 뒤)","title":"두 집 모형 안의 온도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_basic#6','sci',5,2,'u4','L06','g5_2_sci_u4_L06_basic','lesson_basic','SC5-2-u4-C17',2,'mc','auto','집 모형 안의 온도를 잴 때 탐침 온도계를 바르게 쓴 것은 어느 것인가요?',ARRAY['SC5-2-u4-X32']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C17","difficulty":2,"kind":"mc","stem":"집 모형 안의 온도를 잴 때 탐침 온도계를 바르게 쓴 것은 어느 것인가요?","options":[{"t":"탐침 끝이 바닥에 닿지 않게 꽂아 공기의 온도를 잰다","correct":true},{"t":"탐침 끝을 바닥에 꾹 눌러 꽂는다","mis":"SC5-2-u4-X32"},{"t":"탐침 끝을 친구 쪽으로 향하게 든다","mis":"SC5-2-u4-X32"},{"t":"손난로에 탐침을 꽂는다","mis":"SC5-2-u4-X32"}],"explanation":["공기 온도를 재요.","바닥에 닿지 않게요.","바르게 꽂아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_basic#7','sci',5,2,'u4','L06','g5_2_sci_u4_L06_basic','lesson_basic','SC5-2-u4-C18',2,'mc','auto','두 집 모형 안의 온도 그래프에서 에너지 효율이 더 높은 집과 그 까닭은 어느 것인가요?',ARRAY['SC5-2-u4-X33','SC5-2-u4-X34']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C18","difficulty":2,"kind":"mc","stem":"두 집 모형 안의 온도 그래프에서 에너지 효율이 더 높은 집과 그 까닭은 어느 것인가요?","options":[{"t":"단열한 집, 온도 변화가 더 작아서","correct":true},{"t":"단열 안 한 집, 온도 변화가 더 커서","mis":"SC5-2-u4-X33"},{"t":"두 집이 같다, 처음 온도가 같아서","mis":"SC5-2-u4-X34"},{"t":"단열 안 한 집, 5분 뒤 온도가 더 낮아서","mis":"SC5-2-u4-X33"}],"explanation":["변화량을 견줘요.","단열한 집이 덜 변해요.","효율이 높아요."],"asset":{"type":"lgraph","xs":["처음","1","2","3","4","5"],"series":[{"name":"단열 안 한 집","vals":[30,28,27,26.5,26,25.5]},{"name":"단열한 집","vals":[30,29.5,29,28.5,28,27.5]}],"step":0.5,"y0":24,"wave":true,"ymax":31,"ylab":"(°C)","xlab":"(분 뒤)","title":"두 집 모형 안의 온도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_basic#8','sci',5,2,'u4','L06','g5_2_sci_u4_L06_basic','lesson_basic','SC5-2-u4-C19',2,'mc','auto','에너지를 아끼는 집 그림에서 ㉡ 이중창이 하는 일은 어느 것인가요?',ARRAY['SC5-2-u4-X35','SC5-2-u4-X36']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C19","difficulty":2,"kind":"mc","stem":"에너지를 아끼는 집 그림에서 ㉡ 이중창이 하는 일은 어느 것인가요?","options":[{"t":"집 안과 밖 사이의 열 이동을 막아 집 안 온도를 지킨다","correct":true},{"t":"햇빛으로 전기를 만든다","mis":"SC5-2-u4-X35"},{"t":"스스로 열을 내 집을 데운다","mis":"SC5-2-u4-X36"},{"t":"땅속 열을 끌어 온다","mis":"SC5-2-u4-X35"}],"explanation":["창이 두 겹이에요.","열 이동을 막아요.","온도를 지켜요."],"asset":{"type":"passage","lines":["㉠ 벽 속 단열재","㉡ 이중창","㉢ 햇빛 방향에 따라 움직이는 차양","㉣ 지붕 위 태양 전지판","㉤ 땅속 열을 쓰는 냉난방","㉥ 옥상 정원"],"title":"에너지를 아끼는 집 그림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_basic#9','sci',5,2,'u4','L06','g5_2_sci_u4_L06_basic','lesson_basic','SC5-2-u4-C19',2,'ox','auto','지붕의 태양 전지판으로 전기를 만들어 쓰는 것은 에너지를 직접 만들어 쓰는 방법이에요.',ARRAY['SC5-2-u4-X35']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C19","difficulty":2,"kind":"ox","stem":"지붕의 태양 전지판으로 전기를 만들어 쓰는 것은 에너지를 직접 만들어 쓰는 방법이에요.","answer":"O","reason_options":[{"t":"태양 빛으로 필요한 에너지를 생산하기 때문에","correct":true},{"t":"태양 전지판은 열이 빠져나가는 것을 막는 단열재이기 때문에","mis":"SC5-2-u4-X35"}],"mis":"SC5-2-u4-X35","explanation":["햇빛을 받아요.","전기를 만들어요.","직접 만드는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_basic#10','sci',5,2,'u4','L06','g5_2_sci_u4_L06_basic','lesson_basic','SC5-2-u4-C17',3,'error','auto','집 모형 실험 차례를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X32','SC5-2-u4-X31']::text[],false,'{"seq":10,"concept":"SC5-2-u4-C17","difficulty":3,"kind":"error","stem":"집 모형 실험 차례를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"주원 — 「손난로를 뺄 때는 집 문을 활짝 열어야 정확해.」","correct":true,"mis_target":"SC5-2-u4-X32"},{"t":"채아 — 「두 집에 같은 손난로를 넣었어.」","mis":"SC5-2-u4-X31"},{"t":"보람 — 「㉯ 집만 단열을 더 했어.」","mis":"SC5-2-u4-X31"}],"explanation":["활짝 열면 열이 나가요.","살짝만 열어요.","주원의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["① 크기와 모양이 같은 집 모형 ㉮, ㉯를 만든다.","② 두 집 창문 안쪽에 뽁뽁이를 한 장씩 붙인다.","③ ㉯에만 뽁뽁이를 한 장 더, 벽에 우드록, 틈은 색점토로 막는다.","④ 지붕에 탐침 온도계를 꽂고 데운 손난로를 넣어 5분 둔다.","⑤ 손난로를 빼고 1분 간격으로 5번 온도를 잰다."],"title":"집 모형 실험 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_challenge#1','sci',5,2,'u4','L06','g5_2_sci_u4_L06_challenge','lesson_challenge','SC5-2-u4-C19',2,'match','auto','에너지를 아끼는 집 그림의 시설과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u4-C19","difficulty":2,"kind":"match","stem":"에너지를 아끼는 집 그림의 시설과 하는 일을 알맞게 이으세요.","pairs":[{"l":"벽 속 단열재","r":"열이 빠져나가는 것을 막음"},{"l":"지붕 위 태양 전지판","r":"햇빛으로 에너지를 만듦"},{"l":"햇빛 방향에 따라 움직이는 차양","r":"들어오는 햇빛을 알맞게 조절함"}],"mis":"SC5-2-u4-X35","explanation":["단열재는 막아요.","전지판은 만들어요.","차양은 조절해요."],"asset":{"type":"passage","lines":["㉠ 벽 속 단열재","㉡ 이중창","㉢ 햇빛 방향에 따라 움직이는 차양","㉣ 지붕 위 태양 전지판","㉤ 땅속 열을 쓰는 냉난방","㉥ 옥상 정원"],"title":"에너지를 아끼는 집 그림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_challenge#2','sci',5,2,'u4','L06','g5_2_sci_u4_L06_challenge','lesson_challenge','SC5-2-u4-C17',2,'mc','auto','집 모형 실험 차례에서 두 집을 서로 다르게 한 조건은 어느 것인가요?',ARRAY['SC5-2-u4-X31']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C17","difficulty":2,"kind":"mc","stem":"집 모형 실험 차례에서 두 집을 서로 다르게 한 조건은 어느 것인가요?","options":[{"t":"단열을 한 정도","correct":true},{"t":"집 모형의 크기","mis":"SC5-2-u4-X31"},{"t":"넣은 손난로의 종류","mis":"SC5-2-u4-X31"},{"t":"온도를 잰 시간 간격","mis":"SC5-2-u4-X31"}],"explanation":["㉯만 더 했어요.","단열이 달라요.","나머지는 같아요."],"asset":{"type":"passage","lines":["① 크기와 모양이 같은 집 모형 ㉮, ㉯를 만든다.","② 두 집 창문 안쪽에 뽁뽁이를 한 장씩 붙인다.","③ ㉯에만 뽁뽁이를 한 장 더, 벽에 우드록, 틈은 색점토로 막는다.","④ 지붕에 탐침 온도계를 꽂고 데운 손난로를 넣어 5분 둔다.","⑤ 손난로를 빼고 1분 간격으로 5번 온도를 잰다."],"title":"집 모형 실험 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_challenge#3','sci',5,2,'u4','L06','g5_2_sci_u4_L06_challenge','lesson_challenge','SC5-2-u4-C18',3,'mc','auto','처음 온도가 다른 두 집 모형에서 단열한 집은 어느 것이고, 그 까닭은 무엇인가요?',ARRAY['SC5-2-u4-X34','SC5-2-u4-X33']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C18","difficulty":3,"kind":"mc","stem":"처음 온도가 다른 두 집 모형에서 단열한 집은 어느 것이고, 그 까닭은 무엇인가요?","options":[{"t":"(나), 온도 변화량이 2.8 °C로 (가)의 6.2 °C보다 작아서","correct":true},{"t":"(가), 처음 온도가 더 높아서","mis":"SC5-2-u4-X34"},{"t":"(가), 온도 변화량이 더 커서","mis":"SC5-2-u4-X33"},{"t":"(나), 5분 뒤 온도만 보면 되니까","mis":"SC5-2-u4-X34"}],"explanation":["처음 온도가 달라요.","변화량을 구해요.","(나)가 덜 변했어요."],"asset":{"type":"passage","lines":["(가) 처음 31.0 °C → 5분 뒤 24.8 °C","(나) 처음 30.0 °C → 5분 뒤 27.2 °C","두 집 가운데 한 집만 단열을 하였다."],"title":"처음 온도가 다른 두 집 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_challenge#4','sci',5,2,'u4','L06','g5_2_sci_u4_L06_challenge','lesson_challenge','SC5-2-u4-C18',3,'sa','auto','처음 온도가 다른 두 집 모형에서 (가)의 온도 변화량은 몇 °C인가요? 숫자만 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-2-u4-C18","difficulty":3,"kind":"sa","stem":"처음 온도가 다른 두 집 모형에서 (가)의 온도 변화량은 몇 °C인가요? 숫자만 쓰세요.","answer":["6.2","6.2 °C","6.2도"],"explanation":["처음 31.0 °C예요.","5분 뒤 24.8 °C예요.","6.2 °C예요."],"asset":{"type":"passage","lines":["(가) 처음 31.0 °C → 5분 뒤 24.8 °C","(나) 처음 30.0 °C → 5분 뒤 27.2 °C","두 집 가운데 한 집만 단열을 하였다."],"title":"처음 온도가 다른 두 집 모형"},"mis":"SC5-2-u4-X34"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_challenge#5','sci',5,2,'u4','L06','g5_2_sci_u4_L06_challenge','lesson_challenge','SC5-2-u4-C18',3,'ox','auto','처음 온도가 다른 두 집은 5분 뒤 온도만 견주어도 단열 효과를 알 수 있어요.',ARRAY['SC5-2-u4-X34']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C18","difficulty":3,"kind":"ox","stem":"처음 온도가 다른 두 집은 5분 뒤 온도만 견주어도 단열 효과를 알 수 있어요.","answer":"X","reason_options":[{"t":"처음 온도가 달라 온도 변화량을 구해 견주어야 하기 때문에","correct":true},{"t":"마지막 온도가 높은 집이 언제나 단열이 잘된 집이기 때문에","mis":"SC5-2-u4-X34"}],"mis":"SC5-2-u4-X34","explanation":["처음이 달라요.","변화량을 구해요.","그래야 공정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_challenge#6','sci',5,2,'u4','L06','g5_2_sci_u4_L06_challenge','lesson_challenge','SC5-2-u4-C19',3,'error','auto','단열한 집 모형을 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X36','SC5-2-u4-X33']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C19","difficulty":3,"kind":"error","stem":"단열한 집 모형을 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서진 — 「우드록과 색점토가 스스로 따뜻해져서 집을 데워 줘.」","correct":true,"mis_target":"SC5-2-u4-X36"},{"t":"나윤 — 「색점토로 틈을 막으니 열이 덜 새.」","mis":"SC5-2-u4-X36"},{"t":"이현 — 「뽁뽁이를 두 겹 붙이면 단열이 더 잘돼.」","mis":"SC5-2-u4-X33"}],"explanation":["단열재는 막을 뿐이에요.","스스로 열을 내지 않아요.","서진의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_challenge#7','sci',5,2,'u4','L06','g5_2_sci_u4_L06_challenge','lesson_challenge','SC5-2-u4-C19',3,'mc','auto','전 세계에서 함께 한 시간 불을 끄는 날(어스아워) 캠페인을 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X29','SC5-2-u4-X42','SC5-2-u4-X27']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C19","difficulty":3,"kind":"mc","stem":"전 세계에서 함께 한 시간 불을 끄는 날(어스아워) 캠페인을 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"에너지 절약이 왜 필요한지 알리고 함께 실천하려고","correct":true},{"t":"불을 끄면 에너지가 새로 생겨나서","mis":"SC5-2-u4-X29"},{"t":"재생 에너지가 있어 원래는 아낄 필요가 없어서","mis":"SC5-2-u4-X42"},{"t":"전등의 효율 등급을 바꾸려고","mis":"SC5-2-u4-X27"}],"explanation":["불을 함께 꺼요.","절약을 알려요.","함께 실천해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_challenge#8','sci',5,2,'u4','L06','g5_2_sci_u4_L06_challenge','lesson_challenge','SC5-2-u4-C17',4,'mc','auto','집 모형 실험 결과를 더 믿을 수 있게 하는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X31','SC5-2-u4-X32']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C17","difficulty":4,"kind":"mc","stem":"집 모형 실험 결과를 더 믿을 수 있게 하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"같은 실험을 여러 번 되풀이해 결과가 비슷한지 확인한다","correct":true},{"t":"한 집에만 손난로를 더 오래 넣는다","mis":"SC5-2-u4-X31"},{"t":"두 집을 서로 다른 때에 따로 잰다","mis":"SC5-2-u4-X31"},{"t":"탐침 끝을 바닥에 닿게 한다","mis":"SC5-2-u4-X32"}],"explanation":["되풀이해요.","결과를 견줘요.","믿을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_challenge#9','sci',5,2,'u4','L06','g5_2_sci_u4_L06_challenge','lesson_challenge','SC5-2-u4-C19',4,'mc','auto','사계절 내내 에너지를 아끼는 집을 설계한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X35','SC5-2-u4-X36','SC5-2-u4-X33']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C19","difficulty":4,"kind":"mc","stem":"사계절 내내 에너지를 아끼는 집을 설계한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"벽과 지붕을 단열하고 이중창을 달며, 태양 빛과 땅속 열로 에너지를 만들어 쓴다","correct":true},{"t":"얇은 한 겹 창을 크게 내고 냉난방을 세게 켠다","mis":"SC5-2-u4-X35"},{"t":"단열재가 열을 내니 난방기를 없앤다","mis":"SC5-2-u4-X36"},{"t":"지붕과 벽에 틈을 넓게 낸다","mis":"SC5-2-u4-X33"}],"explanation":["열을 막아요.","에너지를 만들어요.","둘 다 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L06_challenge#10','sci',5,2,'u4','L06','g5_2_sci_u4_L06_challenge','lesson_challenge','SC5-2-u4-C18',4,'essay','teacher','두 집 모형 안의 온도 그래프를 보고 두 집의 온도 변화량을 견주어 쓰고, 이 결과를 실제 집에 어떻게 쓸 수 있는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u4-C18","difficulty":4,"kind":"essay","stem":"두 집 모형 안의 온도 그래프를 보고 두 집의 온도 변화량을 견주어 쓰고, 이 결과를 실제 집에 어떻게 쓸 수 있는지 쓰세요.","answer_guide":{"answer":"예: 단열 안 한 집은 4.5 °C, 단열한 집은 2.5 °C 낮아져 단열한 집의 온도 변화가 더 작다. 단열을 하면 집 안 온도를 잘 지켜 에너지 효율이 높아지므로, 실제 집에도 단열재와 이중창을 쓰면 냉난방 에너지를 아낄 수 있다.","scoring_points":["두 집의 온도 변화량을 바르게 썼는가","변화가 작은 집이 효율이 높다고 썼는가","실제 집에 쓸 방법(단열재·이중창 등)을 썼는가"]},"explanation":["변화량을 구해요.","덜 변한 집이에요.","실제 집에 써요."],"asset":{"type":"lgraph","xs":["처음","1","2","3","4","5"],"series":[{"name":"단열 안 한 집","vals":[30,28,27,26.5,26,25.5]},{"name":"단열한 집","vals":[30,29.5,29,28.5,28,27.5]}],"step":0.5,"y0":24,"wave":true,"ymax":31,"ylab":"(°C)","xlab":"(분 뒤)","title":"두 집 모형 안의 온도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_basic#1','sci',5,2,'u4','L07','g5_2_sci_u4_L07_basic','lesson_basic','SC5-2-u4-C20',1,'mc','auto','자원과 에너지를 효율적으로 이용하는 실천 영상의 주제로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X37','SC5-2-u4-X38']::text[],false,'{"seq":1,"concept":"SC5-2-u4-C20","difficulty":1,"kind":"mc","stem":"자원과 에너지를 효율적으로 이용하는 실천 영상의 주제로 알맞은 것은 어느 것인가요?","options":[{"t":"양치할 때 양치 컵에 물을 받아 쓰기","correct":true},{"t":"좋아하는 과자 소개하기","mis":"SC5-2-u4-X37"},{"t":"친구 얼굴을 몰래 찍기","mis":"SC5-2-u4-X38"},{"t":"하루 종일 텔레비전 켜 두기","mis":"SC5-2-u4-X37"}],"explanation":["생활 속 실천이에요.","물을 아껴요.","알맞은 주제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_basic#2','sci',5,2,'u4','L07','g5_2_sci_u4_L07_basic','lesson_basic','SC5-2-u4-C20',1,'mc','auto','모둠 역할 나누기에서 장면마다 할 말을 쓰는 역할은 어느 것인가요?',ARRAY['SC5-2-u4-X37']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C20","difficulty":1,"kind":"mc","stem":"모둠 역할 나누기에서 장면마다 할 말을 쓰는 역할은 어느 것인가요?","options":[{"t":"대본","correct":true},{"t":"촬영","mis":"SC5-2-u4-X37"},{"t":"소품","mis":"SC5-2-u4-X37"},{"t":"감독","mis":"SC5-2-u4-X37"}],"explanation":["할 말을 써요.","대사를 정해요.","대본이에요."],"asset":{"type":"passage","lines":["감독 — 영상의 흐름을 정하고 이끈다.","대본 — 장면마다 할 말을 쓴다.","촬영 — 스마트 기기로 장면을 찍는다.","소품 — 다 쓴 상자로 팻말을 만든다."],"title":"모둠 역할 나누기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_basic#3','sci',5,2,'u4','L07','g5_2_sci_u4_L07_basic','lesson_basic','SC5-2-u4-C20',1,'ox','auto','실천 영상에 친구의 이름과 사는 곳을 크게 넣어 누리망에 올려요.',ARRAY['SC5-2-u4-X38']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C20","difficulty":1,"kind":"ox","stem":"실천 영상에 친구의 이름과 사는 곳을 크게 넣어 누리망에 올려요.","answer":"X","reason_options":[{"t":"나와 다른 사람의 개인 정보를 누리망에 함부로 올리면 안 되기 때문에","correct":true},{"t":"개인 정보를 넣어야 영상이 더 재미있기 때문에","mis":"SC5-2-u4-X38"}],"mis":"SC5-2-u4-X38","explanation":["개인 정보예요.","함부로 올리면 안 돼요.","빼고 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_basic#4','sci',5,2,'u4','L07','g5_2_sci_u4_L07_basic','lesson_basic','SC5-2-u4-C20',1,'mc','auto','촬영할 장면과 상황을 글과 그림으로 미리 정리한 것을 무엇이라고 하나요?',ARRAY['SC5-2-u4-X37']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C20","difficulty":1,"kind":"mc","stem":"촬영할 장면과 상황을 글과 그림으로 미리 정리한 것을 무엇이라고 하나요?","options":[{"t":"스토리 보드","correct":true},{"t":"영수증","mis":"SC5-2-u4-X37"},{"t":"놀이판","mis":"SC5-2-u4-X37"},{"t":"일기장","mis":"SC5-2-u4-X37"}],"explanation":["장면을 미리 그려요.","글도 써요.","스토리 보드예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_basic#5','sci',5,2,'u4','L07','g5_2_sci_u4_L07_basic','lesson_basic','SC5-2-u4-C20',2,'mc','auto','하늘 모둠 스토리 보드 ① 장면이 보여 주는 문제는 어느 것인가요?',ARRAY['SC5-2-u4-X28','SC5-2-u4-X37']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C20","difficulty":2,"kind":"mc","stem":"하늘 모둠 스토리 보드 ① 장면이 보여 주는 문제는 어느 것인가요?","options":[{"t":"비누칠하는 동안 물을 틀어 놓아 낭비한다","correct":true},{"t":"물을 너무 아껴 손이 더럽다","mis":"SC5-2-u4-X28"},{"t":"전등을 꺼서 어둡다","mis":"SC5-2-u4-X37"},{"t":"양치 컵을 써서 물이 모자란다","mis":"SC5-2-u4-X28"}],"explanation":["물을 틀어 놓았어요.","「잠깐!」이라고 해요.","물 낭비예요."],"asset":{"type":"passage","lines":["① 수도꼭지를 틀어 놓고 비누칠하는 친구 — 「잠깐!」","② 물을 잠그고 비누칠하는 모습","③ 양치 컵에 물을 받아 양치하는 모습","④ 화면 글 — 「물을 아껴 지구를 지켜요」"],"title":"하늘 모둠 스토리 보드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_basic#6','sci',5,2,'u4','L07','g5_2_sci_u4_L07_basic','lesson_basic','SC5-2-u4-C15',2,'mc','auto','영상에 쓸 팻말 소품을 만들 재료로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X28']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C15","difficulty":2,"kind":"mc","stem":"영상에 쓸 팻말 소품을 만들 재료로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"다 쓴 상자 같은 재활용품","correct":true},{"t":"새로 산 플라스틱 판 여러 장","mis":"SC5-2-u4-X28"},{"t":"한 번 쓰고 버릴 종이컵 묶음","mis":"SC5-2-u4-X28"},{"t":"비닐을 겹겹이 두른 새 포장지","mis":"SC5-2-u4-X28"}],"explanation":["소품도 아껴요.","재활용품을 써요.","상자로 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_basic#7','sci',5,2,'u4','L07','g5_2_sci_u4_L07_basic','lesson_basic','SC5-2-u4-C20',2,'ox','auto','다른 모둠의 실천 영상에 댓글을 달 때는 바르고 고운 말을 써요.',ARRAY['SC5-2-u4-X38']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C20","difficulty":2,"kind":"ox","stem":"다른 모둠의 실천 영상에 댓글을 달 때는 바르고 고운 말을 써요.","answer":"O","reason_options":[{"t":"상대를 존중하고 배려해야 하기 때문에","correct":true},{"t":"댓글은 아무도 안 보니 함부로 써도 되기 때문에","mis":"SC5-2-u4-X38"}],"mis":"SC5-2-u4-X38","explanation":["댓글도 말이에요.","존중해요.","고운 말을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_basic#8','sci',5,2,'u4','L07','g5_2_sci_u4_L07_basic','lesson_basic','SC5-2-u4-C16',2,'mc','auto','전기를 아끼는 실천 영상에 넣기 알맞은 장면은 어느 것인가요?',ARRAY['SC5-2-u4-X25','SC5-2-u4-X23']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C16","difficulty":2,"kind":"mc","stem":"전기를 아끼는 실천 영상에 넣기 알맞은 장면은 어느 것인가요?","options":[{"t":"쓰지 않는 전기 기구의 전원을 끄고 플러그를 뽑는다","correct":true},{"t":"보지 않는 텔레비전을 켜 둔다","mis":"SC5-2-u4-X25"},{"t":"에어컨을 켠 채 문을 연다","mis":"SC5-2-u4-X23"},{"t":"빈방 조명을 켜 둔다","mis":"SC5-2-u4-X23"}],"explanation":["전원을 꺼요.","플러그를 뽑아요.","전기를 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_basic#9','sci',5,2,'u4','L07','g5_2_sci_u4_L07_basic','lesson_basic','SC5-2-u4-C20',2,'mc','auto','실천 영상을 공유한 뒤에 해야 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X39','SC5-2-u4-X38']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C20","difficulty":2,"kind":"mc","stem":"실천 영상을 공유한 뒤에 해야 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"영상에 담은 실천을 나부터 꾸준히 이어 간다","correct":true},{"t":"영상을 올렸으니 실천은 그만둔다","mis":"SC5-2-u4-X39"},{"t":"다른 모둠 영상을 깎아내리는 댓글을 단다","mis":"SC5-2-u4-X38"},{"t":"영상을 지우고 잊어버린다","mis":"SC5-2-u4-X39"}],"explanation":["영상은 시작이에요.","나부터 해요.","꾸준히 이어 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_basic#10','sci',5,2,'u4','L07','g5_2_sci_u4_L07_basic','lesson_basic','SC5-2-u4-C20',3,'error','auto','실천 영상을 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X39','SC5-2-u4-X38','SC5-2-u4-X37']::text[],false,'{"seq":10,"concept":"SC5-2-u4-C20","difficulty":3,"kind":"error","stem":"실천 영상을 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지율 — 「영상에서 실천하는 척만 하고 실제로는 안 해도 돼.」","correct":true,"mis_target":"SC5-2-u4-X39"},{"t":"하온 — 「촬영할 장소는 안전한 곳으로 정해.」","mis":"SC5-2-u4-X38"},{"t":"시하 — 「역할을 나누면 더 잘 만들 수 있어.」","mis":"SC5-2-u4-X37"}],"explanation":["영상은 실천을 알려요.","나도 실천해야 해요.","지율의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_challenge#1','sci',5,2,'u4','L07','g5_2_sci_u4_L07_challenge','lesson_challenge','SC5-2-u4-C20',2,'match','auto','모둠 역할 나누기의 역할과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u4-C20","difficulty":2,"kind":"match","stem":"모둠 역할 나누기의 역할과 하는 일을 알맞게 이으세요.","pairs":[{"l":"감독","r":"영상의 흐름을 정하고 이끈다"},{"l":"촬영","r":"스마트 기기로 장면을 찍는다"},{"l":"소품","r":"다 쓴 상자로 팻말을 만든다"}],"mis":"SC5-2-u4-X37","explanation":["감독은 이끌어요.","촬영은 찍어요.","소품은 만들어요."],"asset":{"type":"passage","lines":["감독 — 영상의 흐름을 정하고 이끈다.","대본 — 장면마다 할 말을 쓴다.","촬영 — 스마트 기기로 장면을 찍는다.","소품 — 다 쓴 상자로 팻말을 만든다."],"title":"모둠 역할 나누기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
