INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_challenge#3','sci',5,2,'u4','L07','g5_2_sci_u4_L07_challenge','lesson_challenge','SC5-2-u4-C20',3,'mc','auto','실천 영상을 촬영할 장소로 가장 알맞은 곳은 어느 것인가요?',ARRAY['SC5-2-u4-X38']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C20","difficulty":3,"kind":"mc","stem":"실천 영상을 촬영할 장소로 가장 알맞은 곳은 어느 것인가요?","options":[{"t":"사람이 다니는 안전한 교실이나 집 안","correct":true},{"t":"사람이 거의 없는 어두운 공사장","mis":"SC5-2-u4-X38"},{"t":"차가 다니는 찻길 한가운데","mis":"SC5-2-u4-X38"},{"t":"물이 깊은 강가","mis":"SC5-2-u4-X38"}],"explanation":["안전이 먼저예요.","위험한 곳은 피해요.","교실이나 집 안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_challenge#4','sci',5,2,'u4','L07','g5_2_sci_u4_L07_challenge','lesson_challenge','SC5-2-u4-C15',3,'mc','auto','음식물 쓰레기를 줄이는 실천 영상에 넣기 알맞은 장면은 어느 것인가요?',ARRAY['SC5-2-u4-X28','SC5-2-u4-X37']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C15","difficulty":3,"kind":"mc","stem":"음식물 쓰레기를 줄이는 실천 영상에 넣기 알맞은 장면은 어느 것인가요?","options":[{"t":"먹을 만큼만 요리하고 남김없이 먹는 모습","correct":true},{"t":"음식을 많이 남기고 버리는 모습","mis":"SC5-2-u4-X28"},{"t":"음식을 일회용 그릇에 담아 바로 버리는 모습","mis":"SC5-2-u4-X28"},{"t":"음식과 상관없는 춤 장면","mis":"SC5-2-u4-X37"}],"explanation":["먹을 만큼만 해요.","남기지 않아요.","쓰레기가 줄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_challenge#5','sci',5,2,'u4','L07','g5_2_sci_u4_L07_challenge','lesson_challenge','SC5-2-u4-C20',3,'ox','auto','스토리 보드에 다른 사람을 놀리거나 비하하는 장면을 넣어도 웃기면 괜찮아요.',ARRAY['SC5-2-u4-X38']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C20","difficulty":3,"kind":"ox","stem":"스토리 보드에 다른 사람을 놀리거나 비하하는 장면을 넣어도 웃기면 괜찮아요.","answer":"X","reason_options":[{"t":"다른 사람에게 불쾌감을 주는 내용은 넣지 않아야 하기 때문에","correct":true},{"t":"재미있으면 무엇이든 넣어도 되기 때문에","mis":"SC5-2-u4-X38"}],"mis":"SC5-2-u4-X38","explanation":["불쾌감을 줘요.","존중해야 해요.","넣지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_challenge#6','sci',5,2,'u4','L07','g5_2_sci_u4_L07_challenge','lesson_challenge','SC5-2-u4-C20',3,'error','auto','실천 영상 주제를 정하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X37']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C20","difficulty":3,"kind":"error","stem":"실천 영상 주제를 정하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은재 — 「우주에 발전소를 짓는 모습을 실천 영상으로 찍자.」","correct":true,"mis_target":"SC5-2-u4-X37"},{"t":"해솔 — 「분리배출 하는 모습을 찍자.」","mis":"SC5-2-u4-X37"},{"t":"다빈 — 「자전거 타고 등교하는 모습도 좋아.」","mis":"SC5-2-u4-X37"}],"explanation":["생활에서 할 수 있어야 해요.","우주 발전소는 어려워요.","은재의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_challenge#7','sci',5,2,'u4','L07','g5_2_sci_u4_L07_challenge','lesson_challenge','SC5-2-u4-C16',3,'mc','auto','교실에서 난방 에너지를 아끼는 실천 영상에 넣기 알맞은 장면은 어느 것인가요?',ARRAY['SC5-2-u4-X23']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C16","difficulty":3,"kind":"mc","stem":"교실에서 난방 에너지를 아끼는 실천 영상에 넣기 알맞은 장면은 어느 것인가요?","options":[{"t":"「문을 닫아요」 팻말을 들고 난방 중인 교실 문을 닫는 모습","correct":true},{"t":"창문을 활짝 열고 난방을 세게 켜는 모습","mis":"SC5-2-u4-X23"},{"t":"빈 교실의 난방기를 켜 두는 모습","mis":"SC5-2-u4-X23"},{"t":"복도 전등을 모두 켜는 모습","mis":"SC5-2-u4-X23"}],"explanation":["난방 중이에요.","문을 닫아요.","열을 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_challenge#8','sci',5,2,'u4','L07','g5_2_sci_u4_L07_challenge','lesson_challenge','SC5-2-u4-C20',4,'mc','auto','더 많은 사람이 함께 실천하게 하려면 영상을 어떻게 쓰는 것이 가장 알맞은가요?',ARRAY['SC5-2-u4-X39','SC5-2-u4-X38','SC5-2-u4-X37']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C20","difficulty":4,"kind":"mc","stem":"더 많은 사람이 함께 실천하게 하려면 영상을 어떻게 쓰는 것이 가장 알맞은가요?","options":[{"t":"학급 누리집에 올려 가족과 이웃에게도 알리고 함께 실천하자고 권한다","correct":true},{"t":"혼자만 보고 아무에게도 알리지 않는다","mis":"SC5-2-u4-X39"},{"t":"친구 집 주소를 함께 적어 퍼뜨린다","mis":"SC5-2-u4-X38"},{"t":"실천과 상관없는 장면만 더 넣는다","mis":"SC5-2-u4-X37"}],"explanation":["널리 알려요.","함께하자고 해요.","실천이 퍼져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_challenge#9','sci',5,2,'u4','L07','g5_2_sci_u4_L07_challenge','lesson_challenge','SC5-2-u4-C20',4,'mc','auto','다른 모둠의 물 절약 영상에 단 댓글로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X38','SC5-2-u4-X39']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C20","difficulty":4,"kind":"mc","stem":"다른 모둠의 물 절약 영상에 단 댓글로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「설거지통에 물을 받아 쓰는 방법을 우리 집에도 알려야겠어요.」","correct":true},{"t":"「이런 걸 왜 찍었어요?」","mis":"SC5-2-u4-X38"},{"t":"「영상 속 친구 이름이 뭐예요? 어디 살아요?」","mis":"SC5-2-u4-X38"},{"t":"「나는 그냥 물을 계속 틀어 놓을래요.」","mis":"SC5-2-u4-X39"}],"explanation":["배운 점을 써요.","고운 말이에요.","실천도 다짐해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L07_challenge#10','sci',5,2,'u4','L07','g5_2_sci_u4_L07_challenge','lesson_challenge','SC5-2-u4-C20',4,'essay','teacher','우리 모둠의 실천 영상 계획을 쓰세요. 주제, 넣을 장면 두 개, 영상을 만들 때 지킬 점 하나를 넣으세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u4-C20","difficulty":4,"kind":"essay","stem":"우리 모둠의 실천 영상 계획을 쓰세요. 주제, 넣을 장면 두 개, 영상을 만들 때 지킬 점 하나를 넣으세요.","answer_guide":{"answer":"예: 주제 — 교실 전기 아끼기. 장면 1 — 이동 수업 때 전등을 끄는 모습. 장면 2 — 쓰지 않는 기기의 플러그를 뽑는 모습. 지킬 점 — 친구의 이름이나 얼굴 같은 개인 정보는 허락 없이 넣지 않는다.","scoring_points":["생활에서 실천할 수 있는 주제를 정했는가","주제에 맞는 실천 장면을 두 개 썼는가","지킬 점(개인 정보·존중·안전 등)을 썼는가"]},"explanation":["주제를 정해요.","장면을 써요.","지킬 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_basic#1','sci',5,2,'u4','L08','g5_2_sci_u4_L08_basic','lesson_basic','SC5-2-u4-C21',1,'mc','auto','두 미래 에너지 전문가의 말에서 ㉮는 어떤 전문가인가요?',ARRAY['SC5-2-u4-X41']::text[],false,'{"seq":1,"concept":"SC5-2-u4-C21","difficulty":1,"kind":"mc","stem":"두 미래 에너지 전문가의 말에서 ㉮는 어떤 전문가인가요?","options":[{"t":"재생 에너지 전문가","correct":true},{"t":"에너지 하베스팅 전문가","mis":"SC5-2-u4-X41"},{"t":"석탄을 캐는 사람","mis":"SC5-2-u4-X41"},{"t":"영상 감독","mis":"SC5-2-u4-X41"}],"explanation":["태양 전지를 연구해요.","풍력 발전기도요.","재생 에너지 전문가예요."],"asset":{"type":"passage","lines":["㉮ 더 좋은 태양 전지와 풍력 발전기를 연구하고, 발전기를 세울 알맞은 곳을 찾아요.","㉯ 새어 나가는 빛, 자동차의 떨림, 체온처럼 그냥 버려지는 에너지를 모아 쓰는 방법을 연구해요."],"title":"두 미래 에너지 전문가의 말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_basic#2','sci',5,2,'u4','L08','g5_2_sci_u4_L08_basic','lesson_basic','SC5-2-u4-C21',1,'mc','auto','일상에서 버려지는 에너지를 모아 쓰는 방법을 연구하는 사람은 누구인가요?',ARRAY['SC5-2-u4-X40']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C21","difficulty":1,"kind":"mc","stem":"일상에서 버려지는 에너지를 모아 쓰는 방법을 연구하는 사람은 누구인가요?","options":[{"t":"에너지 하베스팅 전문가","correct":true},{"t":"재생 에너지 전문가","mis":"SC5-2-u4-X40"},{"t":"자원을 마구 캐는 사람","mis":"SC5-2-u4-X40"},{"t":"집 모형을 꾸미는 사람","mis":"SC5-2-u4-X40"}],"explanation":["버려지는 에너지예요.","모아서 써요.","하베스팅 전문가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_basic#3','sci',5,2,'u4','L08','g5_2_sci_u4_L08_basic','lesson_basic','SC5-2-u4-C21',1,'ox','auto','걸을 때 바닥을 누르는 힘도 모으면 에너지로 쓸 수 있어요.',ARRAY['SC5-2-u4-X40']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C21","difficulty":1,"kind":"ox","stem":"걸을 때 바닥을 누르는 힘도 모으면 에너지로 쓸 수 있어요.","answer":"O","reason_options":[{"t":"버려지는 에너지를 모아 쓰는 기술이 있기 때문에","correct":true},{"t":"사람이 움직이는 힘은 에너지가 될 수 없기 때문에","mis":"SC5-2-u4-X40"}],"mis":"SC5-2-u4-X40","explanation":["걸을 때 힘이 생겨요.","모을 수 있어요.","에너지로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_basic#4','sci',5,2,'u4','L08','g5_2_sci_u4_L08_basic','lesson_basic','SC5-2-u4-C22',1,'mc','auto','「자원과 에너지」 단원을 정리한 말로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X11','SC5-2-u4-X42','SC5-2-u4-X21']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C22","difficulty":1,"kind":"mc","stem":"「자원과 에너지」 단원을 정리한 말로 알맞은 것은 어느 것인가요?","options":[{"t":"자원은 한정되어 있어 아끼고 효율적으로 써야 한다","correct":true},{"t":"자원은 끝없이 있어 마음껏 써도 된다","mis":"SC5-2-u4-X11"},{"t":"재생 에너지가 있으니 아낄 필요가 없다","mis":"SC5-2-u4-X42"},{"t":"석탄과 석유가 가장 깨끗한 에너지다","mis":"SC5-2-u4-X21"}],"explanation":["자원은 한정돼요.","아껴 써요.","효율적으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_basic#5','sci',5,2,'u4','L08','g5_2_sci_u4_L08_basic','lesson_basic','SC5-2-u4-C21',2,'mc','auto','에너지 놀이터 아이디어 가운데 사람이 움직일 때 생기는 힘을 모으는 것끼리 모은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X40']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C21","difficulty":2,"kind":"mc","stem":"에너지 놀이터 아이디어 가운데 사람이 움직일 때 생기는 힘을 모으는 것끼리 모은 것은 어느 것인가요?","options":[{"t":"①, ②","correct":true},{"t":"③, ④","mis":"SC5-2-u4-X40"},{"t":"③","mis":"SC5-2-u4-X40"},{"t":"①, ③","mis":"SC5-2-u4-X40"}],"explanation":["뛰면 모여요.","그네를 타면 모여요.","①과 ②예요."],"asset":{"type":"passage","lines":["① 뛰면 에너지가 모이는 바닥 타일","② 탈 때마다 에너지를 모으는 그네","③ 밤새 켜 두는 큰 조명","④ 미끄럼틀 지붕의 태양 전지판"],"title":"에너지 놀이터 아이디어"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_basic#6','sci',5,2,'u4','L08','g5_2_sci_u4_L08_basic','lesson_basic','SC5-2-u4-C21',2,'mc','auto','에너지 하베스팅의 예로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X40','SC5-2-u4-X23']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C21","difficulty":2,"kind":"mc","stem":"에너지 하베스팅의 예로 알맞은 것은 어느 것인가요?","options":[{"t":"뜨거운 물이나 기구에서 버려지는 열을 모아 전기를 만든다","correct":true},{"t":"땅속 석탄을 더 많이 캔다","mis":"SC5-2-u4-X40"},{"t":"새 석탄 발전소를 짓는다","mis":"SC5-2-u4-X40"},{"t":"쓰지 않는 조명을 밤새 켜 둔다","mis":"SC5-2-u4-X23"}],"explanation":["열이 버려져요.","모아서 써요.","하베스팅이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_basic#7','sci',5,2,'u4','L08','g5_2_sci_u4_L08_basic','lesson_basic','SC5-2-u4-C21',2,'ox','auto','두 미래 에너지 전문가의 말에서 ㉮ 같은 전문가는 사람들에게 재생 에너지의 중요성을 알리는 일도 해요.',ARRAY['SC5-2-u4-X41']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C21","difficulty":2,"kind":"ox","stem":"두 미래 에너지 전문가의 말에서 ㉮ 같은 전문가는 사람들에게 재생 에너지의 중요성을 알리는 일도 해요.","answer":"O","reason_options":[{"t":"재생 에너지를 널리 쓰게 돕는 것도 할 일이기 때문에","correct":true},{"t":"재생 에너지 전문가는 석유를 더 많이 쓰게 하는 사람이기 때문에","mis":"SC5-2-u4-X41"}],"mis":"SC5-2-u4-X41","explanation":["연구도 해요.","널리 알려요.","함께 쓰게 도와요."],"asset":{"type":"passage","lines":["㉮ 더 좋은 태양 전지와 풍력 발전기를 연구하고, 발전기를 세울 알맞은 곳을 찾아요.","㉯ 새어 나가는 빛, 자동차의 떨림, 체온처럼 그냥 버려지는 에너지를 모아 쓰는 방법을 연구해요."],"title":"두 미래 에너지 전문가의 말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_basic#8','sci',5,2,'u4','L08','g5_2_sci_u4_L08_basic','lesson_basic','SC5-2-u4-C22',2,'mc','auto','방법과 그 효과를 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X35','SC5-2-u4-X30','SC5-2-u4-X27']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C22","difficulty":2,"kind":"mc","stem":"방법과 그 효과를 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"빗물 저금통 — 물 자원을 효율적으로 이용","correct":true},{"t":"이중창 — 전기를 생산","mis":"SC5-2-u4-X35"},{"t":"분리배출 — 산림 자원만 아낌","mis":"SC5-2-u4-X30"},{"t":"5등급 제품 — 효율이 가장 높음","mis":"SC5-2-u4-X27"}],"explanation":["빗물을 모아요.","다시 써요.","물을 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_basic#9','sci',5,2,'u4','L08','g5_2_sci_u4_L08_basic','lesson_basic','SC5-2-u4-C22',2,'mc','auto','자연에서 얻어 계속 쓸 수 있는 에너지끼리 모은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X13','SC5-2-u4-X21']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C22","difficulty":2,"kind":"mc","stem":"자연에서 얻어 계속 쓸 수 있는 에너지끼리 모은 것은 어느 것인가요?","options":[{"t":"태양 에너지, 지열 에너지, 바이오 에너지","correct":true},{"t":"석탄, 석유, 풍력","mis":"SC5-2-u4-X13"},{"t":"석탄, 수력, 석유","mis":"SC5-2-u4-X13"},{"t":"석유, 해양 에너지, 석탄","mis":"SC5-2-u4-X21"}],"explanation":["석탄·석유는 빼요.","자연에서 계속 얻어요.","세 가지 모두 재생 에너지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_basic#10','sci',5,2,'u4','L08','g5_2_sci_u4_L08_basic','lesson_basic','SC5-2-u4-C22',3,'error','auto','단원을 마무리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X42','SC5-2-u4-X11','SC5-2-u4-X33']::text[],false,'{"seq":10,"concept":"SC5-2-u4-C22","difficulty":3,"kind":"error","stem":"단원을 마무리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"로운 — 「재생 에너지가 있으니까 이제 전기는 마음껏 써도 돼.」","correct":true,"mis_target":"SC5-2-u4-X42"},{"t":"예솔 — 「물·산림·광물 자원은 한정되어 있어.」","mis":"SC5-2-u4-X11"},{"t":"지환 — 「단열을 하면 에너지 효율이 높아져.」","mis":"SC5-2-u4-X33"}],"explanation":["재생 에너지도 아직 모자라요.","아끼기도 함께해요.","로운의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_challenge#1','sci',5,2,'u4','L08','g5_2_sci_u4_L08_challenge','lesson_challenge','SC5-2-u4-C22',2,'match','auto','단원에서 배운 내용과 그 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u4-C22","difficulty":2,"kind":"match","stem":"단원에서 배운 내용과 그 내용을 알맞게 이으세요.","pairs":[{"l":"자원의 유한성","r":"물·산림·광물 자원은 계속 쓰기 어려움"},{"l":"지속가능한 이용","r":"재생 에너지·친환경 기술·절약"},{"l":"효율적인 이용","r":"1등급 제품·단열·재활용"}],"mis":"SC5-2-u4-X42","explanation":["자원은 한정돼요.","세 갈래로 지속가능하게요.","효율적으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_challenge#2','sci',5,2,'u4','L08','g5_2_sci_u4_L08_challenge','lesson_challenge','SC5-2-u4-C21',2,'mc','auto','일상에서 그냥 버려지는 에너지의 예로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X40']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C21","difficulty":2,"kind":"mc","stem":"일상에서 그냥 버려지는 에너지의 예로 알맞은 것은 어느 것인가요?","options":[{"t":"집 창문으로 새어 나오는 조명의 빛","correct":true},{"t":"땅속에 묻힌 석탄","mis":"SC5-2-u4-X40"},{"t":"가게에 진열된 새 건전지","mis":"SC5-2-u4-X40"},{"t":"아직 쓰지 않은 휘발유","mis":"SC5-2-u4-X40"}],"explanation":["빛이 새어 나와요.","쓰지 못하고 버려져요.","모을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_challenge#3','sci',5,2,'u4','L08','g5_2_sci_u4_L08_challenge','lesson_challenge','SC5-2-u4-C21',3,'mc','auto','학교에서 해 볼 수 있는 에너지 하베스팅 아이디어로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X23','SC5-2-u4-X21','SC5-2-u4-X25']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C21","difficulty":3,"kind":"mc","stem":"학교에서 해 볼 수 있는 에너지 하베스팅 아이디어로 알맞은 것은 어느 것인가요?","options":[{"t":"복도 바닥에 밟으면 에너지가 모이는 판을 깔아 작은 전등을 켠다","correct":true},{"t":"복도 전등을 하루 종일 켜 둔다","mis":"SC5-2-u4-X23"},{"t":"운동장에 석탄을 쌓아 태운다","mis":"SC5-2-u4-X21"},{"t":"교실 플러그를 모두 꽂아 둔다","mis":"SC5-2-u4-X25"}],"explanation":["걸을 때 힘이 생겨요.","바닥이 모아요.","전등을 켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_challenge#4','sci',5,2,'u4','L08','g5_2_sci_u4_L08_challenge','lesson_challenge','SC5-2-u4-C9',3,'mc','auto','산 위는 바람이 세고 집집마다 지붕이 넓으며 음식물 쓰레기가 많이 나오는 마을의 계획으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X18','SC5-2-u4-X21','SC5-2-u4-X19']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C9","difficulty":3,"kind":"mc","stem":"산 위는 바람이 세고 집집마다 지붕이 넓으며 음식물 쓰레기가 많이 나오는 마을의 계획으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"산 위에는 풍력, 지붕에는 태양 전지판, 음식물 쓰레기로 바이오 에너지","correct":true},{"t":"산 위에 바이오 에너지, 지붕에 수력, 쓰레기로 풍력","mis":"SC5-2-u4-X18"},{"t":"석탄을 들여와 모두 태운다","mis":"SC5-2-u4-X21"},{"t":"재생 에너지는 단점이 없으니 아무 데나 세운다","mis":"SC5-2-u4-X19"}],"explanation":["바람은 산 위예요.","햇빛은 지붕이에요.","쓰레기는 바이오예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_challenge#5','sci',5,2,'u4','L08','g5_2_sci_u4_L08_challenge','lesson_challenge','SC5-2-u4-C19',3,'ox','auto','에너지 효율이 높은 집을 짓는 친구에게 단열재와 이중창을 알려 주면 좋아요.',ARRAY['SC5-2-u4-X35']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C19","difficulty":3,"kind":"ox","stem":"에너지 효율이 높은 집을 짓는 친구에게 단열재와 이중창을 알려 주면 좋아요.","answer":"O","reason_options":[{"t":"집 안 열이 빠져나가는 것을 막아 냉난방 에너지를 아끼기 때문에","correct":true},{"t":"단열재와 이중창이 스스로 전기를 만들어 주기 때문에","mis":"SC5-2-u4-X35"}],"mis":"SC5-2-u4-X35","explanation":["열을 막아요.","냉난방을 아껴요.","효율이 높아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_challenge#6','sci',5,2,'u4','L08','g5_2_sci_u4_L08_challenge','lesson_challenge','SC5-2-u4-C21',3,'error','auto','두 미래 에너지 전문가의 말을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X40','SC5-2-u4-X41']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C21","difficulty":3,"kind":"error","stem":"두 미래 에너지 전문가의 말을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"나은 — 「㉯ 전문가는 새 석탄 광산을 찾는 사람이야.」","correct":true,"mis_target":"SC5-2-u4-X40"},{"t":"예준 — 「㉮ 전문가는 발전기를 세울 곳도 찾아.」","mis":"SC5-2-u4-X41"},{"t":"하랑 — 「㉯ 전문가는 체온도 에너지로 써.」","mis":"SC5-2-u4-X40"}],"explanation":["㉯는 버려지는 에너지를 모아요.","석탄 광산이 아니에요.","나은의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["㉮ 더 좋은 태양 전지와 풍력 발전기를 연구하고, 발전기를 세울 알맞은 곳을 찾아요.","㉯ 새어 나가는 빛, 자동차의 떨림, 체온처럼 그냥 버려지는 에너지를 모아 쓰는 방법을 연구해요."],"title":"두 미래 에너지 전문가의 말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_challenge#7','sci',5,2,'u4','L08','g5_2_sci_u4_L08_challenge','lesson_challenge','SC5-2-u4-C10',3,'mc','auto','재생 에너지 시설을 늘리자는 의견에 반대하는 쪽이 근거로 들 수 있는 것은 어느 것인가요?',ARRAY['SC5-2-u4-X13','SC5-2-u4-X20']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C10","difficulty":3,"kind":"mc","stem":"재생 에너지 시설을 늘리자는 의견에 반대하는 쪽이 근거로 들 수 있는 것은 어느 것인가요?","options":[{"t":"시설을 지을 때 생물의 보금자리가 망가지거나 소음이 생길 수 있다","correct":true},{"t":"재생 에너지는 쓰면 금방 바닥난다","mis":"SC5-2-u4-X13"},{"t":"재생 에너지는 공기를 가장 많이 더럽힌다","mis":"SC5-2-u4-X20"},{"t":"재생 에너지는 자연에서 얻을 수 없다","mis":"SC5-2-u4-X13"}],"explanation":["생태계에 영향을 줘요.","소음도 있어요.","반대 근거가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_challenge#8','sci',5,2,'u4','L08','g5_2_sci_u4_L08_challenge','lesson_challenge','SC5-2-u4-C21',4,'mc','auto','에너지 놀이터 아이디어의 ③을 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X23','SC5-2-u4-X25','SC5-2-u4-X27']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C21","difficulty":4,"kind":"mc","stem":"에너지 놀이터 아이디어의 ③을 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사람이 다가올 때만 켜지고, 낮에 모은 햇빛 에너지로 켜지는 조명","correct":true},{"t":"조명을 더 크게, 더 많이 단다","mis":"SC5-2-u4-X23"},{"t":"조명을 켠 채 플러그를 하나 더 꽂는다","mis":"SC5-2-u4-X25"},{"t":"조명을 5등급 제품으로 바꾼다","mis":"SC5-2-u4-X27"}],"explanation":["밤새 켜 두면 낭비예요.","필요할 때만 켜요.","햇빛 에너지로 켜요."],"asset":{"type":"passage","lines":["① 뛰면 에너지가 모이는 바닥 타일","② 탈 때마다 에너지를 모으는 그네","③ 밤새 켜 두는 큰 조명","④ 미끄럼틀 지붕의 태양 전지판"],"title":"에너지 놀이터 아이디어"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_challenge#9','sci',5,2,'u4','L08','g5_2_sci_u4_L08_challenge','lesson_challenge','SC5-2-u4-C22',4,'mc','auto','단원 전체를 생각한 실천 계획으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X42','SC5-2-u4-X28','SC5-2-u4-X27']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C22","difficulty":4,"kind":"mc","stem":"단원 전체를 생각한 실천 계획으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"물은 받아 쓰고 이면지를 쓰며 분리배출하고, 1등급 제품과 재생 에너지에 관심을 갖는다","correct":true},{"t":"재생 에너지만 있으면 되니 다른 실천은 안 한다","mis":"SC5-2-u4-X42"},{"t":"편하게 짧은 거리도 자동차를 탄다","mis":"SC5-2-u4-X28"},{"t":"효율 등급 숫자가 큰 제품을 고른다","mis":"SC5-2-u4-X27"}],"explanation":["자원을 아껴요.","에너지도 효율적으로요.","함께 실천해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_L08_challenge#10','sci',5,2,'u4','L08','g5_2_sci_u4_L08_challenge','lesson_challenge','SC5-2-u4-C21',4,'essay','teacher','미래 에너지 전문가가 되어 우리 학교에서 버려지는 에너지를 찾아 모아 쓰는 아이디어를 쓰세요. 어떤 에너지가 버려지는지와 어디에 쓸지 넣으세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u4-C21","difficulty":4,"kind":"essay","stem":"미래 에너지 전문가가 되어 우리 학교에서 버려지는 에너지를 찾아 모아 쓰는 아이디어를 쓰세요. 어떤 에너지가 버려지는지와 어디에 쓸지 넣으세요.","answer_guide":{"answer":"예: 계단을 오르내릴 때 바닥을 누르는 힘이 버려진다. 계단 바닥에 밟으면 에너지가 모이는 판을 깔아 모은 에너지로 계단 비상등을 켠다.","scoring_points":["학교에서 버려지는 에너지를 찾았는가","그 에너지를 모으는 방법을 썼는가","모은 에너지를 쓸 곳을 썼는가"]},"explanation":["버려지는 것을 찾아요.","모으는 방법이에요.","쓸 곳을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#1','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C2',1,'mc','auto','누리반 탐방 일지 ①에서 전구에 불이 켜진 때는 언제인가요?',ARRAY['SC5-2-u4-X01','SC5-2-u4-X03']::text[],false,'{"seq":1,"concept":"SC5-2-u4-C2","difficulty":1,"kind":"mc","stem":"누리반 탐방 일지 ①에서 전구에 불이 켜진 때는 언제인가요?","options":[{"t":"날개가 빨리 돌 때","correct":true},{"t":"날개가 멈췄을 때","mis":"SC5-2-u4-X01"},{"t":"바람이 전혀 없을 때","mis":"SC5-2-u4-X03"},{"t":"전구를 손으로 덮었을 때","mis":"SC5-2-u4-X01"}],"explanation":["바람을 보냈어요.","날개가 빨리 돌아요.","불이 켜졌어요."],"asset":{"type":"passage","lines":["배에서 내리자 언덕 위 풍력 발전기의 긴 날개 세 개가 돌고 있었다.","우리는 풍력 발전 모형에 머리 말리개 바람을 보냈다.","날개가 빨리 돌자 전구에 불이 켜졌다.","해설사: 「바람이 약한 날엔 날개가 천천히 돌아요.」"],"title":"① 첫날 — 바람의 섬에 도착"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#2','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C4',1,'mc','auto','누리반 탐방 일지 ②에서 우물물과 빗물은 어떤 자원인가요?',ARRAY['SC5-2-u4-X06']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C4","difficulty":1,"kind":"mc","stem":"누리반 탐방 일지 ②에서 우물물과 빗물은 어떤 자원인가요?","options":[{"t":"물 자원","correct":true},{"t":"산림 자원","mis":"SC5-2-u4-X06"},{"t":"광물 자원","mis":"SC5-2-u4-X06"},{"t":"바람 자원","mis":"SC5-2-u4-X06"}],"explanation":["물이에요.","마시고 씻어요.","물 자원이에요."],"asset":{"type":"passage","lines":["섬 사람들은 우물물과 빗물을 모아 쓴다.","뒷산 나무로 집을 지었는데, 다시 자라려면 오래 걸린다고 한다.","옛 돌 광산은 묻혀 있던 돌이 바닥나 문을 닫았다.","섬마을 이장님: 「캔은 꼭 분리배출해요.」"],"title":"② 첫날 오후 — 섬의 자원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#3','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C5',1,'mc','auto','누리반 탐방 일지 ②에서 옛 돌 광산이 문을 닫은 까닭은 어느 것인가요?',ARRAY['SC5-2-u4-X10','SC5-2-u4-X11','SC5-2-u4-X05']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C5","difficulty":1,"kind":"mc","stem":"누리반 탐방 일지 ②에서 옛 돌 광산이 문을 닫은 까닭은 어느 것인가요?","options":[{"t":"묻혀 있던 돌의 양이 한정되어 바닥났기 때문이다","correct":true},{"t":"돌이 너무 빨리 다시 생겨서","mis":"SC5-2-u4-X10"},{"t":"돌을 재활용해 끝없이 쓸 수 있어서","mis":"SC5-2-u4-X11"},{"t":"돌은 자원이 아니어서","mis":"SC5-2-u4-X05"}],"explanation":["묻힌 양이 정해져 있어요.","다 캐냈어요.","바닥났어요."],"asset":{"type":"passage","lines":["섬 사람들은 우물물과 빗물을 모아 쓴다.","뒷산 나무로 집을 지었는데, 다시 자라려면 오래 걸린다고 한다.","옛 돌 광산은 묻혀 있던 돌이 바닥나 문을 닫았다.","섬마을 이장님: 「캔은 꼭 분리배출해요.」"],"title":"② 첫날 오후 — 섬의 자원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#4','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C8',1,'mc','auto','누리반 탐방 일지 ③에서 바닷가 둑의 시설이 얻는 재생 에너지는 어느 것인가요?',ARRAY['SC5-2-u4-X14','SC5-2-u4-X17']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C8","difficulty":1,"kind":"mc","stem":"누리반 탐방 일지 ③에서 바닷가 둑의 시설이 얻는 재생 에너지는 어느 것인가요?","options":[{"t":"해양 에너지","correct":true},{"t":"수력","mis":"SC5-2-u4-X14"},{"t":"지열 에너지","mis":"SC5-2-u4-X14"},{"t":"바이오 에너지","mis":"SC5-2-u4-X17"}],"explanation":["밀물과 썰물이에요.","바다예요.","해양 에너지예요."],"asset":{"type":"passage","lines":["언덕 — 풍력 발전기","집 지붕 — 태양 전지판","바닷가 둑 — 밀물과 썰물을 쓰는 발전 시설","돼지 농장 — 분뇨로 가스를 만드는 시설","마을 회관 땅속 — 땅속 열을 쓰는 냉난방"],"title":"③ 둘째 날 — 섬의 재생 에너지 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#5','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C9',1,'mc','auto','바람솔섬 언덕에 풍력 발전기를 세운 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X18','SC5-2-u4-X21']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C9","difficulty":1,"kind":"mc","stem":"바람솔섬 언덕에 풍력 발전기를 세운 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"언덕에 바람이 세고 자주 불어서","correct":true},{"t":"언덕에 가축이 많아서","mis":"SC5-2-u4-X18"},{"t":"언덕에 물이 세차게 흘러서","mis":"SC5-2-u4-X18"},{"t":"언덕 땅속에 석탄이 많아서","mis":"SC5-2-u4-X21"}],"explanation":["섬은 바람이 세요.","언덕은 더 세요.","풍력에 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#6','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C11',1,'mc','auto','누리반 탐방 일지 ④의 결정에서 「미래 세대를 생각한다」는 것은 무엇을 뜻하나요?',ARRAY['SC5-2-u4-X22','SC5-2-u4-X21']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C11","difficulty":1,"kind":"mc","stem":"누리반 탐방 일지 ④의 결정에서 「미래 세대를 생각한다」는 것은 무엇을 뜻하나요?","options":[{"t":"지금 쓰면서도 미래 세대가 쓸 에너지를 지킨다","correct":true},{"t":"지금 세대만 마음껏 쓴다","mis":"SC5-2-u4-X22"},{"t":"미래에는 에너지가 필요 없다","mis":"SC5-2-u4-X22"},{"t":"석유를 빨리 다 쓴다","mis":"SC5-2-u4-X21"}],"explanation":["지금도 써요.","미래도 생각해요.","지속가능이에요."],"asset":{"type":"passage","lines":["주민 1: 「바람이 약한 날은 전기가 모자라요.」","주민 2: 「옛날처럼 석유 발전기를 다시 돌립시다.」","주민 3: 「에너지를 모아 두는 기술을 들이고 모두 함께 아껴 씁시다.」","결정 — 재생 에너지를 늘리고 절약하며, 미래 세대를 생각한다."],"title":"④ 둘째 날 저녁 — 마을 회의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#7','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C14',1,'mc','auto','누리반 탐방 일지 ⑤의 두 냉장고 가운데 에너지 효율이 더 높은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X27']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C14","difficulty":1,"kind":"mc","stem":"누리반 탐방 일지 ⑤의 두 냉장고 가운데 에너지 효율이 더 높은 것은 어느 것인가요?","options":[{"t":"냉장고 ㉮","correct":true},{"t":"냉장고 ㉯","mis":"SC5-2-u4-X27"},{"t":"둘이 같다","mis":"SC5-2-u4-X27"},{"t":"등급으로는 알 수 없다","mis":"SC5-2-u4-X27"}],"explanation":["㉮는 1등급이에요.","1등급에 가까울수록요.","㉮예요."],"asset":{"type":"passage","lines":["냉장고 ㉮ — 1등급, 냉장고 ㉯ — 5등급(크기와 기능이 같다)","꺼 둔 텔레비전의 플러그가 꽂혀 있었다.","수도꼭지는 움직임을 알아차려 저절로 멈추는 것으로 바뀌었다.","종이컵 대신 다회용 컵이 놓여 있었다."],"title":"⑤ 셋째 날 — 마을 회관 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#8','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C18',1,'mc','auto','누리반 탐방 일지 ⑥에서 에너지 효율이 더 높은 집은 어느 것인가요?',ARRAY['SC5-2-u4-X33','SC5-2-u4-X34']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C18","difficulty":1,"kind":"mc","stem":"누리반 탐방 일지 ⑥에서 에너지 효율이 더 높은 집은 어느 것인가요?","options":[{"t":"단열한 집","correct":true},{"t":"단열 안 한 집","mis":"SC5-2-u4-X33"},{"t":"두 집이 같다","mis":"SC5-2-u4-X34"},{"t":"처음 온도가 높은 집","mis":"SC5-2-u4-X34"}],"explanation":["변화량을 견줘요.","단열한 집이 덜 변해요.","단열한 집이에요."],"asset":{"type":"passage","lines":["단열 안 한 집 — 처음 28.0 °C → 5분 뒤 23.6 °C","단열한 집(뽁뽁이 두 겹·우드록·색점토) — 처음 27.0 °C → 5분 뒤 25.2 °C","두 집은 크기가 같고, 같은 손난로로 데운 뒤 1분마다 쟀다."],"title":"⑥ 셋째 날 오후 — 집 모형 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#9','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C2',2,'mc','auto','누리반 탐방 일지 ①의 해설사 말로 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-2-u4-X02','SC5-2-u4-X01','SC5-2-u4-X03']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C2","difficulty":2,"kind":"mc","stem":"누리반 탐방 일지 ①의 해설사 말로 알 수 있는 것은 어느 것인가요?","options":[{"t":"바람이 약하면 날개가 천천히 돌아 에너지가 덜 만들어진다","correct":true},{"t":"바람이 약할수록 에너지가 더 많이 만들어진다","mis":"SC5-2-u4-X02"},{"t":"날개가 멈춰도 에너지는 똑같다","mis":"SC5-2-u4-X01"},{"t":"바람과 날개는 아무 상관이 없다","mis":"SC5-2-u4-X03"}],"explanation":["바람이 약해요.","날개가 천천히 돌아요.","에너지가 덜 생겨요."],"asset":{"type":"passage","lines":["배에서 내리자 언덕 위 풍력 발전기의 긴 날개 세 개가 돌고 있었다.","우리는 풍력 발전 모형에 머리 말리개 바람을 보냈다.","날개가 빨리 돌자 전구에 불이 켜졌다.","해설사: 「바람이 약한 날엔 날개가 천천히 돌아요.」"],"title":"① 첫날 — 바람의 섬에 도착"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#10','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C5',2,'mc','auto','누리반 탐방 일지 ②의 세 자원에서 함께 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-2-u4-X11','SC5-2-u4-X09','SC5-2-u4-X10']::text[],false,'{"seq":10,"concept":"SC5-2-u4-C5","difficulty":2,"kind":"mc","stem":"누리반 탐방 일지 ②의 세 자원에서 함께 알 수 있는 것은 어느 것인가요?","options":[{"t":"자원은 한정되어 있거나 다시 생기는 데 오래 걸려 계속 쓰기 어렵다","correct":true},{"t":"섬의 자원은 끝없이 쓸 수 있다","mis":"SC5-2-u4-X11"},{"t":"물만 아끼면 된다","mis":"SC5-2-u4-X09"},{"t":"돌은 곧 다시 생긴다","mis":"SC5-2-u4-X10"}],"explanation":["물·나무·돌을 봐요.","모두 한정돼요.","계속 쓰기 어려워요."],"asset":{"type":"passage","lines":["섬 사람들은 우물물과 빗물을 모아 쓴다.","뒷산 나무로 집을 지었는데, 다시 자라려면 오래 걸린다고 한다.","옛 돌 광산은 묻혀 있던 돌이 바닥나 문을 닫았다.","섬마을 이장님: 「캔은 꼭 분리배출해요.」"],"title":"② 첫날 오후 — 섬의 자원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#11','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C8',2,'match','auto','누리반 탐방 일지 ③의 장소와 얻는 재생 에너지를 알맞게 이으세요.','{}'::text[],false,'{"seq":11,"concept":"SC5-2-u4-C8","difficulty":2,"kind":"match","stem":"누리반 탐방 일지 ③의 장소와 얻는 재생 에너지를 알맞게 이으세요.","pairs":[{"l":"언덕","r":"풍력"},{"l":"집 지붕","r":"태양 에너지"},{"l":"마을 회관 땅속","r":"지열 에너지"}],"mis":"SC5-2-u4-X14","explanation":["언덕은 바람이에요.","지붕은 햇빛이에요.","땅속은 지열이에요."],"asset":{"type":"passage","lines":["언덕 — 풍력 발전기","집 지붕 — 태양 전지판","바닷가 둑 — 밀물과 썰물을 쓰는 발전 시설","돼지 농장 — 분뇨로 가스를 만드는 시설","마을 회관 땅속 — 땅속 열을 쓰는 냉난방"],"title":"③ 둘째 날 — 섬의 재생 에너지 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#12','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C10',2,'mc','auto','누리반 탐방 일지 ④의 주민 2 의견의 문제점으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X21','SC5-2-u4-X13']::text[],false,'{"seq":12,"concept":"SC5-2-u4-C10","difficulty":2,"kind":"mc","stem":"누리반 탐방 일지 ④의 주민 2 의견의 문제점으로 알맞은 것은 어느 것인가요?","options":[{"t":"석유는 한정되어 있고 대기오염과 기후변화를 일으킨다","correct":true},{"t":"석유는 끝없이 얻을 수 있다","mis":"SC5-2-u4-X21"},{"t":"석유는 공기를 깨끗하게 한다","mis":"SC5-2-u4-X21"},{"t":"석유는 재생 에너지다","mis":"SC5-2-u4-X13"}],"explanation":["석유는 줄어요.","공기를 더럽혀요.","문제가 있어요."],"asset":{"type":"passage","lines":["주민 1: 「바람이 약한 날은 전기가 모자라요.」","주민 2: 「옛날처럼 석유 발전기를 다시 돌립시다.」","주민 3: 「에너지를 모아 두는 기술을 들이고 모두 함께 아껴 씁시다.」","결정 — 재생 에너지를 늘리고 절약하며, 미래 세대를 생각한다."],"title":"④ 둘째 날 저녁 — 마을 회의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#13','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C13',2,'mc','auto','누리반 탐방 일지 ④의 결정에 들어 있는 지속가능한 방법을 바르게 모은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X21','SC5-2-u4-X24','SC5-2-u4-X22']::text[],false,'{"seq":13,"concept":"SC5-2-u4-C13","difficulty":2,"kind":"mc","stem":"누리반 탐방 일지 ④의 결정에 들어 있는 지속가능한 방법을 바르게 모은 것은 어느 것인가요?","options":[{"t":"재생 에너지 늘리기와 함께 아껴 쓰기","correct":true},{"t":"석유 발전기 다시 돌리기","mis":"SC5-2-u4-X21"},{"t":"재생 에너지만 늘리고 마음껏 쓰기","mis":"SC5-2-u4-X24"},{"t":"아무것도 바꾸지 않기","mis":"SC5-2-u4-X22"}],"explanation":["재생 에너지를 늘려요.","아껴 써요.","둘 다예요."],"asset":{"type":"passage","lines":["주민 1: 「바람이 약한 날은 전기가 모자라요.」","주민 2: 「옛날처럼 석유 발전기를 다시 돌립시다.」","주민 3: 「에너지를 모아 두는 기술을 들이고 모두 함께 아껴 씁시다.」","결정 — 재생 에너지를 늘리고 절약하며, 미래 세대를 생각한다."],"title":"④ 둘째 날 저녁 — 마을 회의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#14','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C14',2,'mc','auto','누리반 탐방 일지 ⑤의 꺼 둔 텔레비전을 바르게 고친 것은 어느 것인가요?',ARRAY['SC5-2-u4-X25']::text[],false,'{"seq":14,"concept":"SC5-2-u4-C14","difficulty":2,"kind":"mc","stem":"누리반 탐방 일지 ⑤의 꺼 둔 텔레비전을 바르게 고친 것은 어느 것인가요?","options":[{"t":"보지 않을 때는 플러그를 뽑거나 절전 멀티탭으로 끈다","correct":true},{"t":"플러그를 그대로 꽂아 둔다","mis":"SC5-2-u4-X25"},{"t":"전원 단추만 여러 번 누른다","mis":"SC5-2-u4-X25"},{"t":"텔레비전 소리만 줄인다","mis":"SC5-2-u4-X25"}],"explanation":["플러그가 꽂혀 있어요.","전기가 새요.","뽑아 두어요."],"asset":{"type":"passage","lines":["냉장고 ㉮ — 1등급, 냉장고 ㉯ — 5등급(크기와 기능이 같다)","꺼 둔 텔레비전의 플러그가 꽂혀 있었다.","수도꼭지는 움직임을 알아차려 저절로 멈추는 것으로 바뀌었다.","종이컵 대신 다회용 컵이 놓여 있었다."],"title":"⑤ 셋째 날 — 마을 회관 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#15','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C15',2,'match','auto','바람솔섬에서 본 방법과 주로 아끼는 자원을 알맞게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"SC5-2-u4-C15","difficulty":2,"kind":"match","stem":"바람솔섬에서 본 방법과 주로 아끼는 자원을 알맞게 이으세요.","pairs":[{"l":"움직임을 알아차리는 수도꼭지","r":"물 자원"},{"l":"다회용 컵","r":"산림 자원"},{"l":"캔 분리배출","r":"광물 자원"}],"mis":"SC5-2-u4-X30","explanation":["수도꼭지는 물이에요.","컵은 종이를 줄여요.","캔은 광물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#16','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C18',2,'mc','auto','누리반 탐방 일지 ⑥에서 단열 안 한 집의 온도 변화량은 얼마인가요?',ARRAY['SC5-2-u4-X34','SC5-2-u4-X33']::text[],false,'{"seq":16,"concept":"SC5-2-u4-C18","difficulty":2,"kind":"mc","stem":"누리반 탐방 일지 ⑥에서 단열 안 한 집의 온도 변화량은 얼마인가요?","options":[{"t":"4.4 °C","correct":true},{"t":"23.6 °C","mis":"SC5-2-u4-X34"},{"t":"1.8 °C","mis":"SC5-2-u4-X33"},{"t":"28.0 °C","mis":"SC5-2-u4-X34"}],"explanation":["처음 28.0 °C예요.","5분 뒤 23.6 °C예요.","4.4 °C예요."],"asset":{"type":"passage","lines":["단열 안 한 집 — 처음 28.0 °C → 5분 뒤 23.6 °C","단열한 집(뽁뽁이 두 겹·우드록·색점토) — 처음 27.0 °C → 5분 뒤 25.2 °C","두 집은 크기가 같고, 같은 손난로로 데운 뒤 1분마다 쟀다."],"title":"⑥ 셋째 날 오후 — 집 모형 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#17','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C18',3,'mc','auto','누리반 탐방 일지 ⑥의 결과로 내릴 수 있는 결론으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X33','SC5-2-u4-X34','SC5-2-u4-X36']::text[],false,'{"seq":17,"concept":"SC5-2-u4-C18","difficulty":3,"kind":"mc","stem":"누리반 탐방 일지 ⑥의 결과로 내릴 수 있는 결론으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"단열을 하면 집 안 온도가 덜 변해 에너지를 더 효율적으로 쓸 수 있다","correct":true},{"t":"단열을 하면 집 안 온도가 더 빨리 떨어진다","mis":"SC5-2-u4-X33"},{"t":"처음 온도가 높은 집이 언제나 좋다","mis":"SC5-2-u4-X34"},{"t":"단열재가 열을 내 집을 데운다","mis":"SC5-2-u4-X36"}],"explanation":["덜 변했어요.","열을 지켜요.","효율이 높아요."],"asset":{"type":"passage","lines":["단열 안 한 집 — 처음 28.0 °C → 5분 뒤 23.6 °C","단열한 집(뽁뽁이 두 겹·우드록·색점토) — 처음 27.0 °C → 5분 뒤 25.2 °C","두 집은 크기가 같고, 같은 손난로로 데운 뒤 1분마다 쟀다."],"title":"⑥ 셋째 날 오후 — 집 모형 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#18','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C19',3,'mc','auto','에너지를 아끼는 집의 시설을 「열 막기」와 「에너지 만들기」로 바르게 나눈 것은 어느 것인가요?',ARRAY['SC5-2-u4-X35']::text[],false,'{"seq":18,"concept":"SC5-2-u4-C19","difficulty":3,"kind":"mc","stem":"에너지를 아끼는 집의 시설을 「열 막기」와 「에너지 만들기」로 바르게 나눈 것은 어느 것인가요?","options":[{"t":"열 막기 — 단열재·이중창, 에너지 만들기 — 태양 전지판·땅속 열 냉난방","correct":true},{"t":"열 막기 — 태양 전지판·이중창, 에너지 만들기 — 단열재·차양","mis":"SC5-2-u4-X35"},{"t":"열 막기 — 땅속 열 냉난방, 에너지 만들기 — 단열재","mis":"SC5-2-u4-X35"},{"t":"모두 에너지 만들기","mis":"SC5-2-u4-X35"}],"explanation":["단열재는 막아요.","전지판은 만들어요.","두 갈래예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#19','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C20',3,'mc','auto','누리반 탐방 일지 ⑦에서 「주민의 얼굴과 이름은 허락 없이 넣지 않는다」를 지킨 까닭은 어느 것인가요?',ARRAY['SC5-2-u4-X38','SC5-2-u4-X37','SC5-2-u4-X39']::text[],false,'{"seq":19,"concept":"SC5-2-u4-C20","difficulty":3,"kind":"mc","stem":"누리반 탐방 일지 ⑦에서 「주민의 얼굴과 이름은 허락 없이 넣지 않는다」를 지킨 까닭은 어느 것인가요?","options":[{"t":"다른 사람의 개인 정보를 누리망에 함부로 올리면 안 되기 때문이다","correct":true},{"t":"얼굴이 나오면 영상이 너무 재미있어서","mis":"SC5-2-u4-X38"},{"t":"이름은 자원이 아니어서","mis":"SC5-2-u4-X37"},{"t":"영상을 올리지 않을 것이어서","mis":"SC5-2-u4-X39"}],"explanation":["개인 정보예요.","허락이 필요해요.","지켜야 해요."],"asset":{"type":"passage","lines":["주제 — 바람솔섬의 물 아끼기","장면 — 비누칠할 때 물 잠그기, 모은 빗물로 화분에 물 주기","지킬 점 — 주민의 얼굴과 이름은 허락 없이 넣지 않는다.","다 만든 영상은 학급 누리집에 올렸다."],"title":"⑦ 넷째 날 — 실천 영상 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#20','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C9',3,'mc','auto','바람이 약한 날에도 바람솔섬이 에너지를 얻는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X19','SC5-2-u4-X21','SC5-2-u4-X18']::text[],false,'{"seq":20,"concept":"SC5-2-u4-C9","difficulty":3,"kind":"mc","stem":"바람이 약한 날에도 바람솔섬이 에너지를 얻는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"풍력과 함께 태양 에너지와 해양 에너지를 같이 쓴다","correct":true},{"t":"풍력 하나만 더 크게 짓는다","mis":"SC5-2-u4-X19"},{"t":"석유 발전기만 쓴다","mis":"SC5-2-u4-X21"},{"t":"섬에 없는 큰 계곡의 수력을 쓴다","mis":"SC5-2-u4-X18"}],"explanation":["바람이 약해요.","다른 재생 에너지도 있어요.","함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#21','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C21',3,'mc','auto','누리반 탐방 일지 ⑧에서 선착장 발걸음을 모으는 전문가가 하는 일은 어느 것인가요?',ARRAY['SC5-2-u4-X40','SC5-2-u4-X41']::text[],false,'{"seq":21,"concept":"SC5-2-u4-C21","difficulty":3,"kind":"mc","stem":"누리반 탐방 일지 ⑧에서 선착장 발걸음을 모으는 전문가가 하는 일은 어느 것인가요?","options":[{"t":"버려지는 에너지를 모아 쓰는 방법을 연구한다","correct":true},{"t":"새 석탄 광산을 찾는다","mis":"SC5-2-u4-X40"},{"t":"석유를 더 많이 쓰게 한다","mis":"SC5-2-u4-X41"},{"t":"바닷물을 모두 막는다","mis":"SC5-2-u4-X40"}],"explanation":["발걸음이 버려져요.","모아서 써요.","하베스팅이에요."],"asset":{"type":"passage","lines":["재생 에너지 전문가 — 「바람이 가장 센 자리를 찾아 발전기를 세워요.」","에너지 하베스팅 전문가 — 「선착장을 밟는 발걸음과 배의 떨림을 모아요.」","우리 반 다짐 — 돌아가서도 자원과 에너지를 아끼자."],"title":"⑧ 마지막 날 — 전문가와 만남"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#22','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C22',3,'error','auto','탐방을 마치며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X42','SC5-2-u4-X11','SC5-2-u4-X33']::text[],false,'{"seq":22,"concept":"SC5-2-u4-C22","difficulty":3,"kind":"error","stem":"탐방을 마치며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"우진 — 「섬은 재생 에너지가 많으니 자원과 에너지를 아낄 필요가 없어.」","correct":true,"mis_target":"SC5-2-u4-X42"},{"t":"가윤 — 「자원은 한정되어 있어 아껴야 해.」","mis":"SC5-2-u4-X11"},{"t":"하은 — 「단열로 에너지 효율을 높일 수 있어.」","mis":"SC5-2-u4-X33"}],"explanation":["재생 에너지도 아직 모자라요.","아끼기도 함께해요.","우진의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#23','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C18',4,'essay','teacher','누리반 탐방 일지 ⑥의 두 집의 온도 변화량을 구해 견주고, 어느 집의 에너지 효율이 더 높은지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC5-2-u4-C18","difficulty":4,"kind":"essay","stem":"누리반 탐방 일지 ⑥의 두 집의 온도 변화량을 구해 견주고, 어느 집의 에너지 효율이 더 높은지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 단열 안 한 집은 28.0 °C에서 23.6 °C로 4.4 °C, 단열한 집은 27.0 °C에서 25.2 °C로 1.8 °C 낮아졌다. 처음 온도가 달라 변화량으로 견주면, 온도 변화가 작은 단열한 집이 열을 더 잘 지켜 에너지 효율이 더 높다.","scoring_points":["두 집의 온도 변화량을 바르게 구했는가","처음 온도가 달라 변화량으로 견준다고 썼는가","변화가 작은 단열한 집이 효율이 높다고 썼는가"]},"explanation":["변화량을 구해요.","견줘요.","단열한 집이에요."],"asset":{"type":"passage","lines":["단열 안 한 집 — 처음 28.0 °C → 5분 뒤 23.6 °C","단열한 집(뽁뽁이 두 겹·우드록·색점토) — 처음 27.0 °C → 5분 뒤 25.2 °C","두 집은 크기가 같고, 같은 손난로로 데운 뒤 1분마다 쟀다."],"title":"⑥ 셋째 날 오후 — 집 모형 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#24','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C9',4,'essay','teacher','누리반 탐방 일지 ③을 참고해 바람솔섬에 알맞은 재생 에너지 두 가지를 고르고, 각각 섬의 어떤 특징 때문에 알맞은지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-2-u4-C9","difficulty":4,"kind":"essay","stem":"누리반 탐방 일지 ③을 참고해 바람솔섬에 알맞은 재생 에너지 두 가지를 고르고, 각각 섬의 어떤 특징 때문에 알맞은지 쓰세요.","answer_guide":{"answer":"예: 섬은 바다로 둘러싸여 바람이 세므로 언덕에 풍력이 알맞다. 또 바닷가에 밀물과 썰물이 드나들므로 해양 에너지도 알맞다.","scoring_points":["재생 에너지 두 가지를 골랐는가","각각 섬의 특징과 이었는가","특징과 재생 에너지의 짝이 알맞은가"]},"explanation":["섬의 특징을 봐요.","두 가지를 골라요.","까닭을 써요."],"asset":{"type":"passage","lines":["언덕 — 풍력 발전기","집 지붕 — 태양 전지판","바닷가 둑 — 밀물과 썰물을 쓰는 발전 시설","돼지 농장 — 분뇨로 가스를 만드는 시설","마을 회관 땅속 — 땅속 열을 쓰는 냉난방"],"title":"③ 둘째 날 — 섬의 재생 에너지 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_a#25','sci',5,2,'u4','','g5_2_sci_u4_review_a','unit_review','SC5-2-u4-C22',4,'essay','teacher','바람솔섬 탐방에서 배운 것을 바탕으로 우리 집에서 실천할 계획을 쓰세요. 자원을 아끼는 일 하나와 에너지를 효율적으로 쓰는 일 하나를 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-2-u4-C22","difficulty":4,"kind":"essay","stem":"바람솔섬 탐방에서 배운 것을 바탕으로 우리 집에서 실천할 계획을 쓰세요. 자원을 아끼는 일 하나와 에너지를 효율적으로 쓰는 일 하나를 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 자원 — 양치할 때 양치 컵에 물을 받아 쓴다. 깨끗한 물이 한정되어 있기 때문이다. 에너지 — 쓰지 않는 전기 기구의 플러그를 뽑는다. 꺼 두어도 전기가 조금씩 쓰이기 때문이다.","scoring_points":["자원을 아끼는 일을 썼는가","에너지를 효율적으로 쓰는 일을 썼는가","각각의 까닭을 썼는가"]},"explanation":["자원을 아껴요.","에너지도 아껴요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_b#1','sci',5,2,'u4','','g5_2_sci_u4_review_b','unit_review','SC5-2-u4-C1',1,'ox','auto','풍력 발전기는 바람의 힘으로 회전 날개를 돌려요.',ARRAY['SC5-2-u4-X03']::text[],false,'{"seq":1,"concept":"SC5-2-u4-C1","difficulty":1,"kind":"ox","stem":"풍력 발전기는 바람의 힘으로 회전 날개를 돌려요.","answer":"O","reason_options":[{"t":"바람이 불어야 날개가 돌아 에너지를 만들기 때문에","correct":true},{"t":"바람 없이 스스로 날개를 돌리기 때문에","mis":"SC5-2-u4-X03"}],"mis":"SC5-2-u4-X03","explanation":["바람이 불어요.","날개가 돌아요.","에너지를 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_b#2','sci',5,2,'u4','','g5_2_sci_u4_review_b','unit_review','SC5-2-u4-C4',1,'mc','auto','누리반 탐방 일지 ②에서 집을 지을 때 쓴 뒷산 나무는 어떤 자원인가요?',ARRAY['SC5-2-u4-X06']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C4","difficulty":1,"kind":"mc","stem":"누리반 탐방 일지 ②에서 집을 지을 때 쓴 뒷산 나무는 어떤 자원인가요?","options":[{"t":"산림 자원","correct":true},{"t":"물 자원","mis":"SC5-2-u4-X06"},{"t":"광물 자원","mis":"SC5-2-u4-X06"},{"t":"바람 자원","mis":"SC5-2-u4-X06"}],"explanation":["나무예요.","숲에서 와요.","산림 자원이에요."],"asset":{"type":"passage","lines":["섬 사람들은 우물물과 빗물을 모아 쓴다.","뒷산 나무로 집을 지었는데, 다시 자라려면 오래 걸린다고 한다.","옛 돌 광산은 묻혀 있던 돌이 바닥나 문을 닫았다.","섬마을 이장님: 「캔은 꼭 분리배출해요.」"],"title":"② 첫날 오후 — 섬의 자원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_b#3','sci',5,2,'u4','','g5_2_sci_u4_review_b','unit_review','SC5-2-u4-C5',1,'ox','auto','숲의 나무는 베어도 곧바로 다시 자라 산림 자원이 줄지 않아요.',ARRAY['SC5-2-u4-X09']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C5","difficulty":1,"kind":"ox","stem":"숲의 나무는 베어도 곧바로 다시 자라 산림 자원이 줄지 않아요.","answer":"X","reason_options":[{"t":"나무가 다시 자라는 데 오랜 시간이 걸리기 때문에","correct":true},{"t":"나무는 베자마자 바로 다시 자라기 때문에","mis":"SC5-2-u4-X09"}],"mis":"SC5-2-u4-X09","explanation":["나무를 베요.","다시 자라려면 오래 걸려요.","줄어들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_b#4','sci',5,2,'u4','','g5_2_sci_u4_review_b','unit_review','SC5-2-u4-C8',1,'mc','auto','누리반 탐방 일지 ③에서 돼지 농장의 시설이 얻는 재생 에너지는 어느 것인가요?',ARRAY['SC5-2-u4-X17','SC5-2-u4-X14']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C8","difficulty":1,"kind":"mc","stem":"누리반 탐방 일지 ③에서 돼지 농장의 시설이 얻는 재생 에너지는 어느 것인가요?","options":[{"t":"바이오 에너지","correct":true},{"t":"태양 에너지","mis":"SC5-2-u4-X17"},{"t":"풍력","mis":"SC5-2-u4-X17"},{"t":"해양 에너지","mis":"SC5-2-u4-X14"}],"explanation":["분뇨를 써요.","가스를 만들어요.","바이오 에너지예요."],"asset":{"type":"passage","lines":["언덕 — 풍력 발전기","집 지붕 — 태양 전지판","바닷가 둑 — 밀물과 썰물을 쓰는 발전 시설","돼지 농장 — 분뇨로 가스를 만드는 시설","마을 회관 땅속 — 땅속 열을 쓰는 냉난방"],"title":"③ 둘째 날 — 섬의 재생 에너지 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_b#5','sci',5,2,'u4','','g5_2_sci_u4_review_b','unit_review','SC5-2-u4-C10',1,'mc','auto','누리반 탐방 일지 ④의 주민 1의 말로 알 수 있는 재생 에너지의 한계는 어느 것인가요?',ARRAY['SC5-2-u4-X19','SC5-2-u4-X13','SC5-2-u4-X20']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C10","difficulty":1,"kind":"mc","stem":"누리반 탐방 일지 ④의 주민 1의 말로 알 수 있는 재생 에너지의 한계는 어느 것인가요?","options":[{"t":"날씨에 따라 얻는 양이 달라진다","correct":true},{"t":"언제나 같은 양을 얻는다","mis":"SC5-2-u4-X19"},{"t":"쓰면 바닥이 난다","mis":"SC5-2-u4-X13"},{"t":"공기를 가장 많이 더럽힌다","mis":"SC5-2-u4-X20"}],"explanation":["바람이 약해요.","전기가 모자라요.","날씨에 따라 달라요."],"asset":{"type":"passage","lines":["주민 1: 「바람이 약한 날은 전기가 모자라요.」","주민 2: 「옛날처럼 석유 발전기를 다시 돌립시다.」","주민 3: 「에너지를 모아 두는 기술을 들이고 모두 함께 아껴 씁시다.」","결정 — 재생 에너지를 늘리고 절약하며, 미래 세대를 생각한다."],"title":"④ 둘째 날 저녁 — 마을 회의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_b#6','sci',5,2,'u4','','g5_2_sci_u4_review_b','unit_review','SC5-2-u4-C12',1,'ox','auto','빈방에 조명을 켜 두는 것은 에너지를 낭비하는 예예요.',ARRAY['SC5-2-u4-X23']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C12","difficulty":1,"kind":"ox","stem":"빈방에 조명을 켜 두는 것은 에너지를 낭비하는 예예요.","answer":"O","reason_options":[{"t":"쓰지 않는 곳에 에너지를 쓰기 때문에","correct":true},{"t":"빈방도 밝아야 에너지가 늘기 때문에","mis":"SC5-2-u4-X23"}],"mis":"SC5-2-u4-X23","explanation":["방이 비었어요.","켜 둘 필요가 없어요.","낭비예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_b#7','sci',5,2,'u4','','g5_2_sci_u4_review_b','unit_review','SC5-2-u4-C15',1,'mc','auto','누리반 탐방 일지 ⑤에서 종이컵 대신 다회용 컵을 쓰면 주로 아끼는 자원은 어느 것인가요?',ARRAY['SC5-2-u4-X30']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C15","difficulty":1,"kind":"mc","stem":"누리반 탐방 일지 ⑤에서 종이컵 대신 다회용 컵을 쓰면 주로 아끼는 자원은 어느 것인가요?","options":[{"t":"산림 자원","correct":true},{"t":"물 자원","mis":"SC5-2-u4-X30"},{"t":"광물 자원","mis":"SC5-2-u4-X30"},{"t":"바람 자원","mis":"SC5-2-u4-X30"}],"explanation":["종이컵은 나무로 만들어요.","나무를 아껴요.","산림 자원이에요."],"asset":{"type":"passage","lines":["냉장고 ㉮ — 1등급, 냉장고 ㉯ — 5등급(크기와 기능이 같다)","꺼 둔 텔레비전의 플러그가 꽂혀 있었다.","수도꼭지는 움직임을 알아차려 저절로 멈추는 것으로 바뀌었다.","종이컵 대신 다회용 컵이 놓여 있었다."],"title":"⑤ 셋째 날 — 마을 회관 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_b#8','sci',5,2,'u4','','g5_2_sci_u4_review_b','unit_review','SC5-2-u4-C18',1,'ox','auto','집 모형 실험에서 온도 변화가 작은 집이 집 안 온도를 더 잘 지킨 집이에요.',ARRAY['SC5-2-u4-X33']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C18","difficulty":1,"kind":"ox","stem":"집 모형 실험에서 온도 변화가 작은 집이 집 안 온도를 더 잘 지킨 집이에요.","answer":"O","reason_options":[{"t":"열이 덜 빠져나가 온도가 덜 변했기 때문에","correct":true},{"t":"온도가 많이 변할수록 열을 잘 지킨 것이기 때문에","mis":"SC5-2-u4-X33"}],"mis":"SC5-2-u4-X33","explanation":["덜 변했어요.","열이 덜 나갔어요.","잘 지켰어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_b#9','sci',5,2,'u4','','g5_2_sci_u4_review_b','unit_review','SC5-2-u4-C2',2,'ox','auto','풍력 발전 모형의 날개에 입술을 바짝 대고 불면 더 안전하게 불이 켜져요.',ARRAY['SC5-2-u4-X04']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C2","difficulty":2,"kind":"ox","stem":"풍력 발전 모형의 날개에 입술을 바짝 대고 불면 더 안전하게 불이 켜져요.","answer":"X","reason_options":[{"t":"돌아가는 날개에 입술이 닿아 다칠 수 있기 때문에","correct":true},{"t":"날개는 돌아도 위험하지 않기 때문에","mis":"SC5-2-u4-X04"}],"mis":"SC5-2-u4-X04","explanation":["날개가 돌아요.","입술이 다칠 수 있어요.","멀리서 불어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_b#10','sci',5,2,'u4','','g5_2_sci_u4_review_b','unit_review','SC5-2-u4-C5',2,'ox','auto','누리반 탐방 일지 ②에서 캔을 분리배출하니 광물 자원은 끝없이 쓸 수 있어요.',ARRAY['SC5-2-u4-X11']::text[],false,'{"seq":10,"concept":"SC5-2-u4-C5","difficulty":2,"kind":"ox","stem":"누리반 탐방 일지 ②에서 캔을 분리배출하니 광물 자원은 끝없이 쓸 수 있어요.","answer":"X","reason_options":[{"t":"재활용을 해도 자원이 끝없이 있는 것은 아니기 때문에","correct":true},{"t":"재활용되는 자원은 무한하기 때문에","mis":"SC5-2-u4-X11"}],"mis":"SC5-2-u4-X11","explanation":["분리배출은 좋아요.","그래도 한정돼요.","아껴 써요."],"asset":{"type":"passage","lines":["섬 사람들은 우물물과 빗물을 모아 쓴다.","뒷산 나무로 집을 지었는데, 다시 자라려면 오래 걸린다고 한다.","옛 돌 광산은 묻혀 있던 돌이 바닥나 문을 닫았다.","섬마을 이장님: 「캔은 꼭 분리배출해요.」"],"title":"② 첫날 오후 — 섬의 자원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_b#11','sci',5,2,'u4','','g5_2_sci_u4_review_b','unit_review','SC5-2-u4-C8',2,'mc','auto','누리반 탐방 일지 ③에서 집 지붕의 태양 전지판이 주로 이용하는 것은 어느 것인가요?',ARRAY['SC5-2-u4-X15','SC5-2-u4-X16','SC5-2-u4-X14']::text[],false,'{"seq":11,"concept":"SC5-2-u4-C8","difficulty":2,"kind":"mc","stem":"누리반 탐방 일지 ③에서 집 지붕의 태양 전지판이 주로 이용하는 것은 어느 것인가요?","options":[{"t":"태양 빛","correct":true},{"t":"태양의 뜨거운 열만","mis":"SC5-2-u4-X15"},{"t":"땅속의 열","mis":"SC5-2-u4-X16"},{"t":"바닷물의 흐름","mis":"SC5-2-u4-X14"}],"explanation":["전지판은 빛을 받아요.","전기를 만들어요.","태양 빛이에요."],"asset":{"type":"passage","lines":["언덕 — 풍력 발전기","집 지붕 — 태양 전지판","바닷가 둑 — 밀물과 썰물을 쓰는 발전 시설","돼지 농장 — 분뇨로 가스를 만드는 시설","마을 회관 땅속 — 땅속 열을 쓰는 냉난방"],"title":"③ 둘째 날 — 섬의 재생 에너지 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_b#12','sci',5,2,'u4','','g5_2_sci_u4_review_b','unit_review','SC5-2-u4-C10',2,'mc','auto','누리반 탐방 일지 ④의 주민 3이 에너지를 모아 두는 기술을 말한 까닭은 어느 것인가요?',ARRAY['SC5-2-u4-X19','SC5-2-u4-X21']::text[],false,'{"seq":12,"concept":"SC5-2-u4-C10","difficulty":2,"kind":"mc","stem":"누리반 탐방 일지 ④의 주민 3이 에너지를 모아 두는 기술을 말한 까닭은 어느 것인가요?","options":[{"t":"바람이 센 날 만든 에너지를 모아 두었다가 약한 날에 쓰려고","correct":true},{"t":"바람이 약한 날에 에너지가 넘쳐서","mis":"SC5-2-u4-X19"},{"t":"석유를 더 많이 모으려고","mis":"SC5-2-u4-X21"},{"t":"재생 에너지는 단점이 없어서","mis":"SC5-2-u4-X19"}],"explanation":["바람이 달라져요.","모아 둬요.","약한 날에 써요."],"asset":{"type":"passage","lines":["주민 1: 「바람이 약한 날은 전기가 모자라요.」","주민 2: 「옛날처럼 석유 발전기를 다시 돌립시다.」","주민 3: 「에너지를 모아 두는 기술을 들이고 모두 함께 아껴 씁시다.」","결정 — 재생 에너지를 늘리고 절약하며, 미래 세대를 생각한다."],"title":"④ 둘째 날 저녁 — 마을 회의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_b#13','sci',5,2,'u4','','g5_2_sci_u4_review_b','unit_review','SC5-2-u4-C12',2,'mc','auto','에너지 이용 놀이를 한다면 사다리를 타고 올라가는 칸은 어느 것인가요?',ARRAY['SC5-2-u4-X23']::text[],false,'{"seq":13,"concept":"SC5-2-u4-C12","difficulty":2,"kind":"mc","stem":"에너지 이용 놀이를 한다면 사다리를 타고 올라가는 칸은 어느 것인가요?","options":[{"t":"냉난방할 때 알맞은 온도 지키기","correct":true},{"t":"창문을 연 채 난방 켜기","mis":"SC5-2-u4-X23"},{"t":"보지 않는 텔레비전 켜 두기","mis":"SC5-2-u4-X23"},{"t":"빈방에 조명 켜 두기","mis":"SC5-2-u4-X23"}],"explanation":["알맞은 온도예요.","낭비가 없어요.","사다리로 올라가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_b#14','sci',5,2,'u4','','g5_2_sci_u4_review_b','unit_review','SC5-2-u4-C16',2,'mc','auto','누리반 탐방 일지 ⑤의 냉장고 ㉯를 ㉮ 같은 제품으로 바꾸면 어떻게 되나요?',ARRAY['SC5-2-u4-X26','SC5-2-u4-X27']::text[],false,'{"seq":14,"concept":"SC5-2-u4-C16","difficulty":2,"kind":"mc","stem":"누리반 탐방 일지 ⑤의 냉장고 ㉯를 ㉮ 같은 제품으로 바꾸면 어떻게 되나요?","options":[{"t":"같은 일을 하면서 전기를 덜 써 에너지를 아낄 수 있다","correct":true},{"t":"전기를 더 많이 써 효율이 낮아진다","mis":"SC5-2-u4-X26"},{"t":"5등급이 더 좋아 손해가 된다","mis":"SC5-2-u4-X27"},{"t":"등급과 전기 사용은 상관없다","mis":"SC5-2-u4-X27"}],"explanation":["1등급으로 바꿔요.","전기를 덜 써요.","에너지를 아껴요."],"asset":{"type":"passage","lines":["냉장고 ㉮ — 1등급, 냉장고 ㉯ — 5등급(크기와 기능이 같다)","꺼 둔 텔레비전의 플러그가 꽂혀 있었다.","수도꼭지는 움직임을 알아차려 저절로 멈추는 것으로 바뀌었다.","종이컵 대신 다회용 컵이 놓여 있었다."],"title":"⑤ 셋째 날 — 마을 회관 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_b#15','sci',5,2,'u4','','g5_2_sci_u4_review_b','unit_review','SC5-2-u4-C15',2,'mc','auto','섬 가게에서 자원을 효율적으로 이용하는 행동은 어느 것인가요?',ARRAY['SC5-2-u4-X28']::text[],false,'{"seq":15,"concept":"SC5-2-u4-C15","difficulty":2,"kind":"mc","stem":"섬 가게에서 자원을 효율적으로 이용하는 행동은 어느 것인가요?","options":[{"t":"과대 포장되지 않은 물건을 장바구니에 담는다","correct":true},{"t":"포장이 겹겹이 된 물건만 고른다","mis":"SC5-2-u4-X28"},{"t":"비닐봉지를 여러 장 받는다","mis":"SC5-2-u4-X28"},{"t":"종이 영수증을 꼭 여러 장 받는다","mis":"SC5-2-u4-X28"}],"explanation":["포장을 줄여요.","장바구니를 써요.","자원을 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_b#16','sci',5,2,'u4','','g5_2_sci_u4_review_b','unit_review','SC5-2-u4-C18',2,'mc','auto','누리반 탐방 일지 ⑥에서 단열한 집의 온도 변화량은 얼마인가요?',ARRAY['SC5-2-u4-X34','SC5-2-u4-X33']::text[],false,'{"seq":16,"concept":"SC5-2-u4-C18","difficulty":2,"kind":"mc","stem":"누리반 탐방 일지 ⑥에서 단열한 집의 온도 변화량은 얼마인가요?","options":[{"t":"1.8 °C","correct":true},{"t":"25.2 °C","mis":"SC5-2-u4-X34"},{"t":"4.4 °C","mis":"SC5-2-u4-X33"},{"t":"27.0 °C","mis":"SC5-2-u4-X34"}],"explanation":["처음 27.0 °C예요.","5분 뒤 25.2 °C예요.","1.8 °C예요."],"asset":{"type":"passage","lines":["단열 안 한 집 — 처음 28.0 °C → 5분 뒤 23.6 °C","단열한 집(뽁뽁이 두 겹·우드록·색점토) — 처음 27.0 °C → 5분 뒤 25.2 °C","두 집은 크기가 같고, 같은 손난로로 데운 뒤 1분마다 쟀다."],"title":"⑥ 셋째 날 오후 — 집 모형 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_b#17','sci',5,2,'u4','','g5_2_sci_u4_review_b','unit_review','SC5-2-u4-C17',3,'error','auto','집 모형 실험을 계획하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X31','SC5-2-u4-X32']::text[],false,'{"seq":17,"concept":"SC5-2-u4-C17","difficulty":3,"kind":"error","stem":"집 모형 실험을 계획하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「단열한 집에만 손난로를 두 개 넣자.」","correct":true,"mis_target":"SC5-2-u4-X31"},{"t":"채윤 — 「두 집 크기와 모양을 같게 하자.」","mis":"SC5-2-u4-X31"},{"t":"도겸 — 「탐침 끝이 바닥에 닿지 않게 하자.」","mis":"SC5-2-u4-X32"}],"explanation":["손난로는 같게 해요.","단열만 달라야 해요.","은우의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_b#18','sci',5,2,'u4','','g5_2_sci_u4_review_b','unit_review','SC5-2-u4-C19',3,'error','auto','단열에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X36','SC5-2-u4-X35','SC5-2-u4-X33']::text[],false,'{"seq":18,"concept":"SC5-2-u4-C19","difficulty":3,"kind":"error","stem":"단열에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온 — 「뽁뽁이가 스스로 뜨거워져서 집을 데워 줘.」","correct":true,"mis_target":"SC5-2-u4-X36"},{"t":"세린 — 「이중창은 열이 빠져나가는 걸 막아.」","mis":"SC5-2-u4-X35"},{"t":"민혁 — 「틈을 막으면 열이 덜 새.」","mis":"SC5-2-u4-X33"}],"explanation":["뽁뽁이는 막을 뿐이에요.","스스로 열을 내지 않아요.","라온의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_b#19','sci',5,2,'u4','','g5_2_sci_u4_review_b','unit_review','SC5-2-u4-C20',3,'error','auto','실천 영상을 올린 뒤 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X39','SC5-2-u4-X38']::text[],false,'{"seq":19,"concept":"SC5-2-u4-C20","difficulty":3,"kind":"error","stem":"실천 영상을 올린 뒤 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"소은 — 「영상을 올렸으니 이제 물은 마음대로 써도 돼.」","correct":true,"mis_target":"SC5-2-u4-X39"},{"t":"준하 — 「가족에게도 알려서 같이 해 보자.」","mis":"SC5-2-u4-X39"},{"t":"이안 — 「댓글은 고운 말로 달자.」","mis":"SC5-2-u4-X38"}],"explanation":["영상은 시작이에요.","꾸준히 해요.","소은의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_b#20','sci',5,2,'u4','','g5_2_sci_u4_review_b','unit_review','SC5-2-u4-C10',3,'error','auto','재생 에너지 시설을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X19']::text[],false,'{"seq":20,"concept":"SC5-2-u4-C10","difficulty":3,"kind":"error","stem":"재생 에너지 시설을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시윤 — 「재생 에너지 시설은 생태계에 아무 영향도 주지 않아.」","correct":true,"mis_target":"SC5-2-u4-X19"},{"t":"예나 — 「시설을 지을 때 비용이 많이 들어.」","mis":"SC5-2-u4-X19"},{"t":"도원 — 「기술이 더 발전해야 해.」","mis":"SC5-2-u4-X19"}],"explanation":["시설을 지어요.","생태계에 영향이 있어요.","시윤의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_b#21','sci',5,2,'u4','','g5_2_sci_u4_review_b','unit_review','SC5-2-u4-C21',3,'error','auto','누리반 탐방 일지 ⑧을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X41','SC5-2-u4-X40']::text[],false,'{"seq":21,"concept":"SC5-2-u4-C21","difficulty":3,"kind":"error","stem":"누리반 탐방 일지 ⑧을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태경 — 「재생 에너지 전문가는 석유 발전기를 더 늘리는 사람이야.」","correct":true,"mis_target":"SC5-2-u4-X41"},{"t":"나린 — 「바람이 센 자리를 찾아 발전기를 세워.」","mis":"SC5-2-u4-X41"},{"t":"주안 — 「배의 떨림도 에너지로 모을 수 있어.」","mis":"SC5-2-u4-X40"}],"explanation":["재생 에너지를 연구해요.","석유가 아니에요.","태경의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["재생 에너지 전문가 — 「바람이 가장 센 자리를 찾아 발전기를 세워요.」","에너지 하베스팅 전문가 — 「선착장을 밟는 발걸음과 배의 떨림을 모아요.」","우리 반 다짐 — 돌아가서도 자원과 에너지를 아끼자."],"title":"⑧ 마지막 날 — 전문가와 만남"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_b#22','sci',5,2,'u4','','g5_2_sci_u4_review_b','unit_review','SC5-2-u4-C22',3,'mc','auto','바람솔섬 탐방으로 정리한 내용으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X11','SC5-2-u4-X21','SC5-2-u4-X27']::text[],false,'{"seq":22,"concept":"SC5-2-u4-C22","difficulty":3,"kind":"mc","stem":"바람솔섬 탐방으로 정리한 내용으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자원은 한정되어 아끼고, 재생 에너지·친환경 기술·절약으로 에너지를 지속가능하게 쓴다","correct":true},{"t":"자원은 끝없이 있으니 재생 에너지는 필요 없다","mis":"SC5-2-u4-X11"},{"t":"석유가 가장 깨끗하니 석유만 쓴다","mis":"SC5-2-u4-X21"},{"t":"효율 등급 숫자가 큰 제품을 고른다","mis":"SC5-2-u4-X27"}],"explanation":["자원은 한정돼요.","지속가능하게 써요.","함께 실천해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_b#23','sci',5,2,'u4','','g5_2_sci_u4_review_b','unit_review','SC5-2-u4-C19',4,'essay','teacher','바람솔섬 마을 회관을 에너지 효율이 높은 건물로 바꾸려고 해요. 「열 막기」 방법 하나와 「에너지 만들기」 방법 하나를 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC5-2-u4-C19","difficulty":4,"kind":"essay","stem":"바람솔섬 마을 회관을 에너지 효율이 높은 건물로 바꾸려고 해요. 「열 막기」 방법 하나와 「에너지 만들기」 방법 하나를 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 열 막기 — 벽과 지붕에 단열재를 넣고 이중창으로 바꿔 겨울에 열이 빠져나가지 않게 한다. 에너지 만들기 — 지붕에 태양 전지판을 달아 햇빛으로 전기를 만들어 쓴다.","scoring_points":["열 막기 방법을 알맞게 썼는가","에너지 만들기 방법을 알맞게 썼는가","각 방법의 까닭을 썼는가"]},"explanation":["열을 막아요.","에너지를 만들어요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_b#24','sci',5,2,'u4','','g5_2_sci_u4_review_b','unit_review','SC5-2-u4-C10',4,'essay','teacher','「바람솔섬에 재생 에너지 시설을 더 늘려야 한다.」에 찬성하거나 반대하는 입장을 정하고, 알맞은 근거를 두 가지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-2-u4-C10","difficulty":4,"kind":"essay","stem":"「바람솔섬에 재생 에너지 시설을 더 늘려야 한다.」에 찬성하거나 반대하는 입장을 정하고, 알맞은 근거를 두 가지 쓰세요.","answer_guide":{"answer":"예: 찬성 — 재생 에너지는 자연에서 계속 얻을 수 있어 미래 세대도 쓸 수 있고, 대기오염 물질을 적게 내 섬의 환경을 지킨다. 반대 — 시설을 지을 때 비용이 많이 들고 새와 바다 생물의 보금자리가 망가질 수 있다.","scoring_points":["입장을 분명히 정했는가","입장에 맞는 근거를 하나 썼는가","입장에 맞는 근거를 하나 더 썼는가"]},"explanation":["입장을 정해요.","근거를 써요.","두 가지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_b#25','sci',5,2,'u4','','g5_2_sci_u4_review_b','unit_review','SC5-2-u4-C13',4,'essay','teacher','누리반 탐방 일지 ④의 마을 회의에 참여한다면 에너지를 지속가능하게 이용하는 방법을 세 갈래(재생 에너지·친환경 기술·절약)에서 하나씩 제안하세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-2-u4-C13","difficulty":4,"kind":"essay","stem":"누리반 탐방 일지 ④의 마을 회의에 참여한다면 에너지를 지속가능하게 이용하는 방법을 세 갈래(재생 에너지·친환경 기술·절약)에서 하나씩 제안하세요.","answer_guide":{"answer":"예: 재생 에너지 — 바닷가에 해양 에너지 시설을 더 짓는다. 친환경 기술 — 섬 버스를 전기차로 바꾼다. 절약 — 쓰지 않는 마을 회관 조명을 끈다.","scoring_points":["재생 에너지 제안을 썼는가","친환경 기술 제안을 썼는가","절약 제안을 썼는가"]},"explanation":["세 갈래예요.","하나씩 써요.","섬에 맞게 써요."],"asset":{"type":"passage","lines":["주민 1: 「바람이 약한 날은 전기가 모자라요.」","주민 2: 「옛날처럼 석유 발전기를 다시 돌립시다.」","주민 3: 「에너지를 모아 두는 기술을 들이고 모두 함께 아껴 씁시다.」","결정 — 재생 에너지를 늘리고 절약하며, 미래 세대를 생각한다."],"title":"④ 둘째 날 저녁 — 마을 회의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_c#1','sci',5,2,'u4','','g5_2_sci_u4_review_c','unit_review','SC5-2-u4-C1',1,'mc','auto','누리반 탐방 일지 ①의 언덕 위 발전기가 에너지를 만드는 데 쓰는 것은 어느 것인가요?',ARRAY['SC5-2-u4-X14','SC5-2-u4-X13']::text[],false,'{"seq":1,"concept":"SC5-2-u4-C1","difficulty":1,"kind":"mc","stem":"누리반 탐방 일지 ①의 언덕 위 발전기가 에너지를 만드는 데 쓰는 것은 어느 것인가요?","options":[{"t":"바람","correct":true},{"t":"땅속의 열","mis":"SC5-2-u4-X14"},{"t":"석유","mis":"SC5-2-u4-X13"},{"t":"밀물과 썰물","mis":"SC5-2-u4-X14"}],"explanation":["풍력 발전기예요.","날개가 돌아요.","바람을 써요."],"asset":{"type":"passage","lines":["배에서 내리자 언덕 위 풍력 발전기의 긴 날개 세 개가 돌고 있었다.","우리는 풍력 발전 모형에 머리 말리개 바람을 보냈다.","날개가 빨리 돌자 전구에 불이 켜졌다.","해설사: 「바람이 약한 날엔 날개가 천천히 돌아요.」"],"title":"① 첫날 — 바람의 섬에 도착"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_c#2','sci',5,2,'u4','','g5_2_sci_u4_review_c','unit_review','SC5-2-u4-C4',1,'ox','auto','돌, 철, 석탄은 광물 자원이에요.',ARRAY['SC5-2-u4-X06']::text[],false,'{"seq":2,"concept":"SC5-2-u4-C4","difficulty":1,"kind":"ox","stem":"돌, 철, 석탄은 광물 자원이에요.","answer":"O","reason_options":[{"t":"땅속에 묻힌 것을 캐내어 쓰기 때문에","correct":true},{"t":"숲에서 자라는 것을 베어 쓰기 때문에","mis":"SC5-2-u4-X06"}],"mis":"SC5-2-u4-X06","explanation":["땅속에 있어요.","캐내어 써요.","광물 자원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_c#3','sci',5,2,'u4','','g5_2_sci_u4_review_c','unit_review','SC5-2-u4-C6',1,'mc','auto','물·산림·광물 자원을 아껴 써야 하는 까닭은 어느 것인가요?',ARRAY['SC5-2-u4-X10','SC5-2-u4-X11','SC5-2-u4-X05']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C6","difficulty":1,"kind":"mc","stem":"물·산림·광물 자원을 아껴 써야 하는 까닭은 어느 것인가요?","options":[{"t":"양이 한정되어 있거나 다시 만들어지는 데 오래 걸려서","correct":true},{"t":"쓸수록 더 많아져서","mis":"SC5-2-u4-X10"},{"t":"재활용하면 끝없이 생겨서","mis":"SC5-2-u4-X11"},{"t":"미래에는 쓸 일이 없어서","mis":"SC5-2-u4-X05"}],"explanation":["한정되어 있어요.","오래 걸려요.","아껴 써야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_c#4','sci',5,2,'u4','','g5_2_sci_u4_review_c','unit_review','SC5-2-u4-C7',1,'ox','auto','재생 에너지는 자연에서 얻어 계속 이용할 수 있어요.',ARRAY['SC5-2-u4-X13']::text[],false,'{"seq":4,"concept":"SC5-2-u4-C7","difficulty":1,"kind":"ox","stem":"재생 에너지는 자연에서 얻어 계속 이용할 수 있어요.","answer":"O","reason_options":[{"t":"태양 빛·바람·물처럼 써도 줄지 않는 것에서 얻기 때문에","correct":true},{"t":"쓰면 쓸수록 바닥나는 것에서 얻기 때문에","mis":"SC5-2-u4-X13"}],"mis":"SC5-2-u4-X13","explanation":["자연에서 얻어요.","줄지 않아요.","계속 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_c#5','sci',5,2,'u4','','g5_2_sci_u4_review_c','unit_review','SC5-2-u4-C10',1,'ox','auto','재생 에너지 시설은 설치 비용이 많이 들기도 해요.',ARRAY['SC5-2-u4-X19']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C10","difficulty":1,"kind":"ox","stem":"재생 에너지 시설은 설치 비용이 많이 들기도 해요.","answer":"O","reason_options":[{"t":"시설을 만드는 데 돈과 기술이 많이 필요하기 때문에","correct":true},{"t":"재생 에너지 시설은 돈이 하나도 들지 않기 때문에","mis":"SC5-2-u4-X19"}],"mis":"SC5-2-u4-X19","explanation":["시설을 지어요.","비용이 들어요.","기술 발전이 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_c#6','sci',5,2,'u4','','g5_2_sci_u4_review_c','unit_review','SC5-2-u4-C13',1,'mc','auto','환경오염에 영향을 적게 주는 친환경 기술의 예는 어느 것인가요?',ARRAY['SC5-2-u4-X21','SC5-2-u4-X23']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C13","difficulty":1,"kind":"mc","stem":"환경오염에 영향을 적게 주는 친환경 기술의 예는 어느 것인가요?","options":[{"t":"전기차","correct":true},{"t":"석유를 많이 먹는 낡은 기계","mis":"SC5-2-u4-X21"},{"t":"밤새 켜 둔 조명","mis":"SC5-2-u4-X23"},{"t":"창문을 연 채 켠 난방","mis":"SC5-2-u4-X23"}],"explanation":["친환경 기술이에요.","오염을 줄여요.","전기차예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_c#7','sci',5,2,'u4','','g5_2_sci_u4_review_c','unit_review','SC5-2-u4-C14',1,'ox','auto','전원을 꺼도 플러그를 꽂아 두기만 하면 전기가 조금씩 쓰여요.',ARRAY['SC5-2-u4-X25']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C14","difficulty":1,"kind":"ox","stem":"전원을 꺼도 플러그를 꽂아 두기만 하면 전기가 조금씩 쓰여요.","answer":"O","reason_options":[{"t":"꽂혀 있는 동안 기기가 전기를 조금씩 쓰기 때문에","correct":true},{"t":"전원을 끄면 플러그와 상관없이 전기가 전혀 안 쓰이기 때문에","mis":"SC5-2-u4-X25"}],"mis":"SC5-2-u4-X25","explanation":["플러그가 꽂혀 있어요.","전기가 새요.","뽑아 두어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_c#8','sci',5,2,'u4','','g5_2_sci_u4_review_c','unit_review','SC5-2-u4-C17',1,'mc','auto','집 모형 실험에서 집 안 공기의 온도를 재려고 탐침 온도계를 꽂은 곳은 어디인가요?',ARRAY['SC5-2-u4-X32']::text[],false,'{"seq":8,"concept":"SC5-2-u4-C17","difficulty":1,"kind":"mc","stem":"집 모형 실험에서 집 안 공기의 온도를 재려고 탐침 온도계를 꽂은 곳은 어디인가요?","options":[{"t":"집 모형 지붕","correct":true},{"t":"손난로 속","mis":"SC5-2-u4-X32"},{"t":"실험대 바닥","mis":"SC5-2-u4-X32"},{"t":"친구의 손","mis":"SC5-2-u4-X32"}],"explanation":["지붕에 꽂아요.","공기 온도를 재요.","지붕이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_c#9','sci',5,2,'u4','','g5_2_sci_u4_review_c','unit_review','SC5-2-u4-C2',2,'match','auto','날개를 돌리는 방법과 알맞은 요령을 이으세요.','{}'::text[],false,'{"seq":9,"concept":"SC5-2-u4-C2","difficulty":2,"kind":"match","stem":"날개를 돌리는 방법과 알맞은 요령을 이으세요.","pairs":[{"l":"입으로 불기","r":"가운데를 세게 분다"},{"l":"빨대로 불기","r":"날개 면을 향해 비스듬히 분다"},{"l":"머리 말리개 쓰기","r":"몸에서 떨어뜨려 데지 않게 쓴다"}],"mis":"SC5-2-u4-X02","explanation":["가운데를 불어요.","비스듬히 불어요.","데지 않게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_c#10','sci',5,2,'u4','','g5_2_sci_u4_review_c','unit_review','SC5-2-u4-C5',2,'mc','auto','섬 사람들이 빗물까지 모아 쓰는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X07','SC5-2-u4-X08','SC5-2-u4-X05']::text[],false,'{"seq":10,"concept":"SC5-2-u4-C5","difficulty":2,"kind":"mc","stem":"섬 사람들이 빗물까지 모아 쓰는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"사람이 쓸 수 있는 깨끗한 물이 한정되어 있어서","correct":true},{"t":"빗물을 모으면 지구의 물이 새로 생겨서","mis":"SC5-2-u4-X07"},{"t":"물은 돌고 도니 아낄 필요가 없어서","mis":"SC5-2-u4-X08"},{"t":"빗물은 자원이 아니어서","mis":"SC5-2-u4-X05"}],"explanation":["깨끗한 물이 귀해요.","빗물을 모아요.","물을 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_c#11','sci',5,2,'u4','','g5_2_sci_u4_review_c','unit_review','SC5-2-u4-C8',2,'ox','auto','태양 에너지는 태양의 뜨거운 열만 이용하는 에너지예요.',ARRAY['SC5-2-u4-X15']::text[],false,'{"seq":11,"concept":"SC5-2-u4-C8","difficulty":2,"kind":"ox","stem":"태양 에너지는 태양의 뜨거운 열만 이용하는 에너지예요.","answer":"X","reason_options":[{"t":"태양 빛을 이용하는 것이 많고 태양열을 이용하기도 하기 때문에","correct":true},{"t":"태양은 빛을 내지 않고 열만 내기 때문에","mis":"SC5-2-u4-X15"}],"mis":"SC5-2-u4-X15","explanation":["빛을 많이 써요.","열도 써요.","열만은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_c#12','sci',5,2,'u4','','g5_2_sci_u4_review_c','unit_review','SC5-2-u4-C10',2,'ox','auto','재생 에너지는 언제나 같은 양을 얻을 수 있어 아무 걱정이 없어요.',ARRAY['SC5-2-u4-X19']::text[],false,'{"seq":12,"concept":"SC5-2-u4-C10","difficulty":2,"kind":"ox","stem":"재생 에너지는 언제나 같은 양을 얻을 수 있어 아무 걱정이 없어요.","answer":"X","reason_options":[{"t":"날씨의 영향을 받아 얻는 양이 달라지기 때문에","correct":true},{"t":"재생 에너지는 날씨와 아무 상관이 없기 때문에","mis":"SC5-2-u4-X19"}],"mis":"SC5-2-u4-X19","explanation":["날씨가 바뀌어요.","양이 달라져요.","걱정할 점이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_c#13','sci',5,2,'u4','','g5_2_sci_u4_review_c','unit_review','SC5-2-u4-C13',2,'ox','auto','재생 에너지만 늘리면 에너지를 아낄 필요는 전혀 없어요.',ARRAY['SC5-2-u4-X24']::text[],false,'{"seq":13,"concept":"SC5-2-u4-C13","difficulty":2,"kind":"ox","stem":"재생 에너지만 늘리면 에너지를 아낄 필요는 전혀 없어요.","answer":"X","reason_options":[{"t":"재생 에너지와 함께 친환경 기술과 절약도 필요하기 때문에","correct":true},{"t":"재생 에너지가 이미 넘칠 만큼 충분하기 때문에","mis":"SC5-2-u4-X24"}],"mis":"SC5-2-u4-X24","explanation":["재생 에너지도 좋아요.","절약도 필요해요.","함께 해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_c#14','sci',5,2,'u4','','g5_2_sci_u4_review_c','unit_review','SC5-2-u4-C14',2,'ox','auto','에너지 소비 효율 5등급 제품이 1등급 제품보다 효율이 더 높아요.',ARRAY['SC5-2-u4-X27']::text[],false,'{"seq":14,"concept":"SC5-2-u4-C14","difficulty":2,"kind":"ox","stem":"에너지 소비 효율 5등급 제품이 1등급 제품보다 효율이 더 높아요.","answer":"X","reason_options":[{"t":"1등급에 가까울수록 효율이 높기 때문에","correct":true},{"t":"등급 숫자가 클수록 효율이 높기 때문에","mis":"SC5-2-u4-X27"}],"mis":"SC5-2-u4-X27","explanation":["1~5등급이 있어요.","1등급에 가까울수록요.","5등급은 낮아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_c#15','sci',5,2,'u4','','g5_2_sci_u4_review_c','unit_review','SC5-2-u4-C15',2,'ox','auto','종이 영수증 대신 전자 영수증을 받으면 산림 자원을 아낄 수 있어요.',ARRAY['SC5-2-u4-X30']::text[],false,'{"seq":15,"concept":"SC5-2-u4-C15","difficulty":2,"kind":"ox","stem":"종이 영수증 대신 전자 영수증을 받으면 산림 자원을 아낄 수 있어요.","answer":"O","reason_options":[{"t":"종이를 덜 써 나무를 아끼기 때문에","correct":true},{"t":"전자 영수증은 물 자원만 아끼기 때문에","mis":"SC5-2-u4-X30"}],"mis":"SC5-2-u4-X30","explanation":["종이를 안 써요.","나무를 아껴요.","산림 자원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_c#16','sci',5,2,'u4','','g5_2_sci_u4_review_c','unit_review','SC5-2-u4-C18',2,'ox','auto','누리반 탐방 일지 ⑥처럼 처음 온도가 다를 때는 온도 변화량으로 두 집을 견주어요.',ARRAY['SC5-2-u4-X34']::text[],false,'{"seq":16,"concept":"SC5-2-u4-C18","difficulty":2,"kind":"ox","stem":"누리반 탐방 일지 ⑥처럼 처음 온도가 다를 때는 온도 변화량으로 두 집을 견주어요.","answer":"O","reason_options":[{"t":"처음 온도가 달라 마지막 온도만으로는 견줄 수 없기 때문에","correct":true},{"t":"마지막 온도가 높은 집이 언제나 단열한 집이기 때문에","mis":"SC5-2-u4-X34"}],"mis":"SC5-2-u4-X34","explanation":["처음이 달라요.","변화량을 구해요.","공정하게 견줘요."],"asset":{"type":"passage","lines":["단열 안 한 집 — 처음 28.0 °C → 5분 뒤 23.6 °C","단열한 집(뽁뽁이 두 겹·우드록·색점토) — 처음 27.0 °C → 5분 뒤 25.2 °C","두 집은 크기가 같고, 같은 손난로로 데운 뒤 1분마다 쟀다."],"title":"⑥ 셋째 날 오후 — 집 모형 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_c#17','sci',5,2,'u4','','g5_2_sci_u4_review_c','unit_review','SC5-2-u4-C17',3,'mc','auto','집 모형 실험에서 같게 해야 할 조건을 바르게 모은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X31']::text[],false,'{"seq":17,"concept":"SC5-2-u4-C17","difficulty":3,"kind":"mc","stem":"집 모형 실험에서 같게 해야 할 조건을 바르게 모은 것은 어느 것인가요?","options":[{"t":"집 모형의 크기, 손난로의 종류, 온도를 재는 시간 간격","correct":true},{"t":"단열재의 겹 수, 집 모형의 크기, 손난로의 종류","mis":"SC5-2-u4-X31"},{"t":"창문의 뽁뽁이 수, 단열재, 색점토","mis":"SC5-2-u4-X31"},{"t":"재는 시각, 단열재, 손난로를 넣는 시간","mis":"SC5-2-u4-X31"}],"explanation":["단열만 달라요.","나머지는 같아요.","그래야 견줄 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_c#18','sci',5,2,'u4','','g5_2_sci_u4_review_c','unit_review','SC5-2-u4-C19',3,'ox','auto','누리반 탐방 일지 ③의 마을 회관처럼 땅속 열을 냉난방에 쓰는 것은 에너지를 직접 얻어 쓰는 방법이에요.',ARRAY['SC5-2-u4-X35']::text[],false,'{"seq":18,"concept":"SC5-2-u4-C19","difficulty":3,"kind":"ox","stem":"누리반 탐방 일지 ③의 마을 회관처럼 땅속 열을 냉난방에 쓰는 것은 에너지를 직접 얻어 쓰는 방법이에요.","answer":"O","reason_options":[{"t":"땅속 열이라는 재생 에너지를 끌어 와 쓰기 때문에","correct":true},{"t":"땅속 열은 열이 빠져나가는 것을 막는 단열재이기 때문에","mis":"SC5-2-u4-X35"}],"mis":"SC5-2-u4-X35","explanation":["땅속 열을 써요.","재생 에너지예요.","직접 얻어 써요."],"asset":{"type":"passage","lines":["언덕 — 풍력 발전기","집 지붕 — 태양 전지판","바닷가 둑 — 밀물과 썰물을 쓰는 발전 시설","돼지 농장 — 분뇨로 가스를 만드는 시설","마을 회관 땅속 — 땅속 열을 쓰는 냉난방"],"title":"③ 둘째 날 — 섬의 재생 에너지 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_c#19','sci',5,2,'u4','','g5_2_sci_u4_review_c','unit_review','SC5-2-u4-C20',3,'ox','auto','실천 영상의 주제는 섬 생활에서 실제로 할 수 있는 일로 정하는 것이 좋아요.',ARRAY['SC5-2-u4-X37']::text[],false,'{"seq":19,"concept":"SC5-2-u4-C20","difficulty":3,"kind":"ox","stem":"실천 영상의 주제는 섬 생활에서 실제로 할 수 있는 일로 정하는 것이 좋아요.","answer":"O","reason_options":[{"t":"보는 사람이 따라 하며 함께 실천할 수 있기 때문에","correct":true},{"t":"실천할 수 없는 일이어야 더 눈길을 끌기 때문에","mis":"SC5-2-u4-X37"}],"mis":"SC5-2-u4-X37","explanation":["할 수 있는 일이에요.","따라 할 수 있어요.","함께 실천해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_c#20','sci',5,2,'u4','','g5_2_sci_u4_review_c','unit_review','SC5-2-u4-C10',3,'mc','auto','재생 에너지 시설을 늘리자는 의견을 지지하는 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X19','SC5-2-u4-X13']::text[],false,'{"seq":20,"concept":"SC5-2-u4-C10","difficulty":3,"kind":"mc","stem":"재생 에너지 시설을 늘리자는 의견을 지지하는 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자연에서 계속 얻을 수 있고 대기오염 물질을 적게 내 미래 세대에 깨끗한 환경을 남긴다","correct":true},{"t":"시설을 지을 때 비용이 많이 든다","mis":"SC5-2-u4-X19"},{"t":"날씨에 따라 얻는 양이 달라진다","mis":"SC5-2-u4-X19"},{"t":"석유보다 쓸수록 빨리 바닥난다","mis":"SC5-2-u4-X13"}],"explanation":["계속 얻어요.","깨끗해요.","찬성 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_c#21','sci',5,2,'u4','','g5_2_sci_u4_review_c','unit_review','SC5-2-u4-C21',3,'ox','auto','배가 움직일 때 생기는 떨림도 모으면 에너지로 쓸 수 있어요.',ARRAY['SC5-2-u4-X40']::text[],false,'{"seq":21,"concept":"SC5-2-u4-C21","difficulty":3,"kind":"ox","stem":"배가 움직일 때 생기는 떨림도 모으면 에너지로 쓸 수 있어요.","answer":"O","reason_options":[{"t":"버려지는 떨림을 모아 쓰는 기술이 있기 때문에","correct":true},{"t":"떨림은 에너지가 될 수 없기 때문에","mis":"SC5-2-u4-X40"}],"mis":"SC5-2-u4-X40","explanation":["배가 떨려요.","버려지는 에너지예요.","모아 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_c#22','sci',5,2,'u4','','g5_2_sci_u4_review_c','unit_review','SC5-2-u4-C22',3,'ox','auto','자원과 에너지를 효율적으로 쓰면 돈도 아끼고 환경을 지키는 데도 도움이 돼요.',ARRAY['SC5-2-u4-X42']::text[],false,'{"seq":22,"concept":"SC5-2-u4-C22","difficulty":3,"kind":"ox","stem":"자원과 에너지를 효율적으로 쓰면 돈도 아끼고 환경을 지키는 데도 도움이 돼요.","answer":"O","reason_options":[{"t":"덜 쓰고 다시 써 비용과 오염이 함께 줄기 때문에","correct":true},{"t":"효율적으로 쓰면 환경이 더 오염되기 때문에","mis":"SC5-2-u4-X42"}],"mis":"SC5-2-u4-X42","explanation":["덜 써요.","돈을 아껴요.","환경도 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_c#23','sci',5,2,'u4','','g5_2_sci_u4_review_c','unit_review','SC5-2-u4-C18',4,'mc','auto','처음 32.0 °C에서 5분 뒤 26.5 °C가 된 집 ㉮와, 처음 30.0 °C에서 5분 뒤 27.6 °C가 된 집 ㉯ 가운데 단열이 더 잘된 집과 까닭은 어느 것인가요?',ARRAY['SC5-2-u4-X34','SC5-2-u4-X33']::text[],false,'{"seq":23,"concept":"SC5-2-u4-C18","difficulty":4,"kind":"mc","stem":"처음 32.0 °C에서 5분 뒤 26.5 °C가 된 집 ㉮와, 처음 30.0 °C에서 5분 뒤 27.6 °C가 된 집 ㉯ 가운데 단열이 더 잘된 집과 까닭은 어느 것인가요?","options":[{"t":"㉯, 온도 변화량이 2.4 °C로 ㉮의 5.5 °C보다 작아서","correct":true},{"t":"㉮, 처음 온도가 더 높아서","mis":"SC5-2-u4-X34"},{"t":"㉮, 온도 변화량이 더 커서","mis":"SC5-2-u4-X33"},{"t":"㉯, 5분 뒤 온도가 더 높아서","mis":"SC5-2-u4-X34"}],"explanation":["처음 온도가 달라요.","변화량을 구해요.","㉯가 덜 변했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_c#24','sci',5,2,'u4','','g5_2_sci_u4_review_c','unit_review','SC5-2-u4-C9',4,'mc','auto','바람솔섬에 새 마을을 만든다면 가장 알맞은 재생 에너지 계획은 어느 것인가요?',ARRAY['SC5-2-u4-X18','SC5-2-u4-X21','SC5-2-u4-X19']::text[],false,'{"seq":24,"concept":"SC5-2-u4-C9","difficulty":4,"kind":"mc","stem":"바람솔섬에 새 마을을 만든다면 가장 알맞은 재생 에너지 계획은 어느 것인가요?","options":[{"t":"언덕에 풍력, 지붕에 태양 전지판, 농장 분뇨로 바이오 에너지, 바닷가에 해양 에너지","correct":true},{"t":"언덕에 바이오 에너지, 지붕에 수력, 바닷가에 지열 에너지","mis":"SC5-2-u4-X18"},{"t":"모든 곳에 석유 발전기","mis":"SC5-2-u4-X21"},{"t":"재생 에너지는 단점이 없으니 한 가지만","mis":"SC5-2-u4-X19"}],"explanation":["장소마다 달라요.","섬의 자연을 써요.","여러 가지를 함께요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_c#25','sci',5,2,'u4','','g5_2_sci_u4_review_c','unit_review','SC5-2-u4-C13',4,'mc','auto','바람솔섬의 에너지 문제를 푸는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X21','SC5-2-u4-X24','SC5-2-u4-X22']::text[],false,'{"seq":25,"concept":"SC5-2-u4-C13","difficulty":4,"kind":"mc","stem":"바람솔섬의 에너지 문제를 푸는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"재생 에너지를 늘리고 에너지를 모아 두는 기술을 들이며, 주민 모두가 절약을 함께 한다","correct":true},{"t":"석유 발전기를 다시 돌려 마음껏 쓴다","mis":"SC5-2-u4-X21"},{"t":"재생 에너지만 늘리고 절약은 하지 않는다","mis":"SC5-2-u4-X24"},{"t":"미래 세대가 알아서 하도록 둔다","mis":"SC5-2-u4-X22"}],"explanation":["재생 에너지예요.","기술도 들여요.","절약도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_d#1','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C2',1,'sa','auto','누리반 탐방 일지 ①에서 모형의 날개를 돌리려고 쓴 기구는 무엇인가요? 다섯 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u4-C2","difficulty":1,"kind":"sa","stem":"누리반 탐방 일지 ①에서 모형의 날개를 돌리려고 쓴 기구는 무엇인가요? 다섯 글자로 쓰세요.","answer":["머리말리개","머리 말리개"],"explanation":["바람을 보내요.","다섯 글자예요.","머리 말리개예요."],"asset":{"type":"passage","lines":["배에서 내리자 언덕 위 풍력 발전기의 긴 날개 세 개가 돌고 있었다.","우리는 풍력 발전 모형에 머리 말리개 바람을 보냈다.","날개가 빨리 돌자 전구에 불이 켜졌다.","해설사: 「바람이 약한 날엔 날개가 천천히 돌아요.」"],"title":"① 첫날 — 바람의 섬에 도착"},"mis":"SC5-2-u4-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_d#2','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C3',1,'sa','auto','물·나무·철처럼 생활하거나 물건을 만들 때 쓰는 원료를 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-2-u4-C3","difficulty":1,"kind":"sa","stem":"물·나무·철처럼 생활하거나 물건을 만들 때 쓰는 원료를 두 글자로 쓰세요.","answer":["자원"],"explanation":["원료예요.","두 글자예요.","자원이에요."],"mis":"SC5-2-u4-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_d#3','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C5',1,'mc','auto','물을 쓰고 난 뒤 지구 전체 물의 양은 어떻게 되나요?',ARRAY['SC5-2-u4-X07']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C5","difficulty":1,"kind":"mc","stem":"물을 쓰고 난 뒤 지구 전체 물의 양은 어떻게 되나요?","options":[{"t":"총량은 줄지 않는다","correct":true},{"t":"쓴 만큼 사라진다","mis":"SC5-2-u4-X07"},{"t":"쓸수록 늘어난다","mis":"SC5-2-u4-X07"},{"t":"바닷물만 사라진다","mis":"SC5-2-u4-X07"}],"explanation":["물은 돌고 돌아요.","총량은 그대로예요.","깨끗한 물이 문제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_d#4','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C8',1,'sa','auto','누리반 탐방 일지 ③에서 마을 회관이 냉난방에 쓰는 땅속 열은 어떤 재생 에너지인가요? 다섯 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-2-u4-C8","difficulty":1,"kind":"sa","stem":"누리반 탐방 일지 ③에서 마을 회관이 냉난방에 쓰는 땅속 열은 어떤 재생 에너지인가요? 다섯 글자로 쓰세요.","answer":["지열에너지","지열 에너지"],"explanation":["땅속 열이에요.","다섯 글자예요.","지열 에너지예요."],"asset":{"type":"passage","lines":["언덕 — 풍력 발전기","집 지붕 — 태양 전지판","바닷가 둑 — 밀물과 썰물을 쓰는 발전 시설","돼지 농장 — 분뇨로 가스를 만드는 시설","마을 회관 땅속 — 땅속 열을 쓰는 냉난방"],"title":"③ 둘째 날 — 섬의 재생 에너지 지도"},"mis":"SC5-2-u4-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_d#5','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C9',1,'mc','auto','햇빛이 잘 드는 넓은 지붕에 알맞은 재생 에너지 시설은 어느 것인가요?',ARRAY['SC5-2-u4-X18']::text[],false,'{"seq":5,"concept":"SC5-2-u4-C9","difficulty":1,"kind":"mc","stem":"햇빛이 잘 드는 넓은 지붕에 알맞은 재생 에너지 시설은 어느 것인가요?","options":[{"t":"태양 전지판","correct":true},{"t":"풍력 발전기","mis":"SC5-2-u4-X18"},{"t":"밀물과 썰물을 쓰는 둑","mis":"SC5-2-u4-X18"},{"t":"분뇨로 가스를 만드는 시설","mis":"SC5-2-u4-X18"}],"explanation":["햇빛이 잘 들어요.","빛을 받아요.","태양 전지판이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_d#6','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C12',1,'mc','auto','에너지를 지속가능하게 이용하는 예는 어느 것인가요?',ARRAY['SC5-2-u4-X23']::text[],false,'{"seq":6,"concept":"SC5-2-u4-C12","difficulty":1,"kind":"mc","stem":"에너지를 지속가능하게 이용하는 예는 어느 것인가요?","options":[{"t":"가까운 곳은 걷거나 자전거를 탄다","correct":true},{"t":"가까운 거리도 늘 자동차를 탄다","mis":"SC5-2-u4-X23"},{"t":"보지 않는 텔레비전을 켜 둔다","mis":"SC5-2-u4-X23"},{"t":"창문을 연 채 난방을 한다","mis":"SC5-2-u4-X23"}],"explanation":["가까운 곳이에요.","걸어가요.","에너지를 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_d#7','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C15',1,'mc','auto','누리반 탐방 일지 ⑤에서 움직임을 알아차리는 수도꼭지가 아끼는 것은 어느 것인가요?',ARRAY['SC5-2-u4-X30']::text[],false,'{"seq":7,"concept":"SC5-2-u4-C15","difficulty":1,"kind":"mc","stem":"누리반 탐방 일지 ⑤에서 움직임을 알아차리는 수도꼭지가 아끼는 것은 어느 것인가요?","options":[{"t":"물","correct":true},{"t":"나무","mis":"SC5-2-u4-X30"},{"t":"철","mis":"SC5-2-u4-X30"},{"t":"석탄","mis":"SC5-2-u4-X30"}],"explanation":["수도꼭지예요.","물이 저절로 멈춰요.","물을 아껴요."],"asset":{"type":"passage","lines":["냉장고 ㉮ — 1등급, 냉장고 ㉯ — 5등급(크기와 기능이 같다)","꺼 둔 텔레비전의 플러그가 꽂혀 있었다.","수도꼭지는 움직임을 알아차려 저절로 멈추는 것으로 바뀌었다.","종이컵 대신 다회용 컵이 놓여 있었다."],"title":"⑤ 셋째 날 — 마을 회관 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_d#8','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C18',1,'sa','auto','누리반 탐방 일지 ⑥에서 단열한 집의 5분 뒤 온도는 몇 °C인가요? 숫자만 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SC5-2-u4-C18","difficulty":1,"kind":"sa","stem":"누리반 탐방 일지 ⑥에서 단열한 집의 5분 뒤 온도는 몇 °C인가요? 숫자만 쓰세요.","answer":["25.2","25.2 °C","25.2도"],"explanation":["단열한 집을 봐요.","5분 뒤예요.","25.2 °C예요."],"asset":{"type":"passage","lines":["단열 안 한 집 — 처음 28.0 °C → 5분 뒤 23.6 °C","단열한 집(뽁뽁이 두 겹·우드록·색점토) — 처음 27.0 °C → 5분 뒤 25.2 °C","두 집은 크기가 같고, 같은 손난로로 데운 뒤 1분마다 쟀다."],"title":"⑥ 셋째 날 오후 — 집 모형 실험"},"mis":"SC5-2-u4-X34"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_d#9','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C1',2,'mc','auto','누리반 탐방 일지 ①의 풍력 발전기와 풍력 발전 모형의 같은 점은 어느 것인가요?',ARRAY['SC5-2-u4-X03']::text[],false,'{"seq":9,"concept":"SC5-2-u4-C1","difficulty":2,"kind":"mc","stem":"누리반 탐방 일지 ①의 풍력 발전기와 풍력 발전 모형의 같은 점은 어느 것인가요?","options":[{"t":"바람이 불면 회전 날개가 돌아간다","correct":true},{"t":"둘 다 머리 말리개로만 돈다","mis":"SC5-2-u4-X03"},{"t":"둘 다 언덕 위에만 있다","mis":"SC5-2-u4-X03"},{"t":"둘 다 바람 없이 돈다","mis":"SC5-2-u4-X03"}],"explanation":["둘 다 날개가 있어요.","바람이 불어요.","날개가 돌아요."],"asset":{"type":"passage","lines":["배에서 내리자 언덕 위 풍력 발전기의 긴 날개 세 개가 돌고 있었다.","우리는 풍력 발전 모형에 머리 말리개 바람을 보냈다.","날개가 빨리 돌자 전구에 불이 켜졌다.","해설사: 「바람이 약한 날엔 날개가 천천히 돌아요.」"],"title":"① 첫날 — 바람의 섬에 도착"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_d#10','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C5',2,'error','auto','누리반 탐방 일지 ②를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X08','SC5-2-u4-X09','SC5-2-u4-X10']::text[],false,'{"seq":10,"concept":"SC5-2-u4-C5","difficulty":2,"kind":"error","stem":"누리반 탐방 일지 ②를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태민 — 「물은 돌고 도니까 깨끗한 물도 절대 줄지 않아.」","correct":true,"mis_target":"SC5-2-u4-X08"},{"t":"유나 — 「나무가 다시 자라려면 오래 걸려.」","mis":"SC5-2-u4-X09"},{"t":"정우 — 「돌 광산은 돌이 바닥나 문을 닫았어.」","mis":"SC5-2-u4-X10"}],"explanation":["물의 총량은 그대로예요.","깨끗한 물은 줄어요.","태민의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["섬 사람들은 우물물과 빗물을 모아 쓴다.","뒷산 나무로 집을 지었는데, 다시 자라려면 오래 걸린다고 한다.","옛 돌 광산은 묻혀 있던 돌이 바닥나 문을 닫았다.","섬마을 이장님: 「캔은 꼭 분리배출해요.」"],"title":"② 첫날 오후 — 섬의 자원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_d#11','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C8',2,'mc','auto','바람솔섬에 물이 세차게 흘러내리는 골짜기가 있다면 더 얻을 수 있는 재생 에너지는 어느 것인가요?',ARRAY['SC5-2-u4-X14','SC5-2-u4-X17']::text[],false,'{"seq":11,"concept":"SC5-2-u4-C8","difficulty":2,"kind":"mc","stem":"바람솔섬에 물이 세차게 흘러내리는 골짜기가 있다면 더 얻을 수 있는 재생 에너지는 어느 것인가요?","options":[{"t":"수력","correct":true},{"t":"해양 에너지","mis":"SC5-2-u4-X14"},{"t":"바이오 에너지","mis":"SC5-2-u4-X17"},{"t":"지열 에너지","mis":"SC5-2-u4-X14"}],"explanation":["물이 떨어져요.","흐름을 써요.","수력이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_d#12','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C10',2,'error','auto','재생 에너지를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X20']::text[],false,'{"seq":12,"concept":"SC5-2-u4-C10","difficulty":2,"kind":"error","stem":"재생 에너지를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"소라 — 「재생 에너지는 모양이 멋져서 주목받는 거야.」","correct":true,"mis_target":"SC5-2-u4-X20"},{"t":"현우 — 「계속 쓸 수 있어서 주목받아.」","mis":"SC5-2-u4-X20"},{"t":"지나 — 「환경오염에 영향을 적게 줘.」","mis":"SC5-2-u4-X20"}],"explanation":["모양 때문이 아니에요.","계속·깨끗하게예요.","소라의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_d#13','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C11',2,'mc','auto','바람솔섬 사람들이 에너지를 지속가능하게 이용하려는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X22','SC5-2-u4-X21']::text[],false,'{"seq":13,"concept":"SC5-2-u4-C11","difficulty":2,"kind":"mc","stem":"바람솔섬 사람들이 에너지를 지속가능하게 이용하려는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"미래 세대도 깨끗한 에너지를 쓰고 기후변화에 대응하려고","correct":true},{"t":"지금 세대가 더 많이 쓰려고","mis":"SC5-2-u4-X22"},{"t":"석유를 빨리 다 쓰려고","mis":"SC5-2-u4-X21"},{"t":"미래에는 섬에 사람이 없어서","mis":"SC5-2-u4-X22"}],"explanation":["미래 세대가 있어요.","깨끗한 에너지예요.","기후변화도 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_d#14','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C16',2,'error','auto','마을 회관을 살펴보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X26','SC5-2-u4-X27']::text[],false,'{"seq":14,"concept":"SC5-2-u4-C16","difficulty":2,"kind":"error","stem":"마을 회관을 살펴보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"세준 — 「전기를 많이 쓸수록 효율이 높은 거야.」","correct":true,"mis_target":"SC5-2-u4-X26"},{"t":"다희 — 「LED 조명으로 바꾸면 좋겠어.」","mis":"SC5-2-u4-X26"},{"t":"윤호 — 「1등급 냉장고가 전기를 덜 써.」","mis":"SC5-2-u4-X27"}],"explanation":["효율은 적게 쓰는 거예요.","같은 일에 덜 써요.","세준의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_d#15','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C15',2,'mc','auto','산림 자원을 지키려고 섬 사람들이 할 수 있는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X09','SC5-2-u4-X28']::text[],false,'{"seq":15,"concept":"SC5-2-u4-C15","difficulty":2,"kind":"mc","stem":"산림 자원을 지키려고 섬 사람들이 할 수 있는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"나무를 벤 자리에 다시 나무를 심고 가꾼다","correct":true},{"t":"뒷산 나무를 한꺼번에 모두 벤다","mis":"SC5-2-u4-X09"},{"t":"숲을 모두 밭으로 바꾼다","mis":"SC5-2-u4-X09"},{"t":"나무 의자를 고치지 않고 바로 버린다","mis":"SC5-2-u4-X28"}],"explanation":["나무를 심어요.","가꿔요.","숲을 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_d#16','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C18',2,'error','auto','누리반 탐방 일지 ⑥을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X33','SC5-2-u4-X34','SC5-2-u4-X31']::text[],false,'{"seq":16,"concept":"SC5-2-u4-C18","difficulty":2,"kind":"error","stem":"누리반 탐방 일지 ⑥을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하겸 — 「단열 안 한 집이 더 많이 변했으니 효율이 더 높아.」","correct":true,"mis_target":"SC5-2-u4-X33"},{"t":"보은 — 「단열한 집은 1.8 °C만 낮아졌어.」","mis":"SC5-2-u4-X34"},{"t":"지후 — 「두 집 크기는 같았어.」","mis":"SC5-2-u4-X31"}],"explanation":["많이 변하면 열이 샜어요.","덜 변해야 좋아요.","하겸의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["단열 안 한 집 — 처음 28.0 °C → 5분 뒤 23.6 °C","단열한 집(뽁뽁이 두 겹·우드록·색점토) — 처음 27.0 °C → 5분 뒤 25.2 °C","두 집은 크기가 같고, 같은 손난로로 데운 뒤 1분마다 쟀다."],"title":"⑥ 셋째 날 오후 — 집 모형 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_d#17','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C18',3,'ox','auto','집 모형 실험에서 온도 변화량이 큰 집일수록 에너지 효율이 높아요.',ARRAY['SC5-2-u4-X33']::text[],false,'{"seq":17,"concept":"SC5-2-u4-C18","difficulty":3,"kind":"ox","stem":"집 모형 실험에서 온도 변화량이 큰 집일수록 에너지 효율이 높아요.","answer":"X","reason_options":[{"t":"온도 변화가 작아야 열이 덜 빠져나간 것이기 때문에","correct":true},{"t":"온도가 많이 변해야 열을 잘 지킨 것이기 때문에","mis":"SC5-2-u4-X33"}],"mis":"SC5-2-u4-X33","explanation":["변화량을 봐요.","작아야 좋아요.","큰 집은 열이 샜어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_d#18','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C19',3,'mc','auto','창이 한 겹이고 창틀 틈으로 바람이 새어 드는 섬 학교를 고치는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X35','SC5-2-u4-X33','SC5-2-u4-X23']::text[],false,'{"seq":18,"concept":"SC5-2-u4-C19","difficulty":3,"kind":"mc","stem":"창이 한 겹이고 창틀 틈으로 바람이 새어 드는 섬 학교를 고치는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"창을 이중창으로 바꾸고 창틀 틈을 막는다","correct":true},{"t":"창을 더 얇은 유리로 바꾼다","mis":"SC5-2-u4-X35"},{"t":"틈을 더 넓혀 바람을 잘 통하게 한다","mis":"SC5-2-u4-X33"},{"t":"난방기를 세게 켜고 창을 연다","mis":"SC5-2-u4-X23"}],"explanation":["창을 두 겹으로요.","틈을 막아요.","열을 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_d#19','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C20',3,'mc','auto','누리반 탐방 일지 ⑦의 영상에 더 넣기 알맞은 장면은 어느 것인가요?',ARRAY['SC5-2-u4-X28','SC5-2-u4-X38','SC5-2-u4-X37']::text[],false,'{"seq":19,"concept":"SC5-2-u4-C20","difficulty":3,"kind":"mc","stem":"누리반 탐방 일지 ⑦의 영상에 더 넣기 알맞은 장면은 어느 것인가요?","options":[{"t":"설거지할 때 물을 받아 쓰는 모습","correct":true},{"t":"수도꼭지를 틀어 둔 채 자리를 비우는 모습","mis":"SC5-2-u4-X28"},{"t":"주민의 집 주소를 보여 주는 모습","mis":"SC5-2-u4-X38"},{"t":"물과 상관없는 놀이 장면","mis":"SC5-2-u4-X37"}],"explanation":["물 아끼기가 주제예요.","받아 써요.","알맞은 장면이에요."],"asset":{"type":"passage","lines":["주제 — 바람솔섬의 물 아끼기","장면 — 비누칠할 때 물 잠그기, 모은 빗물로 화분에 물 주기","지킬 점 — 주민의 얼굴과 이름은 허락 없이 넣지 않는다.","다 만든 영상은 학급 누리집에 올렸다."],"title":"⑦ 넷째 날 — 실천 영상 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_d#20','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C9',3,'ox','auto','햇빛이 거의 들지 않는 깊은 골짜기에는 태양 에너지보다 물의 흐름을 쓰는 수력이 더 알맞아요.',ARRAY['SC5-2-u4-X18']::text[],false,'{"seq":20,"concept":"SC5-2-u4-C9","difficulty":3,"kind":"ox","stem":"햇빛이 거의 들지 않는 깊은 골짜기에는 태양 에너지보다 물의 흐름을 쓰는 수력이 더 알맞아요.","answer":"O","reason_options":[{"t":"지역에 많은 자연을 이용하는 재생 에너지를 골라야 하기 때문에","correct":true},{"t":"어느 지역이든 태양 에너지만 알맞기 때문에","mis":"SC5-2-u4-X18"}],"mis":"SC5-2-u4-X18","explanation":["햇빛이 적어요.","물이 흘러요.","수력이 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_d#21','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C21',3,'mc','auto','재생 에너지 전문가가 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X40','SC5-2-u4-X41']::text[],false,'{"seq":21,"concept":"SC5-2-u4-C21","difficulty":3,"kind":"mc","stem":"재생 에너지 전문가가 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"더 좋은 태양 전지와 풍력 발전기를 연구하고 알맞은 설치 장소를 찾는다","correct":true},{"t":"버려지는 체온만 모은다","mis":"SC5-2-u4-X40"},{"t":"석탄을 더 많이 캔다","mis":"SC5-2-u4-X41"},{"t":"영상만 만든다","mis":"SC5-2-u4-X41"}],"explanation":["재생 에너지를 연구해요.","장소를 찾아요.","알려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_d#22','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C22',3,'match','auto','탐방에서 본 모습과 배운 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":22,"concept":"SC5-2-u4-C22","difficulty":3,"kind":"match","stem":"탐방에서 본 모습과 배운 내용을 알맞게 이으세요.","pairs":[{"l":"바닥난 돌 광산","r":"자원은 한정되어 있다"},{"l":"바닷가 둑의 발전 시설","r":"재생 에너지를 쓴다"},{"l":"1등급 냉장고","r":"에너지를 효율적으로 쓴다"}],"mis":"SC5-2-u4-X42","explanation":["광산은 바닥났어요.","둑은 바다를 써요.","냉장고는 효율적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_d#23','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C17',4,'mc','auto','집 모형 실험의 결과가 모둠마다 조금씩 달랐어요. 결과를 더 믿을 수 있게 하는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X34','SC5-2-u4-X31','SC5-2-u4-X32']::text[],false,'{"seq":23,"concept":"SC5-2-u4-C17","difficulty":4,"kind":"mc","stem":"집 모형 실험의 결과가 모둠마다 조금씩 달랐어요. 결과를 더 믿을 수 있게 하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"조건을 같게 하여 여러 번 되풀이하고 모둠 결과를 함께 견준다","correct":true},{"t":"가장 마음에 드는 결과 하나만 고른다","mis":"SC5-2-u4-X34"},{"t":"모둠마다 집 크기를 다르게 한다","mis":"SC5-2-u4-X31"},{"t":"탐침 끝을 바닥에 닿게 해 다시 잰다","mis":"SC5-2-u4-X32"}],"explanation":["되풀이해요.","조건을 같게 해요.","함께 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_d#24','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C10',4,'mc','auto','재생 에너지의 좋은 점과 한계를 모두 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-2-u4-X19','SC5-2-u4-X20','SC5-2-u4-X21']::text[],false,'{"seq":24,"concept":"SC5-2-u4-C10","difficulty":4,"kind":"mc","stem":"재생 에너지의 좋은 점과 한계를 모두 바르게 말한 것은 어느 것인가요?","options":[{"t":"계속 얻고 오염이 적지만, 날씨에 따라 양이 달라지고 비용이 많이 들어 기술 발전이 필요하다","correct":true},{"t":"한계는 하나도 없고 좋은 점만 있다","mis":"SC5-2-u4-X19"},{"t":"쓸수록 줄어들고 오염도 많이 낸다","mis":"SC5-2-u4-X20"},{"t":"석유처럼 묻힌 양이 정해져 있다","mis":"SC5-2-u4-X21"}],"explanation":["좋은 점이 있어요.","한계도 있어요.","기술이 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u4_review_d#25','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C20',4,'mc','auto','누리반의 실천 영상을 본 섬 주민이 함께 실천하게 하려면 어떻게 하는 것이 가장 알맞은가요?',ARRAY['SC5-2-u4-X38','SC5-2-u4-X39','SC5-2-u4-X37']::text[],false,'{"seq":25,"concept":"SC5-2-u4-C20","difficulty":4,"kind":"mc","stem":"누리반의 실천 영상을 본 섬 주민이 함께 실천하게 하려면 어떻게 하는 것이 가장 알맞은가요?","options":[{"t":"주민들이 쉽게 따라 할 수 있는 실천을 보여 주고, 함께해 보자고 권하는 말을 넣는다","correct":true},{"t":"주민의 이름과 집을 영상에 크게 보여 준다","mis":"SC5-2-u4-X38"},{"t":"한 번 올리고 다시는 실천하지 않는다","mis":"SC5-2-u4-X39"},{"t":"섬 생활과 상관없는 장면을 넣는다","mis":"SC5-2-u4-X37"}],"explanation":["따라 하기 쉬워요.","함께하자고 해요.","실천이 퍼져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
